insert into questions(id,level,difficulty,tags,image,situation,options,answer,spell,legal,source) values
(1,1,1,ARRAY['mat-khau']::text[],'img/matkhau-1.svg','Mèo Mít đặt mật khẩu game là "meomit123". Cún Bông khen: "Dễ nhớ ghê, cho tớ mượn nhé!". Mèo Mít nên làm gì?','["Viết mật khẩu lên bảng lớp để khỏi quên", "Cho mượn nhưng bắt Cún Bông hứa không kể ai", "Cho Cún Bông mượn vì bạn thân thì không sao", "Không cho ai biết mật khẩu, kể cả bạn thân, và đổi sang mật khẩu khó đoán hơn"]'::jsonb,3,'Mật khẩu của em, giữ kín như kem!','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(2,1,1,ARRAY['mat-khau']::text[],'img/matkhau-2.svg','Tí dán tờ giấy ghi mật khẩu ngay trên màn hình máy tính "cho tiện". Điều gì có thể xảy ra?','["Ai đi ngang qua cũng đọc được và đăng nhập vào tài khoản của Tí", "Chỉ mèo mới đọc được giấy dán", "Mật khẩu sẽ tự đổi sau 1 ngày", "Không sao vì máy tính biết chủ nhân là Tí"]'::jsonb,0,'Mật khẩu dán màn hình, kẻ gian mừng thình lình.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(3,1,1,ARRAY['nguoi-la']::text[],'img/nguoila.svg','Một người lạ trong game nhắn: "Em dễ thương quá, cho anh xin địa chỉ nhà để gửi quà nhé!". Tí nên làm gì?','["Không trả lời, không cho địa chỉ, kể ngay với bố mẹ", "Cho địa chỉ trường thay vì địa chỉ nhà", "Hỏi quà gì rồi mới quyết định", "Cho địa chỉ nhà hàng xóm cho chắc"]'::jsonb,0,'Người lạ hỏi nhà, chạy về hỏi ba!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(4,1,1,ARRAY['nguoi-la']::text[],'img/nguoila.svg','Cún Bông nhận tin nhắn: "Đây là bí mật của hai đứa mình thôi, đừng kể bố mẹ nhé!". Cún Bông nên nghĩ gì?','["Đợi tới sinh nhật rồi mới kể", "Kể cho mỗi bạn mèo hàng xóm thôi", "Bí mật khiến mình sợ không phải bí mật cần giữ – kể ngay với người lớn tin cậy", "Giữ bí mật vì đã hứa rồi"]'::jsonb,2,'Bí mật làm sợ, kể ngay đừng ngợ!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(5,1,1,ARRAY['anh-rieng-tu']::text[],'img/anhrieng.svg','Tí chụp ảnh cả lớp đang ngủ gật và muốn đăng lên mạng cho "vui". Tí nên làm gì?','["Đăng lúc nửa đêm để ít người xem", "Đăng rồi xóa sau 5 phút", "Đăng nhưng dán sticker lên mặt một bạn", "Không đăng khi các bạn chưa đồng ý"]'::jsonb,3,'Ảnh bạn đẹp ghê, hỏi bạn rồi hẵng khoe!','Điểm b khoản 2 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(6,1,1,ARRAY['link-la']::text[],'img/linkla-2.svg','Mèo Mít nhận tin nhắn: "Bấm vào đây nhận 1 triệu kim cương miễn phí!!!". Mèo Mít nên làm gì?','["Gửi cho cả lớp cùng nhận", "Bấm thử một lần thôi", "Không bấm, hỏi bố mẹ hoặc thầy cô", "Bấm bằng điện thoại của mẹ cho an toàn"]'::jsonb,2,'Quà free bấm vội, coi chừng gặp tội!','Khoản 1 Điều 17 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(7,1,1,ARRAY['link-la']::text[],'img/linkla-1.svg','Máy tính báo: "Máy bạn có 99 con virus! Tải ngay phần mềm diệt virus này!". Tí nên làm gì?','["Rút điện máy tính rồi cắm lại và tải", "Tải ngay kẻo virus lây sang Tí", "Không tải, đóng trang và nhờ người lớn kiểm tra", "Bấm \"Đồng ý\" thật nhanh nhiều lần"]'::jsonb,2,'Máy hù có virus, đừng tải, gọi người lớn nha!','Khoản 1 Điều 17 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(8,1,1,ARRAY['tin-gia']::text[],'img/tingia.svg','Cún Bông đọc tin: "Ngày mai trường nghỉ học vì có khủng long!". Cún Bông muốn chia sẻ ngay. Nên làm gì?','["Hỏi thầy cô hoặc bố mẹ trước, không chia sẻ tin chưa kiểm chứng", "Đăng thêm ảnh khủng long cho thật", "Chia sẻ ngay cho bạn bè được nghỉ", "Chia sẻ kèm chữ \"nghe nói thôi nha\""]'::jsonb,0,'Tin lạ chưa tường, đừng vội share đường!','Điểm d khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Nghị định 328/2026/NĐ-CP (phòng, chống tin giả, tin sai sự thật)','ORIGINAL'),
(9,1,1,ARRAY['bat-nat']::text[],'img/batnat-1.svg','Trong nhóm chat lớp, các bạn chế ảnh Tí thành con heo và cười ầm. Mèo Mít nên làm gì?','["Thả \"haha\" cho hòa đồng", "Không thả \"haha\", không chia sẻ tiếp, báo thầy cô", "Chế thêm ảnh khác cho vui hơn", "Im lặng rời nhóm và quên đi"]'::jsonb,1,'Bạn bị chế ảnh, không cười, báo thầy nhanh!','Điểm c khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(10,1,1,ARRAY['bat-nat']::text[],'img/batnat.svg','Mèo Mít bị trêu chọc trên mạng và thấy rất buồn. Mèo Mít nên làm gì?','["Xóa hết tài khoản và không nói với ai", "Tự chịu đựng vì kể ra sẽ bị cười", "Kể với bố mẹ, thầy cô hoặc gọi Tổng đài 111", "Trêu lại thật nặng"]'::jsonb,2,'Buồn thì đừng giấu, một một một luôn thấu!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(11,1,1,ARRAY['tai-khoan']::text[],'img/taikhoan-1.svg','Tí mới 9 tuổi, muốn có tài khoản mạng xã hội riêng. Ai nên đăng ký cho Tí?','["Không ai cả, cứ dùng tài khoản của anh họ", "Bố mẹ đăng ký bằng tên bố mẹ và trông chừng Tí", "Tí tự đăng ký và khai tăng tuổi", "Bạn lớp trên đăng ký hộ"]'::jsonb,1,'Lên mạng còn bé, bố mẹ cầm lái nhé!','Khoản 2 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(12,1,1,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-2.svg','Một trang web đố vui hỏi: "Nhập tên, số nhà, trường và số điện thoại của mẹ để biết bạn là siêu nhân nào!". Tí nên làm gì?','["Nhập thông tin của bạn thân", "Nhập hết vì muốn biết là siêu nhân nào", "Không nhập thông tin cá nhân, hỏi bố mẹ", "Chỉ nhập số điện thoại của bố"]'::jsonb,2,'Đố vui đòi nhà, đừng nhập, hỏi mẹ cha!','Điểm h khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm a khoản 2 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(13,1,1,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-2.svg','Đâu là thông tin cá nhân cần giữ kín, không đăng lên mạng?','["Địa chỉ nhà và số điện thoại", "Món ăn em thích nhất", "Màu yêu thích", "Tên con mèo trong phim hoạt hình"]'::jsonb,0,'Số nhà số điện, giữ kín như tiền!','Khoản 1 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Điểm a khoản 2 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(14,1,1,ARRAY['nguoi-la']::text[],'img/nguoila-1.svg','Bạn mới quen trong game rủ Cún Bông gặp nhau ở công viên, "đừng nói với ai nhé". Cún Bông nên làm gì?','["Đi nhưng mang theo ô", "Rủ thêm một bạn nhỏ đi cùng", "Đi một mình cho bí mật", "Không đi, kể với bố mẹ ngay"]'::jsonb,3,'Bạn mạng rủ đi, kể mẹ đã rồi tính gì!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(15,1,1,ARRAY['webcam']::text[],'img/webcam.svg','Người lạ gọi video và bảo Tí: "Bật camera lên cho anh xem phòng em nào". Tí nên làm gì?','["Hỏi người đó tên gì trước", "Bật một chút rồi tắt", "Bật camera hướng lên trần nhà", "Tắt cuộc gọi, chặn và kể với người lớn"]'::jsonb,3,'Người lạ đòi xem phòng, tắt máy là xong!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(16,1,2,ARRAY['ban-quyen']::text[],'img/banquyen.svg','Mèo Mít thấy bức tranh rất đẹp trên mạng, muốn đăng lại và ghi "Tranh của tớ vẽ". Như vậy có đúng không?','["Không đúng – phải ghi rõ tác giả, không nhận của người khác là của mình", "Đúng, vì tranh đã có trên mạng là của chung", "Đúng nếu tô thêm một màu", "Đúng nếu đăng lúc ít người xem"]'::jsonb,0,'Tranh người ta vẽ, ghi tên tác giả mới đẹp!','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(17,1,1,ARRAY['game']::text[],'img/game.svg','Cún Bông chơi game tới 11 giờ đêm, mắt đỏ như thỏ. Lời khuyên nào đúng nhất?','["Đặt giờ chơi hợp lý với bố mẹ và đi ngủ đúng giờ", "Chơi tiếp để lên cấp nhanh hơn", "Chơi dưới chăn để bố mẹ không biết", "Uống nước ngọt cho tỉnh táo"]'::jsonb,0,'Chơi game đúng giờ, ngủ ngon mơ thơ!','Khoản 2 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(18,1,1,ARRAY['link-la']::text[],'img/linkla-1.svg','Một tin nhắn từ số lạ: "Con của bạn đã trúng thưởng xe đạp, bấm link điền thông tin". Tí đọc được trên máy mẹ. Tí nên?','["Bấm giúp mẹ cho nhanh", "Chuyển tiếp cho bố", "Trả lời \"Có ạ!\"", "Đưa mẹ xem và nhắc mẹ không bấm link lạ"]'::jsonb,3,'Trúng thưởng bất ngờ, đưa mẹ coi giờ!','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(19,1,1,ARRAY['bao-cao']::text[],'img/baocao-1.svg','Gặp nội dung đáng sợ trên mạng, 5 "nút" cần nhớ là gì?','["Chụp lại – Gửi cả lớp – Đăng – Câu like – Xóa", "Tắt máy – Ngủ – Quên – Không kể – Chơi tiếp", "Dừng – Không lan truyền – Lưu bằng chứng – Báo cáo – Chia sẻ với người tin cậy", "Xem tiếp – Chia sẻ – Bình luận – Thả tim – Quên"]'::jsonb,2,'Dừng, Lưu, Báo, Kể – năm nút nhớ dễ!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(20,1,1,ARRAY['bao-cao']::text[],'img/baocao.svg','Số điện thoại Tổng đài quốc gia bảo vệ trẻ em là gì?','["115", "111", "113", "114"]'::jsonb,1,'Một một một, gọi là có người lo!','Khoản 3 Điều 51 Luật Trẻ em số 102/2016/QH13; Điều 22, Điều 23 Nghị định 56/2017/NĐ-CP; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(21,1,1,ARRAY['mat-khau']::text[],'img/matkhau-2.svg','Mật khẩu nào an toàn nhất cho tài khoản của Tí?','["123456", "tiyeumeo", "Mot_Con-Vit!Xoe2CanhVang", "ngày sinh của Tí"]'::jsonb,2,'Mật khẩu dài dài, kẻ gian chịu thua hoài!','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(22,1,1,ARRAY['anh-rieng-tu']::text[],'img/anhrieng-2.svg','Bố đăng ảnh Cún Bông tắm bồn lên mạng. Cún Bông thấy ngại. Cún Bông nên làm gì?','["Nói với bố rằng mình không thích và xin bố gỡ ảnh", "Im lặng vì bố là người lớn", "Đăng lại ảnh bố ngủ ngáy để trả đũa", "Khóa tài khoản của bố"]'::jsonb,0,'Ảnh em ngại ngùng, nói bố gỡ chung!','Khoản 2 Điều 24 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 1 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(23,1,1,ARRAY['tin-gia']::text[],'img/tingia-1.svg','Trên mạng có video "Ăn 10 cái kẹo mỗi ngày sẽ cao thêm 10cm". Mèo Mít nên?','["Không tin ngay, hỏi thầy cô, bố mẹ", "Ăn ngay 20 cái cho cao gấp đôi", "Mua kẹo cho cả nhà", "Chia sẻ cho cả lớp cùng cao"]'::jsonb,0,'Video lạ tai, hỏi người lớn liền tay!','Điểm d khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(24,1,1,ARRAY['nguoi-la']::text[],'img/nguoila.svg','Một tài khoản tự xưng là "thầy giáo mới" nhắn riêng, xin ảnh và địa chỉ của Tí. Tí nên?','["Hỏi lại thầy cô chủ nhiệm và bố mẹ, không gửi gì", "Gửi ngay vì là thầy giáo", "Gửi địa chỉ nhưng không gửi ảnh", "Gửi ảnh nhưng không gửi địa chỉ"]'::jsonb,0,'Xưng thầy trên mạng, hỏi thầy thật cho sáng!','Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(25,1,2,ARRAY['ai-deepfake']::text[],'img/deepfake-2.svg','Cún Bông thấy video "chú mèo nói tiếng người, kêu gọi các bạn chuyển tiền mua cá". Đây có thể là gì?','["Phim hoạt hình chính thức của trường", "Video giả do máy tính tạo ra để lừa người xem", "Chú mèo thông minh thật", "Tin tức nghiêm túc"]'::jsonb,1,'Mèo nói xin tiền, video giả liền!','Điểm g khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(26,1,1,ARRAY['tai-khoan']::text[],'img/taikhoan-1.svg','Mèo Mít dùng máy tính ở thư viện, xong việc thì đi về luôn. Mèo Mít quên làm gì?','["Chỉnh ghế", "Đăng xuất tài khoản", "Tắt màn hình", "Lau bàn phím"]'::jsonb,1,'Máy chung dùng xong, đăng xuất cho xong!','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(27,1,1,ARRAY['bat-nat']::text[],'img/batnat.svg','Tí lỡ gửi tin nhắn chê bai bạn trong nhóm, giờ thấy hối hận. Tí nên làm gì?','["Rời nhóm và giả vờ không biết", "Gửi thêm tin để chữa cháy bằng chê người khác", "Đổ cho em trai gửi", "Dừng lại, xóa tin và xin lỗi bạn"]'::jsonb,3,'Lỡ lời làm buồn, xin lỗi bạn luôn!','Điểm c khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(28,1,1,ARRAY['game']::text[],'img/game.svg','Trong game, người lạ tặng Cún Bông nhiều vật phẩm rồi bảo "giờ em gửi ảnh cho anh nhé". Cún Bông nên?','["Gửi ảnh của bạn khác", "Từ chối, chặn người đó và kể với người lớn", "Gửi ảnh vì đã nhận quà rồi", "Trả lại vật phẩm rồi gửi ảnh"]'::jsonb,1,'Quà game đổi ảnh, chặn ngay cho nhanh!','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình); Khoản 6 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(29,1,1,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Lớp có danh sách học sinh kèm số điện thoại phụ huynh. Mèo Mít muốn đăng công khai lên trang cá nhân. Có nên không?','["Không, vì đó là thông tin cá nhân của người khác", "Có, cho các bạn dễ liên lạc", "Có, vì danh sách là của lớp", "Có, nếu chỉ đăng một nửa"]'::jsonb,0,'Số bạn số nhà, không đăng ra ngoài nha!','Điểm b khoản 2 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 7 Điều 7 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(30,1,1,ARRAY['link-la']::text[],'img/linkla-1.svg','USB nhặt được ở sân trường có ghi "Đáp án kiểm tra". Tí nên làm gì?','["Không cắm vào máy, nộp cho thầy cô", "Cắm vào máy xem ngay", "Cắm vào máy của bạn cho an toàn", "Mang về nhà cắm vào máy bố"]'::jsonb,0,'USB nhặt được, nộp thầy là được!','Khoản 1 Điều 17 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(31,1,1,ARRAY['tin-gia']::text[],'img/tingia.svg','Mèo Mít nghe tin đồn "bạn Na bị bệnh lây, đừng chơi với Na" trong nhóm chat. Mèo Mít nên?','["Chia sẻ để cảnh báo mọi người", "Không lan truyền, hỏi thầy cô và bênh vực bạn", "Rời xa bạn Na ngay", "Thêm chi tiết cho câu chuyện hấp dẫn"]'::jsonb,1,'Tin đồn làm đau, dừng lại ở đâu? Ở mình!','Điểm c khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(32,1,1,ARRAY['webcam']::text[],'img/webcam-1.svg','Khi không học online, nên làm gì với camera máy tính?','["Tắt hoặc che camera lại", "Dán sticker hình mặt cười lên màn hình", "Luôn bật để tiện", "Hướng camera ra cửa sổ"]'::jsonb,0,'Học xong che cam, kẻ xấu hết nhòm!','Điểm c khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(33,1,1,ARRAY['mua-sam']::text[],'img/muasam-2.svg','Cún Bông thấy quảng cáo game: "Nhập số thẻ ngân hàng của bố để nhận skin miễn phí". Nên làm gì?','["Nhập một nửa số thẻ", "Nhập số thẻ của mẹ thay vì bố", "Lấy thẻ bố nhập nhanh", "Không nhập, báo bố mẹ"]'::jsonb,3,'Miễn phí đòi thẻ, lừa đảo đó nhé!','Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(34,1,2,ARRAY['mat-khau']::text[],'img/matkhau-1.svg','Tí dùng chung một mật khẩu cho tất cả tài khoản. Nếu một tài khoản bị lộ thì sao?','["Máy tính sẽ tự đổi mật khẩu", "Chỉ tài khoản đó bị ảnh hưởng", "Kẻ xấu có thể mở được tất cả tài khoản khác", "Không sao vì mật khẩu dài"]'::jsonb,2,'Một mật khẩu dùng chung, mất là mất tung!','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(35,1,1,ARRAY['nguoi-la']::text[],'img/nguoila-2.svg','Ai là người Tí nên tìm khi gặp chuyện không ổn trên mạng?','["Một tài khoản ẩn danh", "Người lạ trong game", "Bố mẹ, thầy cô hoặc người lớn tin cậy", "Không ai cả, tự xử lý"]'::jsonb,2,'Gặp chuyện trên mạng, người lớn giúp sáng!','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình); Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(36,1,1,ARRAY['anh-rieng-tu']::text[],'img/anhrieng-2.svg','Cún Bông muốn gửi ảnh mặc đồ ngủ cho "bạn mới quen trên mạng". Nên làm gì?','["Gửi ảnh mờ thôi", "Không gửi ảnh riêng tư cho ai trên mạng", "Gửi vì bạn khen dễ thương", "Gửi rồi bảo bạn xóa"]'::jsonb,1,'Ảnh riêng của em, không gửi ai xem!','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình); Điểm a khoản 2 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(37,1,1,ARRAY['bao-cao']::text[],'img/baocao-2.svg','Khi bị người lạ nhắn tin đe dọa, điều gì KHÔNG nên làm?','["Xóa hết tin nhắn và giấu không cho ai biết", "Chặn và báo cáo tài khoản", "Kể với bố mẹ", "Chụp màn hình lưu bằng chứng"]'::jsonb,0,'Bị dọa đừng xóa, kể ra là khỏe!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(38,1,1,ARRAY['ban-quyen']::text[],'img/banquyen-1.svg','Mèo Mít tải phim lậu trên trang lạ để xem miễn phí. Rủi ro là gì?','["Phim sẽ hay hơn", "Vi phạm bản quyền và dễ dính phần mềm độc hại", "Máy sẽ chạy nhanh hơn", "Không có rủi ro gì"]'::jsonb,1,'Phim lậu xem chùa, virus kéo vô cửa!','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Khoản 1 Điều 17 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(39,1,1,ARRAY['tai-khoan']::text[],'img/taikhoan-1.svg','Có người nhắn: "Mình là quản trị game, cho mình mã đăng nhập (OTP) để tặng quà". Tí nên?','["Đưa một nửa mã", "Đưa ngay để nhận quà", "Hỏi tên rồi đưa", "Không đưa mã OTP cho bất kỳ ai"]'::jsonb,3,'Mã OTP, không đưa ai hết nghe!','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15; Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(40,1,1,ARRAY['game']::text[],'img/game.svg','Bạn rủ Tí vào nhóm "hack game, có tiền thật". Tí nên?','["Tham gia để giàu nhanh", "Rủ thêm bạn để chia tiền", "Tham gia nhưng không nói ai", "Từ chối vì hack game là xâm nhập trái phép, có thể bị lừa"]'::jsonb,3,'Hack game có tiền, lừa mình liền liền!','Khoản 5 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(41,1,1,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Một ứng dụng vẽ tranh xin quyền đọc danh bạ và vị trí. Mèo Mít nên?','["Cài thêm 3 ứng dụng nữa", "Cấp danh bạ, không cấp vị trí", "Hỏi bố mẹ, không cấp quyền không cần thiết", "Cấp hết cho nhanh"]'::jsonb,2,'App xin quyền lạ, hỏi bố mẹ đã!','Điểm b khoản 3 Điều 31 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 1 Điều 29 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(42,1,1,ARRAY['bat-nat']::text[],'img/batnat.svg','Bạn Bin bị cả nhóm tẩy chay trên mạng. Cún Bông có thể giúp gì?','["Nhắn hỏi thăm Bin và báo thầy cô", "Cùng tẩy chay cho an toàn", "Không làm gì vì không phải việc của mình", "Chụp lại để gửi nhóm khác cười"]'::jsonb,0,'Bạn bị tẩy chay, mình giúp bạn ngay!','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình); Khoản 4 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(43,1,1,ARRAY['tin-gia']::text[],'img/tingia-1.svg','Video "uống nước rửa chén sẽ thông minh hơn" đang lan truyền. Tí nên?','["Rủ bạn thử chung", "Chia sẻ cảnh báo kèm lời “thử xem”", "Không làm theo, không chia sẻ và báo người lớn", "Thử một ngụm"]'::jsonb,2,'Clip làm liều, không theo không share nhiều!','Điểm d khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Nghị định 328/2026/NĐ-CP (phòng, chống tin giả, tin sai sự thật)','ORIGINAL'),
(44,1,1,ARRAY['webcam']::text[],'img/webcam.svg','Tí học online, nhóm lớp bảo bật camera. Một người lạ vào phòng học online. Tí nên?','["Trò chuyện với người lạ", "Báo thầy cô ngay để mời người lạ ra", "Gửi link phòng cho người lạ khác", "Tắt mic và mặc kệ"]'::jsonb,1,'Người lạ vào lớp, báo thầy cô kịp!','Khoản 3 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(45,1,2,ARRAY['link-la']::text[],'img/linkla-1.svg','Email "Từ: Hiệu trưởng" nhưng địa chỉ là thaihieutruong99@abcxyz.top, yêu cầu tải file "diem.exe". Tí nên?','["Mở bằng điện thoại", "Không mở file, báo thầy cô", "Chuyển cho bạn mở trước", "Tải về xem điểm"]'::jsonb,1,'File lạ đuôi exe, không mở nghe!','Khoản 1 Điều 17 Luật An ninh mạng số 116/2025/QH15; Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(46,1,1,ARRAY['mat-khau']::text[],'img/matkhau.svg','Mẹ hỏi mật khẩu tài khoản học tập của Tí để giúp Tí. Có được nói không?','["Nói với người lạ trong game", "Không bao giờ nói với ai, kể cả bố mẹ", "Được nói với bố mẹ – người giám hộ, nhưng không nói với người khác", "Nói với bạn thân trước"]'::jsonb,2,'Mật khẩu của con, bố mẹ biết thì còn!','Khoản 2 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(47,1,1,ARRAY['mua-sam']::text[],'img/muasam-2.svg','Tí thấy quảng cáo "Điện thoại xịn chỉ 10.000 đồng, chuyển khoản trước". Nên nghĩ gì?','["Mua 10 cái tặng cả lớp", "Chuyển tiền của heo đất", "Rẻ bất thường – có thể là lừa đảo", "Mua ngay kẻo hết"]'::jsonb,2,'Rẻ quá hóa lừa, chuyển tiền thì thua!','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(48,1,1,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-1.svg','Cún Bông đăng ảnh check-in kèm "đang ở nhà một mình". Có vấn đề gì?','["Ảnh sẽ được nhiều tim hơn", "Kẻ xấu biết em ở đâu và đang ở một mình", "Không có vấn đề gì", "Bạn bè sẽ tới chơi"]'::jsonb,1,'Ở nhà một mình, đừng khoe linh tinh!','Khoản 1 Điều 31 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Điểm a khoản 2 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(49,1,1,ARRAY['ai-deepfake']::text[],'img/deepfake.svg','Tí nhận cuộc gọi video giống hệt mẹ, nói: "Con gửi mã số trên thẻ của bố cho mẹ". Tí nên?','["Hỏi mẹ ăn cơm chưa rồi gửi", "Cúp máy, gọi lại cho mẹ bằng số quen để hỏi", "Gửi cho bố trước", "Gửi ngay vì đúng là mặt mẹ"]'::jsonb,1,'Giọng mẹ trên mạng, gọi lại cho sáng!','Điểm g khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(50,1,1,ARRAY['game']::text[],'img/game-2.svg','Tí bị "mất nick" game. Ai đó đòi tiền để trả lại. Tí nên?','["Hack lại tài khoản kẻ đó", "Đăng lên mạng chửi kẻ đó", "Chuyển tiền ngay", "Báo bố mẹ, không chuyển tiền, báo nhà phát hành game"]'::jsonb,3,'Mất nick đòi tiền, báo bố mẹ liền!','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Khoản 3 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(51,1,1,ARRAY['nguoi-la']::text[],'img/nguoila-2.svg','Lời mời kết bạn từ "Siêu nhân Gao Đỏ chính hãng". Mèo Mít nên?','["Kết bạn cả Gao Xanh", "Chấp nhận rồi hỏi số điện thoại", "Chấp nhận ngay vì thích Gao Đỏ", "Không chấp nhận người lạ, dù tên nghe vui"]'::jsonb,3,'Siêu nhân trên mạng, người lạ đó bạn!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(52,2,1,ARRAY['tin-gia']::text[],'img/tingia-2.svg','Nhóm lớp lan truyền "Mai thi học kỳ bị hoãn, nguồn: tin chuẩn 100%". Không ai biết ai đăng đầu tiên. Bạn nên?','["Chia sẻ thêm vào 5 nhóm khác cho chắc", "Chia sẻ vì \"tin chuẩn 100%\"", "Nghỉ ôn bài luôn", "Kiểm tra trên kênh chính thức của trường trước khi tin hay chia sẻ"]'::jsonb,3,'“Chuẩn 100%” mà không nguồn = 0% đáng tin.','Điểm d khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Nghị định 328/2026/NĐ-CP (phòng, chống tin giả, tin sai sự thật)','ORIGINAL'),
(53,2,2,ARRAY['bat-nat']::text[],'img/batnat.svg','Tí lập "page confession" đăng chuyện xấu bịa về bạn cùng lớp cho vui. Hành vi này là?','["Bịa đặt, xúc phạm danh dự người khác – bị nghiêm cấm", "Quyền tự do sáng tác", "Hợp pháp nếu ẩn danh", "Đùa vui vô hại"]'::jsonb,0,'Ẩn danh không phải áo tàng hình trước pháp luật.','Điểm c khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm d khoản 3 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(54,2,2,ARRAY['anh-rieng-tu']::text[],'img/anhrieng.svg','Bạn gửi riêng cho Mèo Mít ảnh nhạy cảm của một bạn khác, kèm "xem xong xóa nhé". Mèo Mít nên?','["Xem rồi xóa là xong", "Không xem, không chuyển tiếp, báo người lớn tin cậy", "Chuyển cho một người thôi", "Lưu lại phòng khi cần"]'::jsonb,1,'Mỗi lượt chuyển là thêm một vết thương.','Điểm c khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(55,2,2,ARRAY['deepfake']::text[],'img/deepfake-1.svg','Nhóm bạn dùng app AI ghép mặt cô giáo vào clip nhảy múa hài rồi đăng lên TikTok. Đánh giá?','["Hợp pháp nếu có chữ \"AI\"", "Dùng AI giả mạo hình ảnh người khác trái luật là hành vi bị nghiêm cấm", "Chỉ là sáng tạo nội dung", "Không sao nếu cô không biết"]'::jsonb,1,'Ghép mặt người khác – ghép luôn rắc rối pháp lý.','Điểm g khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm h khoản 3 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(56,2,1,ARRAY['tai-khoan']::text[],'img/taikhoan-2.svg','Bạn rủ "cho mượn tài khoản ngân hàng của mẹ để nhận tiền hộ, được trả 200k". Cún Bông nên?','["Đồng ý một lần thôi", "Từ chối – cho mượn, mua bán tài khoản ngân hàng là trái luật", "Hỏi mẹ mượn thẻ lén", "Đồng ý vì có tiền"]'::jsonb,1,'Cho thuê tài khoản = thuê luôn rắc rối.','Điểm g khoản 4 Điều 13 Luật An ninh mạng số 116/2025/QH15; Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(57,2,1,ARRAY['link-la']::text[],'img/linkla-1.svg','Tin nhắn Facebook từ bạn thân: "Bình chọn giúp tớ nhé!" kèm link yêu cầu đăng nhập Facebook lần nữa. Bạn nên?','["Không đăng nhập, gọi hỏi bạn – có thể tài khoản bạn đã bị chiếm", "Đăng nhập để giúp bạn", "Đăng nhập bằng tài khoản phụ", "Gửi link cho cả lớp bình chọn"]'::jsonb,0,'Link đòi đăng nhập lại – dấu hiệu câu “cá”.','Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm c khoản 1 Điều 18 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(58,2,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-2.svg','App "xem ai vào trang cá nhân bạn" đòi tên đăng nhập và mật khẩu Facebook. Tí nên?','["Cung cấp vì tò mò", "Không cung cấp, đây là chiêu thu thập dữ liệu trái phép", "Cung cấp tài khoản của bạn khác", "Cung cấp rồi đổi mật khẩu sau 1 tháng"]'::jsonb,1,'Tò mò ai xem mình – kẻ gian đang xem mình!','Điểm h khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(59,2,2,ARRAY['bat-nat']::text[],'img/batnat-2.svg','Tí bị nhắn tin xúc phạm liên tục. Bước nào là ĐÚNG để lưu bằng chứng?','["Chỉnh ảnh cho rõ ràng hơn", "Xóa tin để quên", "Chửi lại rồi chụp", "Chụp màn hình có thời gian, tài khoản gửi, không chỉnh sửa"]'::jsonb,3,'Bằng chứng nguyên vẹn – bảo vệ chính mình.','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(60,2,1,ARRAY['tin-gia']::text[],'img/tingia-2.svg','Bài đăng "Uống 3 lít nước chanh mỗi sáng chữa khỏi mọi bệnh" có 1 triệu like. Nhiều like có nghĩa là?','["Chắc chắn đúng", "Đúng một nửa", "Đúng nếu bác sĩ like", "Không có nghĩa là đúng – cần kiểm chứng nguồn y tế tin cậy"]'::jsonb,3,'Like nhiều không thay được bằng chứng.','Điểm d khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Nghị định 328/2026/NĐ-CP (phòng, chống tin giả, tin sai sự thật)','ORIGINAL'),
(61,2,2,ARRAY['ban-quyen']::text[],'img/banquyen.svg','Mèo Mít đăng lại nguyên video của YouTuber khác lên kênh mình để kiếm tiền. Đây là?','["Hợp pháp vì video đã công khai", "Được phép nếu thêm nhạc", "Hợp pháp nếu đổi tiêu đề", "Vi phạm bản quyền trên không gian mạng"]'::jsonb,3,'Copy-paste kiếm tiền = copy-paste rắc rối.','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(62,2,1,ARRAY['game']::text[],'img/game-2.svg','Trang web "cá cược game, nạp 50k ăn 500k" mời Tí tham gia. Đúng hay sai?','["Đúng vì chỉ là game", "Sai – tổ chức, tham gia đánh bạc qua mạng là bị nghiêm cấm", "Đúng nếu nạp ít", "Đúng nếu thắng"]'::jsonb,1,'“Nạp ít ăn nhiều” – thường là ăn sạch.','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(63,2,2,ARRAY['anh-rieng-tu']::text[],'img/anhrieng-2.svg','Người quen qua mạng dọa: "Không gửi thêm ảnh thì tao phát tán ảnh cũ". Bạn nên làm gì?','["Gửi thêm để họ im", "Dừng liên lạc, không gửi thêm, lưu bằng chứng, báo người lớn/công an", "Trả tiền cho họ", "Tự tìm nhà họ để nói chuyện"]'::jsonb,1,'Bị dọa ảnh – không gửi, không trả, báo ngay!','Điểm c khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(64,2,1,ARRAY['mat-khau']::text[],'img/matkhau.svg','Tính năng nào giúp tài khoản an toàn hơn ngay cả khi lộ mật khẩu?','["Đăng nhiều bài", "Xác thực hai yếu tố (2FA)", "Đặt tên tài khoản dài", "Ảnh đại diện đẹp"]'::jsonb,1,'Hai lớp khóa – kẻ gian bó tay.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(65,2,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-2.svg','Một nhóm Zalo bán "danh sách số điện thoại học sinh cả trường". Việc mua bán này?','["Được phép nếu dùng để quảng cáo", "Hợp pháp nếu giá rẻ", "Bị nghiêm cấm – mua bán dữ liệu cá nhân trái luật", "Hợp pháp vì số điện thoại ai cũng có"]'::jsonb,2,'Dữ liệu người khác không phải món hàng.','Khoản 6 Điều 7 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Điểm h khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(66,2,1,ARRAY['bat-nat']::text[],'img/batnat-2.svg','Bạn thấy livestream đánh nhau của học sinh trường mình. Hành động đúng?','["Không chia sẻ, báo cáo nội dung và báo thầy cô", "Bình luận cổ vũ", "Share ngay để mọi người biết", "Tải về lưu làm kỷ niệm"]'::jsonb,0,'Share bạo lực = tiếp tay bạo lực.','Điểm d khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(67,2,2,ARRAY['deepfake']::text[],'img/deepfake.svg','Clip "giọng ca sĩ nổi tiếng" quảng cáo app vay tiền siêu nhanh. Bạn nên nghĩ gì?','["App chắc chắn uy tín", "Ca sĩ đã quảng cáo thật", "Có thể là giọng nói giả bằng AI để lừa đảo", "Vay thử 1 triệu"]'::jsonb,2,'Giọng quen chưa chắc người quen.','Điểm g khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(68,2,1,ARRAY['tai-khoan']::text[],'img/taikhoan-2.svg','Tài khoản của Tí bị kẻ xấu chiếm và dùng đi lừa bạn bè. Điều Tí nên làm đầu tiên?','["Đi lừa lại kẻ xấu", "Lập tài khoản mới và im lặng", "Báo bạn bè cảnh giác, khôi phục tài khoản và báo người lớn", "Kệ, không phải lỗi mình"]'::jsonb,2,'Mất nick – báo ngay cho bạn bè đừng mắc bẫy.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15; Khoản 3 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(69,2,2,ARRAY['tin-gia']::text[],'img/tingia.svg','Ảnh bão "khủng khiếp nhất lịch sử" đang lan truyền nhưng thật ra là ảnh từ phim. Người chia sẻ có thể bị gì?','["Có thể bị xử lý vì phát tán thông tin sai sự thật gây hoang mang", "Được thưởng vì cảnh báo sớm", "Chỉ người làm phim chịu trách nhiệm", "Không sao vì chỉ chia sẻ"]'::jsonb,0,'Share bừa – có thể bị phạt thật.','Điểm d khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Nghị định 328/2026/NĐ-CP (phòng, chống tin giả, tin sai sự thật); Nghị định 330/2026/NĐ-CP (xử phạt VPHC lĩnh vực an ninh mạng và bảo vệ dữ liệu cá nhân)','ORIGINAL'),
(70,2,1,ARRAY['link-la']::text[],'img/linkla-2.svg','Tin nhắn "Tài khoản ngân hàng của bạn bị khóa, bấm link để mở" gửi tới máy mẹ. Bạn nên khuyên mẹ?','["Không bấm link, gọi tổng đài chính thức của ngân hàng", "Trả lời tin nhắn hỏi lý do", "Bấm và nhập mật khẩu nhanh", "Chuyển tiền sang tài khoản khác qua link"]'::jsonb,0,'Ngân hàng không nhắn link đòi mật khẩu.','Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(71,2,2,ARRAY['nguoi-la']::text[],'img/nguoila.svg','"Anh" quen qua game chuyển sang Telegram, khen Mèo Mít "trưởng thành hơn tuổi", dặn đừng kể ai. Đây là dấu hiệu?','["Anh ấy chỉ thân thiện", "Tình bạn đẹp", "Dụ dỗ trực tuyến – cần dừng lại và kể với người lớn", "Bình thường trên mạng"]'::jsonb,2,'Khen + bí mật + chuyển app = 3 đèn đỏ.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình); Khoản 6 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(72,2,1,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Bạn đăng ảnh thẻ học sinh có đầy đủ họ tên, ngày sinh, mã số. Rủi ro?','["Được nhiều bạn kết bạn", "Bị lợi dụng giả mạo danh tính", "Không có rủi ro", "Trường khen"]'::jsonb,1,'Ảnh giấy tờ lên mạng – danh tính bay đi.','Điểm a khoản 2 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Điểm g khoản 4 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(73,2,2,ARRAY['cookie']::text[],'img/cookie-2.svg','Trang web hỏi "Chấp nhận tất cả cookie?". Theo Luật BVDLCN, mạng xã hội phải cho bạn quyền gì?','["Bắt buộc chấp nhận", "Không có quyền gì", "Lựa chọn từ chối thu thập và chia sẻ cookie", "Chỉ được xem nếu chấp nhận"]'::jsonb,2,'Cookie không phải bánh – được quyền nói “không”.','Khoản 3 Điều 29 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(74,2,2,ARRAY['anh-rieng-tu']::text[],'img/anhrieng.svg','Tí đăng ảnh chụp lén bạn đang khóc trong nhà vệ sinh lên story. Đánh giá?','["Hợp pháp nếu không ghi tên", "Không sao nếu story 24h", "Xâm phạm đời sống riêng tư, danh dự của bạn", "Ghi lại khoảnh khắc thật"]'::jsonb,2,'Story 24 giờ – tổn thương có thể cả đời.','Điểm c khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Khoản 7 Điều 7 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(75,2,1,ARRAY['game']::text[],'img/game.svg','Trên nhóm game có người bán "tool hack" kèm file .exe. Nguy cơ?','["File có thể chứa mã độc, và hack game là hành vi trái luật", "Không nguy cơ gì", "Game sẽ chạy mượt hơn", "Được chơi miễn phí trọn đời"]'::jsonb,0,'Tool hack = hack ngược máy bạn.','Khoản 1 Điều 17 Luật An ninh mạng số 116/2025/QH15; Điểm đ khoản 1 Điều 18 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(76,2,2,ARRAY['bat-nat']::text[],'img/batnat-1.svg','Tí "chỉ like" một bài chế giễu bạn cùng lớp. Điều đó có ảnh hưởng không?','["Không, like thì vô hại", "Có – lượt tương tác giúp nội dung lan rộng, làm tổn thương thêm", "Chỉ comment mới ảnh hưởng", "Like là ủng hộ tự do ngôn luận"]'::jsonb,1,'Mỗi lượt like là thêm một cú đẩy.','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(77,2,1,ARRAY['mua-sam']::text[],'img/muasam-1.svg','Shop online yêu cầu "chuyển khoản cọc 100%, không giao COD, không cho xem hàng". Bạn nên?','["Chuyển gấp đôi để được ưu tiên", "Cho shop mã OTP để thanh toán", "Chuyển ngay kẻo hết hàng", "Cảnh giác, kiểm tra uy tín shop hoặc chọn kênh an toàn hơn"]'::jsonb,3,'Cọc 100% với shop lạ – rủi ro 100%.','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(78,2,2,ARRAY['deepfake']::text[],'img/deepfake.svg','Có người dùng ảnh trên Facebook của chị Tí để tạo tài khoản giả, mượn tiền họ hàng. Hành vi này?','["Chỉ là trùng tên", "Mạo danh, giả mạo hình ảnh cá nhân – vi phạm pháp luật", "Chỉ là trò đùa", "Hợp pháp vì ảnh công khai"]'::jsonb,1,'Mượn mặt người khác để mượn tiền = lừa đảo.','Điểm h khoản 3 Điều 13 Luật An ninh mạng số 116/2025/QH15; Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(79,2,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-2.svg','Mạng xã hội yêu cầu chụp ảnh căn cước của bạn để "xác thực tài khoản". Theo Luật BVDLCN?','["Luật không quy định", "Bắt buộc phải gửi", "Được gửi nếu là thẻ học sinh", "Nền tảng mạng xã hội không được yêu cầu ảnh, video chứa giấy tờ tùy thân để xác thực tài khoản"]'::jsonb,3,'Xác thực bằng ảnh căn cước – luật nói không.','Khoản 2 Điều 29 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(80,2,1,ARRAY['tin-gia']::text[],'img/tingia-1.svg','Bạn thấy bài "Cô hiệu trưởng bị bắt" không có nguồn. Lựa chọn tốt nhất?','["Không bình luận, không chia sẻ, chờ thông tin chính thức", "Đăng lên nhóm phụ huynh", "Chia sẻ kèm dấu chấm hỏi", "Bình luận \"thật không?\" để kéo tương tác"]'::jsonb,0,'Dấu chấm hỏi không làm tin giả thành vô tội.','Điểm c khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm d khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(81,2,2,ARRAY['bat-nat']::text[],'img/batnat-1.svg','Nhóm lớp tạo bình chọn "Bạn xấu nhất lớp". Mèo Mít là lớp trưởng nên làm gì?','["Bình chọn cho vui", "Đề nghị xóa bình chọn và báo giáo viên", "Chụp lại gửi nhóm khác", "Đề cử chính mình để đùa"]'::jsonb,1,'Bình chọn chê bai = bắt nạt có hệ thống.','Điểm c khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(82,2,1,ARRAY['mat-khau']::text[],'img/matkhau-2.svg','Wifi quán trà sữa miễn phí không mật khẩu. Bạn nên tránh làm gì khi dùng?','["Xem dự báo thời tiết", "Tra từ điển", "Đọc truyện tranh", "Đăng nhập ngân hàng hoặc nhập mật khẩu quan trọng"]'::jsonb,3,'Wifi miễn phí – đừng mở “két sắt”.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(83,2,2,ARRAY['link-la']::text[],'img/linkla-2.svg','File "Ảnh_kỷ_yếu.jpg.apk" gửi qua Zalo. Điều đáng ngờ là gì?','["Tên file quá dài", "Ảnh kỷ yếu luôn là apk", "Đuôi .apk là file cài ứng dụng, không phải ảnh – có thể là mã độc", "Không có gì đáng ngờ"]'::jsonb,2,'Ảnh mà đuôi .apk – ảnh… mã độc.','Khoản 1 Điều 17 Luật An ninh mạng số 116/2025/QH15; Điểm a khoản 1 Điều 18 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(84,2,2,ARRAY['ban-quyen']::text[],'img/banquyen-1.svg','Bạn mua 1 tài khoản xem phim rồi bán lại mật khẩu cho 50 người. Đánh giá?','["Hợp pháp vì đã trả tiền", "Không ai biết nên không sao", "Kinh doanh thông minh", "Vi phạm bản quyền, có thể bị xử lý"]'::jsonb,3,'Một tài khoản, năm mươi rắc rối.','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(85,2,1,ARRAY['nguoi-la']::text[],'img/nguoila.svg','Bạn được hẹn "phỏng vấn làm mẫu ảnh online, lương cao", yêu cầu gửi ảnh mặc đồ bơi. Bạn nên?','["Gửi ảnh bạn thân", "Gửi để có việc", "Gửi ảnh cũ", "Từ chối, báo người lớn – đây là chiêu dụ dỗ phổ biến"]'::jsonb,3,'Việc nhẹ lương cao + ảnh đồ bơi = bẫy.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình); Khoản 6 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(86,2,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-1.svg','Cô giáo dùng bảng điểm có tên học sinh để làm ví dụ công khai trên Facebook. Học sinh có quyền gì?','["Không có quyền gì", "Yêu cầu xóa hoặc hạn chế xử lý dữ liệu cá nhân của mình", "Chỉ được tự đăng bảng điểm của cô", "Chỉ được khiếu nại khi đủ 18 tuổi"]'::jsonb,1,'Dữ liệu của em – em có quyền lên tiếng.','Điểm d khoản 1 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 2 Điều 24 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(87,2,1,ARRAY['game']::text[],'img/game-1.svg','Tí nạp game bằng thẻ của bố mà không hỏi. Vấn đề là?','["Game sẽ hoàn tiền", "Dùng phương tiện thanh toán của người khác trái phép", "Không vấn đề vì là bố", "Chỉ sai nếu nạp nhiều"]'::jsonb,1,'Thẻ bố không phải ví của em.','Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(88,2,2,ARRAY['tin-gia']::text[],'img/tingia.svg','Bạn tự dựng video "trường có ma" để câu view, khiến nhiều bạn sợ không dám đi học. Đánh giá?','["Không sao nếu được nhiều view", "Đăng tin sai sự thật gây hoang mang – có thể bị xử lý", "Sáng tạo nội dung bình thường", "Hợp pháp vì là giải trí"]'::jsonb,1,'View tăng, rắc rối cũng tăng.','Điểm d khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Nghị định 328/2026/NĐ-CP (phòng, chống tin giả, tin sai sự thật)','ORIGINAL'),
(89,2,1,ARRAY['bao-cao']::text[],'img/baocao-2.svg','Thấy tài khoản đăng ảnh xâm hại trẻ em, bạn nên?','["Tải về làm bằng chứng gửi nhóm lớp", "Bình luận chửi", "Chia sẻ để cảnh báo", "Không chia sẻ, báo cáo nền tảng và báo công an/Tổng đài 111"]'::jsonb,3,'Báo cáo, đừng lan truyền.','Khoản 4 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(90,2,2,ARRAY['deepfake']::text[],'img/deepfake-2.svg','Bạn nhận tin nhắn thoại giống giọng bố: "Bố đang gấp, chuyển ngay 5 triệu vào số này". Cách xử lý?','["Chuyển ngay vì giọng giống", "Hỏi bố món ăn yêu thích qua tin nhắn đó", "Gọi lại bố hoặc người nhà qua số quen để xác minh", "Chuyển một nửa"]'::jsonb,2,'Giọng giống – xác minh trước, chuyển tiền sau (hoặc không).','Điểm g khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(91,2,1,ARRAY['anh-rieng-tu']::text[],'img/anhrieng.svg','Bạn có quyền yêu cầu người khác gỡ ảnh của mình họ đăng mà chưa hỏi không?','["Không, đăng rồi là của họ", "Chỉ khi ảnh xấu", "Chỉ người nổi tiếng mới có quyền", "Có – chủ thể dữ liệu có quyền yêu cầu xóa dữ liệu cá nhân"]'::jsonb,3,'Ảnh của mình – mình có tiếng nói.','Điểm d khoản 1 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(92,2,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-2.svg','App học tiếng Anh tắt đi rồi mà vẫn liên tục lấy vị trí. Theo luật, nhà cung cấp app phải?','["Được lấy tự do", "Không cần thông báo", "Thông báo việc dùng dữ liệu vị trí và cho người dùng tùy chọn theo dõi vị trí", "Chỉ cần giấu trong điều khoản"]'::jsonb,2,'Vị trí của bạn – bạn bật tắt.','Điểm b khoản 3 Điều 31 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(93,2,1,ARRAY['link-la']::text[],'img/linkla-1.svg','Mã QR dán trên cột điện: "Quét để nhận học bổng 10 triệu". Bạn nên?','["Không quét, mã QR lạ có thể dẫn tới trang lừa đảo", "Chụp gửi bạn bè quét", "Quét ngay", "Quét bằng máy của mẹ"]'::jsonb,0,'QR lạ – đừng để điện thoại “ăn” bậy.','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Khoản 1 Điều 17 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(94,2,2,ARRAY['bat-nat']::text[],'img/batnat.svg','Mèo Mít nhận ra mình từng chia sẻ bài chế giễu bạn. Việc nên làm?','["Đăng thêm bài khác để át đi", "Đổ lỗi cho người đăng đầu", "Giả vờ không biết", "Gỡ bài, xin lỗi bạn, không tiếp tục lan truyền"]'::jsonb,3,'Lỡ làm sai – dừng lại, sửa sai.','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(95,2,1,ARRAY['tai-khoan']::text[],'img/taikhoan.svg','Bạn bè hỏi mượn tài khoản Zalo để "nhắn tin cho crush". Nếu bạn ấy dùng để làm việc xấu, ai chịu trách nhiệm?','["Chủ tài khoản cũng có thể bị xử lý tùy mức độ", "Nhà mạng", "Không ai cả", "Chỉ người mượn"]'::jsonb,0,'Tài khoản của bạn – trách nhiệm của bạn.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(96,2,2,ARRAY['tin-gia']::text[],'img/tingia.svg','Có bài viết kêu gọi tẩy chay một cửa hàng với thông tin bịa đặt. Theo luật, kêu gọi tẩy chay kiểu này?','["Quyền của người tiêu dùng", "Là thông tin xâm phạm quyền, lợi ích hợp pháp của tổ chức", "Hợp pháp nếu nhiều người đồng tình", "Không có quy định"]'::jsonb,1,'Tẩy chay bằng tin bịa – bịa thì sai.','Điểm b khoản 3 Điều 13 Luật An ninh mạng số 116/2025/QH15; Điểm a khoản 3 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(97,2,1,ARRAY['nguoi-la']::text[],'img/nguoila-2.svg','Dấu hiệu nào cho thấy bạn mạng có thể không như họ nói?','["Không bao giờ bật camera, hỏi nhiều chuyện riêng, đòi giữ bí mật", "Thích cùng game với bạn", "Có ảnh đại diện đẹp", "Nói chuyện lịch sự"]'::jsonb,0,'Không ai trên mạng giống hệt những gì họ nói.','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(98,2,2,ARRAY['mua-sam']::text[],'img/muasam.svg','Livestream bán "iPhone xách tay giá 1 triệu, cam kết chính hãng". Theo luật, quảng cáo bán hàng giả, không rõ nguồn gốc trên mạng là?','["Hành vi xâm phạm trật tự, an toàn xã hội trên không gian mạng", "Khuyến mãi bình thường", "Kinh doanh hợp pháp", "Chỉ vi phạm khi bị tố"]'::jsonb,0,'Hàng giá “khó tin” – thường là “khó tin” thật.','Điểm h khoản 4 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(99,2,2,ARRAY['game']::text[],'img/game-2.svg','Bạn tạo phần mềm làm sập server game của trường "cho vui". Hành vi này là?','["Không ai biết thì không sao", "Thử tài lập trình", "Hợp pháp vì là trường mình", "Tấn công mạng – gây gián đoạn hệ thống thông tin"]'::jsonb,3,'Làm sập để vui – vui ở đồn.','Điểm b khoản 1 Điều 18 Luật An ninh mạng số 116/2025/QH15; Khoản 3 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(100,2,1,ARRAY['bao-cao']::text[],'img/baocao-1.svg','Bạn nhận được tin nhắn đe dọa lúc 11 giờ đêm. Theo cẩm nang, bước đầu tiên là?','["Đăng lên mạng kể khổ", "Chửi lại cho bõ tức", "Trả lời để hỏi lý do", "Dừng lại và cắt nguồn gây hại (chặn, ngừng trả lời)"]'::jsonb,3,'Nút đầu tiên: DỪNG.','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(101,2,2,ARRAY['ai-deepfake']::text[],'img/deepfake-1.svg','Bạn dùng AI tạo ảnh "bạn cùng lớp đang ăn trộm" để trêu. Hành vi này vi phạm?','["Không vi phạm vì ảnh là AI", "Dùng AI giả mạo hình ảnh và bịa đặt xúc phạm người khác", "Không vi phạm nếu ghi \"đùa\"", "Chỉ vi phạm nếu bạn ấy kiện"]'::jsonb,1,'Ảnh AI – hậu quả thật.','Điểm g khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm c khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(102,2,1,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-2.svg','Bạn có nghĩa vụ gì với dữ liệu cá nhân của chính mình theo Luật BVDLCN?','["Tự bảo vệ dữ liệu cá nhân của mình", "Giao cho người khác giữ hộ", "Không có nghĩa vụ gì", "Phải đăng công khai"]'::jsonb,0,'Luật dặn: tự giữ dữ liệu của mình trước.','Điểm a khoản 2 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(103,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-1.svg','Một app học tập ghi: "Tiếp tục sử dụng nghĩa là bạn đồng ý cho chúng tôi bán dữ liệu cho đối tác". Theo Luật BVDLCN, cách "đồng ý" này?','["Hợp lệ nếu người dùng trên 16 tuổi", "Hợp lệ vì đã thông báo", "Hợp lệ nếu app miễn phí", "Không hợp lệ – sự đồng ý phải tự nguyện, rõ ràng, theo từng mục đích; im lặng không phải là đồng ý"]'::jsonb,3,'Im lặng ≠ đồng ý. Đồng ý phải rõ ràng.','Khoản 2 Điều 9 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Điểm d khoản 4 Điều 9 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(104,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Đăng ký CLB online yêu cầu đồng ý chung một nút cho cả "quản lý thành viên" và "gửi quảng cáo của nhà tài trợ". Điểm sai?','["Sai vì nút quá nhỏ", "Không được buộc đồng ý kèm các mục đích khác ngoài thỏa thuận", "Chỉ sai nếu thu phí", "Không sai gì"]'::jsonb,1,'Mỗi mục đích một lần đồng ý.','Điểm a khoản 4 Điều 9 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Điểm b khoản 4 Điều 9 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(105,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-2.svg','Bạn đã đồng ý cho một app dùng dữ liệu, giờ muốn rút lại. Theo luật?','["Đã đồng ý thì không rút được", "Chỉ rút được khi app đóng cửa", "Phải ra tòa mới rút được", "Có quyền yêu cầu rút lại sự đồng ý, gửi bằng văn bản hoặc dạng điện tử kiểm chứng được"]'::jsonb,3,'Đồng ý được thì rút được.','Điểm b khoản 1 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 1 Điều 10 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 2 Điều 10 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(106,3,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-2.svg','Rút lại sự đồng ý có làm các hoạt động xử lý dữ liệu TRƯỚC thời điểm rút trở nên trái luật không?','["Có, mọi xử lý trước đó đều trái luật", "Có, và app phải bồi thường tự động", "Tùy app quyết định", "Không – việc rút lại không áp dụng với hoạt động xử lý trước thời điểm yêu cầu"]'::jsonb,3,'Rút đồng ý là “từ nay”, không phải “từ xưa”.','Khoản 4 Điều 10 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(107,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Theo Luật BVDLCN, việc nào sau đây bị nghiêm cấm (trừ trường hợp luật khác quy định)?','["Mua, bán dữ liệu cá nhân", "Tự đăng ảnh của mình", "Yêu cầu chỉnh sửa dữ liệu sai", "Đồng ý cho trường lưu hồ sơ"]'::jsonb,0,'Dữ liệu người khác – không mua, không bán.','Khoản 6 Điều 7 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(108,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-2.svg','Theo Luật BVDLCN, "dữ liệu cá nhân" sau khi đã khử nhận dạng thì?','["Trở thành bí mật nhà nước", "Thuộc về người khử nhận dạng", "Vẫn là dữ liệu cá nhân nhạy cảm", "Không còn là dữ liệu cá nhân"]'::jsonb,3,'Khử nhận dạng xong – không còn “nhận ra ai”.','Khoản 1 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 11 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(109,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-1.svg','Bạn phát hiện thông tin sai về mình trong hồ sơ một trung tâm tiếng Anh. Quyền của bạn?','["Xem, chỉnh sửa hoặc yêu cầu chỉnh sửa dữ liệu cá nhân", "Chỉ phụ huynh có quyền xem", "Chỉ được chấp nhận", "Phải trả phí mới được xem"]'::jsonb,0,'Dữ liệu sai – có quyền sửa.','Điểm c khoản 1 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(110,3,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Một tạp chí tuổi teen muốn đăng chuyện đời tư của bạn 14 tuổi (có tên, ảnh). Theo Luật BVDLCN cần sự đồng ý của ai?','["Chỉ của bạn đó", "Chỉ của bố mẹ", "Của chính bạn đó (vì từ đủ 7 tuổi) và người đại diện theo pháp luật", "Của nhà trường"]'::jsonb,2,'Trẻ từ 7 tuổi – cả em và bố mẹ cùng gật đầu.','Khoản 2 Điều 24 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(111,3,2,ARRAY['tin-gia']::text[],'img/tingia-2.svg','Theo Luật An ninh mạng 2025, đăng thông tin sai sự thật gây hoang mang trong Nhân dân thuộc nhóm nào?','["Chỉ vi phạm nếu có trên 1.000 lượt chia sẻ", "Vi phạm đạo đức, không vi phạm luật", "Hành vi bị nghiêm cấm về an ninh mạng", "Quyền tự do biểu đạt không giới hạn"]'::jsonb,2,'Sai sự thật gây hoang mang – nằm trong danh sách cấm.','Điểm d khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(112,4,2,ARRAY['tin-gia']::text[],'img/tingia.svg','Nghị định nào trong 7 nghị định ngày 19/8/2026 chuyên về phòng, chống tin giả, tin sai sự thật?','["Nghị định 329/2026/NĐ-CP", "Nghị định 331/2026/NĐ-CP", "Nghị định 332/2026/NĐ-CP", "Nghị định 328/2026/NĐ-CP"]'::jsonb,3,'Tin giả? Nhớ “ba hai tám”.','Nghị định 328/2026/NĐ-CP ngày 19/8/2026 quy định phòng, chống tin giả, tin sai sự thật','ORIGINAL'),
(113,4,2,ARRAY['tin-gia']::text[],'img/tingia.svg','Nghị định xử phạt vi phạm hành chính trong lĩnh vực an ninh mạng và bảo vệ dữ liệu cá nhân là?','["Nghị định 327/2026/NĐ-CP", "Nghị định 332/2026/NĐ-CP", "Nghị định 330/2026/NĐ-CP", "Nghị định 333/2026/NĐ-CP"]'::jsonb,2,'Phạt thì “ba ba mươi”.','Nghị định 330/2026/NĐ-CP ngày 19/8/2026 quy định xử phạt vi phạm hành chính trong lĩnh vực an ninh mạng và bảo vệ dữ liệu cá nhân','ORIGINAL'),
(114,4,1,ARRAY['luat-chung']::text[],'img/luat-2.svg','Luật An ninh mạng số 116/2025/QH15 có hiệu lực từ ngày nào?','["10/12/2025", "01/01/2026", "19/8/2026", "01/7/2026"]'::jsonb,3,'Mùng 1 tháng 7 năm 2026 – luật mới “lên sóng”.','Khoản 1 Điều 44 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(115,4,1,ARRAY['luat-chung']::text[],'img/luat.svg','Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15 có hiệu lực từ ngày nào?','["01/01/2026", "26/6/2025", "01/7/2026", "01/01/2027"]'::jsonb,0,'Tết Dương lịch 2026 – dữ liệu được “bảo hiểm”.','Điều 38 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(116,4,2,ARRAY['luat-chung']::text[],'img/luat-2.svg','Khi Luật An ninh mạng 2025 có hiệu lực, hai luật nào hết hiệu lực?','["Luật Giao dịch điện tử và Luật Viễn thông", "Bộ luật Dân sự và Bộ luật Hình sự", "Luật An toàn thông tin mạng 2015 và Luật An ninh mạng 2018", "Luật Trẻ em và Luật Giáo dục"]'::jsonb,2,'Hai luật cũ “nghỉ hưu”, một luật mới thay.','Khoản 2 Điều 44 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(117,3,2,ARRAY['tai-khoan']::text[],'img/taikhoan.svg','Theo Luật ANM 2025, người dùng có trách nhiệm gì với tài khoản số của mình?','["Chỉ doanh nghiệp mới có trách nhiệm", "Bảo mật thông tin đăng ký, mở, quản lý, sử dụng tài khoản số", "Không có trách nhiệm gì", "Chia sẻ mật khẩu cho người thân quen"]'::jsonb,1,'Tài khoản số của ai – người đó giữ.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(118,3,3,ARRAY['tai-khoan']::text[],'img/taikhoan-1.svg','Tài khoản của bạn bị người khác mượn để lừa đảo. Theo Luật ANM 2025, hậu quả có thể là?','["Chủ tài khoản, người sử dụng có thể bị xử lý kỷ luật, xử phạt hoặc truy cứu và phải bồi thường nếu gây thiệt hại", "Không ai bị xử lý vì là tài khoản ảo", "Chỉ người mượn bị xử lý", "Chỉ bị nhắc nhở"]'::jsonb,0,'Cho mượn tài khoản – trả giá bằng trách nhiệm.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(119,3,2,ARRAY['tai-khoan']::text[],'img/taikhoan-1.svg','Thu thập, mua bán, trao đổi trái phép thông tin tài khoản ngân hàng, ví điện tử của người khác là?','["Giao dịch dân sự bình thường", "Chỉ vi phạm khi trên 10 tài khoản", "Hợp pháp nếu có giấy viết tay", "Hành vi xâm phạm an ninh quốc gia, trật tự, an toàn xã hội trên không gian mạng"]'::jsonb,3,'Tài khoản người khác – không phải hàng hóa.','Điểm g khoản 4 Điều 13 Luật An ninh mạng số 116/2025/QH15; Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(120,3,2,ARRAY['deepfake']::text[],'img/deepfake.svg','Luật ANM 2025 quy định cụ thể về việc dùng AI để giả mạo video, hình ảnh, giọng nói của người khác như thế nào?','["Được phép nếu để giải trí", "Là hành vi bị nghiêm cấm khi trái quy định pháp luật", "Chỉ cấm với người nổi tiếng", "Không có quy định về AI"]'::jsonb,1,'AI giả mặt giả giọng – luật đã gọi tên.','Điểm g khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(121,3,2,ARRAY['bat-nat']::text[],'img/batnat-2.svg','Hành vi nào được Luật ANM 2025 liệt kê là thông tin xâm phạm quyền, lợi ích của cá nhân?','["Đánh giá 3 sao một quán ăn trung thực", "Xúc phạm danh dự, uy tín, nhân phẩm của người khác", "Bày tỏ không thích một bộ phim", "Góp ý lịch sự về bài làm"]'::jsonb,1,'Chê có văn hóa ≠ xúc phạm.','Điểm d khoản 3 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(122,3,3,ARRAY['bat-nat']::text[],'img/batnat.svg','Bịa đặt rằng bạn khác phạm tội rồi tố cáo họ với cơ quan có thẩm quyền thì sao?','["Là thông tin xâm phạm quyền, lợi ích hợp pháp của cá nhân theo Luật ANM", "Là quyền tố cáo", "Hợp pháp nếu tố cáo qua mạng", "Chỉ là hiểu nhầm"]'::jsonb,0,'Tố cáo thật là quyền – tố cáo bịa là vi phạm.','Điểm g khoản 3 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(123,3,2,ARRAY['nguoi-la']::text[],'img/nguoila.svg','Theo Luật ANM 2025, trẻ em có những quyền gì trên không gian mạng?','["Tiếp cận thông tin, tham gia hoạt động xã hội, vui chơi, giải trí, bảo vệ bí mật cá nhân, đời sống riêng tư", "Chỉ được dùng mạng khi có giáo viên", "Chỉ được học online", "Không có quyền gì cho đến 18 tuổi"]'::jsonb,0,'Trẻ em online – có quyền và được bảo vệ.','Khoản 1 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(124,3,2,ARRAY['nguoi-la']::text[],'img/nguoila-2.svg','Doanh nghiệp cung cấp mạng xã hội có trách nhiệm gì với nội dung gây hại cho trẻ em theo Luật ANM 2025?','["Chỉ cảnh báo người đăng", "Không có trách nhiệm", "Ngăn chặn chia sẻ và xóa bỏ thông tin gây nguy hại, xâm hại trẻ em", "Chỉ xóa khi có lệnh tòa"]'::jsonb,2,'Nền tảng phải “dọn rác” độc hại cho trẻ.','Điểm b khoản 3 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(125,3,2,ARRAY['link-la']::text[],'img/linkla-1.svg','Ai có trách nhiệm chủ động phòng ngừa phần mềm độc hại theo Luật ANM 2025?','["Cơ quan, tổ chức, cá nhân – tức là mọi người", "Chỉ người làm IT", "Chỉ công an", "Chỉ nhà mạng"]'::jsonb,0,'Mã độc – ai cũng phải đề phòng.','Khoản 1 Điều 17 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(126,3,2,ARRAY['hack']::text[],'img/hack-1.svg','Bạn tìm ra lỗ hổng web trường và tự ý xâm nhập để "đổi điểm giúp bạn". Theo Luật ANM?','["Xâm nhập trái phép hệ thống thông tin – hành vi bị nghiêm cấm", "Kỹ năng đáng khen", "Hợp pháp nếu không lấy tiền", "Hợp pháp nếu báo trường sau"]'::jsonb,0,'Phát hiện lỗ hổng – báo, đừng khai thác.','Khoản 5 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm d khoản 1 Điều 18 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(127,3,2,ARRAY['hack']::text[],'img/hack.svg','Bạn phát hiện lỗ hổng bảo mật trên website của trường. Cách đúng?','["Bán thông tin lỗ hổng", "Thử khai thác để chứng minh", "Báo cho nhà trường/cơ quan có thẩm quyền, không khai thác", "Đăng lên mạng khoe"]'::jsonb,2,'Lỗ hổng: báo cáo, không khai thác.','Khoản 3 Điều 42 Luật An ninh mạng số 116/2025/QH15; Điểm d khoản 1 Điều 18 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(128,3,3,ARRAY['hack']::text[],'img/hack-2.svg','Bán, tặng phần mềm có tính năng gây hại để dùng vào mục đích trái pháp luật thuộc nhóm hành vi nào?','["Chia sẻ mã nguồn mở", "Hành vi tấn công mạng và liên quan tới tấn công mạng", "Không bị điều chỉnh", "Kinh doanh phần mềm bình thường"]'::jsonb,1,'Bán vũ khí số – cũng là tấn công mạng.','Điểm đ khoản 1 Điều 18 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(129,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-1.svg','Theo Luật ANM 2025, thu thập, sử dụng, phát tán, kinh doanh trái pháp luật dữ liệu cá nhân của người khác là?','["Hành vi bị nghiêm cấm trên không gian mạng", "Hoạt động marketing bình thường", "Hợp pháp nếu dữ liệu đã công khai", "Chỉ vi phạm đạo đức"]'::jsonb,0,'Dữ liệu người khác – không phải “mỏ vàng” tự do.','Điểm h khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(130,3,2,ARRAY['anh-rieng-tu']::text[],'img/anhrieng-1.svg','Cố ý nghe lén, ghi âm, ghi hình trái phép cuộc gọi trên không gian mạng là?','["Quyền lưu bằng chứng tùy ý", "Chỉ sai nếu đăng lên mạng", "Hợp pháp nếu là bạn bè", "Hành vi bị nghiêm cấm"]'::jsonb,3,'Ghi lén cuộc gọi – luật cấm rõ ràng.','Điểm c khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(131,3,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-1.svg','Mạng xã hội muốn đọc tin nhắn của bạn để "gợi ý quảng cáo phù hợp" mà không hỏi. Theo Luật BVDLCN?','["Được nếu ghi trong điều khoản dài", "Được phép nếu ẩn danh", "Được phép vì miễn phí", "Không được đọc tin nhắn khi chưa có sự đồng ý, trừ trường hợp luật khác quy định"]'::jsonb,3,'Tin nhắn riêng – không đọc lén.','Khoản 5 Điều 29 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(132,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Mạng xã hội có nghĩa vụ gì về chính sách bảo mật theo Luật BVDLCN?','["Giữ bí mật chính sách", "Không có nghĩa vụ", "Công khai chính sách, giải thích cách thu thập, sử dụng, chia sẻ dữ liệu và cho người dùng cơ chế truy cập, chỉnh sửa, xóa", "Chỉ cung cấp cho cơ quan nhà nước"]'::jsonb,2,'Minh bạch là nghĩa vụ, không phải ân huệ.','Khoản 6 Điều 29 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(133,4,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Dữ liệu sinh trắc học (vân tay, khuôn mặt) được định nghĩa là gì?','["Mọi ảnh selfie có filter", "Mật khẩu dạng số", "Dữ liệu về sở thích ăn uống", "Dữ liệu về thuộc tính vật lý, đặc điểm sinh học cá biệt và ổn định để xác định một người"]'::jsonb,3,'Vân tay không đổi được như mật khẩu – giữ cẩn thận!','Khoản 2 Điều 31 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(134,3,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Một phòng gym thu thập vân tay hội viên nhưng để thiết bị lưu trữ ai cũng truy cập được. Họ vi phạm nghĩa vụ gì?','["Không vi phạm vì vân tay không phải bí mật", "Bảo mật vật lý thiết bị, hạn chế quyền truy cập dữ liệu sinh trắc học", "Chỉ cần xin lỗi khách", "Chỉ vi phạm nếu bị hack"]'::jsonb,1,'Dữ liệu sinh trắc – khóa hai lớp.','Điểm a khoản 4 Điều 31 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(135,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-1.svg','Bạn thấy dữ liệu của mình bị lạm dụng và gây thiệt hại. Quyền nào sau đây là của chủ thể dữ liệu?','["Không có quyền nào", "Khiếu nại, tố cáo, khởi kiện, yêu cầu bồi thường thiệt hại", "Chỉ được đăng lên mạng bóc phốt", "Tự xâm nhập hệ thống để xóa"]'::jsonb,1,'Bị hại dữ liệu – dùng đường pháp luật.','Điểm đ khoản 1 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(136,3,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Khi thực hiện quyền của chủ thể dữ liệu, bạn phải tuân thủ nguyên tắc nào?','["Được làm mọi cách để bảo vệ dữ liệu mình", "Được công khai dữ liệu người khác để trả đũa", "Không có nguyên tắc nào", "Không xâm phạm quyền, lợi ích hợp pháp của Nhà nước, tổ chức, cá nhân khác"]'::jsonb,3,'Đòi quyền mình – không giẫm quyền người.','Điểm c khoản 3 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(137,3,2,ARRAY['tin-gia']::text[],'img/tingia.svg','Bình luận bịa đặt về chất lượng một ngân hàng gây hoang mang, rút tiền ồ ạt. Luật ANM xếp hành vi này vào?','["Đăng tải thông tin bịa đặt, sai sự thật trong lĩnh vực tài chính, ngân hàng – bị nghiêm cấm", "Phản biện xã hội", "Bình luận cá nhân", "Không có quy định"]'::jsonb,0,'Tin đồn tài chính – có thể gây “bão” thật.','Điểm d khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(138,4,2,ARRAY['mua-sam']::text[],'img/muasam-1.svg','Tổ chức, hỗ trợ vận hành sàn giao dịch tài sản số trái phép trên mạng được Luật ANM 2025 xếp vào?','["Hoạt động khởi nghiệp hợp pháp", "Không bị điều chỉnh", "Hành vi xâm phạm an ninh quốc gia, trật tự, an toàn xã hội trên không gian mạng", "Đầu tư cá nhân"]'::jsonb,2,'Sàn “ảo” – rắc rối thật.','Điểm e khoản 4 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(139,3,2,ARRAY['luat-chung']::text[],'img/luat-2.svg','Theo Luật ANM 2025, việc phổ biến kiến thức an ninh mạng ưu tiên những đối tượng nào?','["Trẻ em, người cao tuổi, người khó khăn trong nhận thức", "Chỉ sinh viên IT", "Chỉ doanh nghiệp", "Chỉ cán bộ công an"]'::jsonb,0,'Người dễ bị tổn thương – được ưu tiên học trước.','Khoản 1 Điều 35 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(140,3,2,ARRAY['bao-cao']::text[],'img/baocao-2.svg','Theo Luật ANM 2025, cá nhân sử dụng không gian mạng có trách nhiệm gì khi phát hiện hành vi xâm phạm an ninh mạng?','["Đăng lên mạng bóc phốt trước", "Kịp thời cung cấp thông tin cho cơ quan có thẩm quyền, lực lượng bảo vệ an ninh mạng", "Tự xử lý bằng cách tấn công lại", "Im lặng cho an toàn"]'::jsonb,1,'Thấy xâm phạm – báo đúng nơi.','Khoản 3 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(141,3,3,ARRAY['bat-nat']::text[],'img/batnat.svg','Bạn A đăng clip chế giễu ngoại hình bạn B. Nhiều người chia sẻ lại "cho vui". Người chia sẻ có liên quan trách nhiệm không?','["Không, chỉ người đăng đầu tiên", "Không, vì không bình luận gì", "Có thể – phát tán thông tin xâm phạm danh dự người khác cũng là hành vi bị cấm", "Chỉ khi chia sẻ quá 3 lần"]'::jsonb,2,'Đăng lại cũng là “phát tán”.','Điểm c khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm a khoản 4 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(142,3,2,ARRAY['deepfake']::text[],'img/deepfake-2.svg','Tài khoản giả mạo trang thông tin điện tử của trường để thu tiền "học phí bổ sung". Đây là?','["Giả mạo trang thông tin điện tử của tổ chức – bị nghiêm cấm", "Quảng cáo hợp pháp", "Lỗi kỹ thuật", "Không vi phạm vì chưa thu được tiền"]'::jsonb,0,'Fanpage giả – học phí thật mất.','Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(143,3,2,ARRAY['game']::text[],'img/game-2.svg','Quảng cáo "app cá độ bóng đá uy tín" tràn ngập nhóm chat. Theo Luật ANM, tổ chức đánh bạc qua mạng là?','["Chỉ cấm người dưới 18", "Hành vi bị nghiêm cấm", "Hợp pháp nếu nhà cái ở nước ngoài", "Giải trí hợp pháp"]'::jsonb,1,'Cá độ online – thua cả tiền lẫn luật.','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(144,4,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-1.svg','Bên quyết định mục đích và phương tiện xử lý dữ liệu cá nhân được gọi là?','["Chủ thể dữ liệu cá nhân", "Bên kiểm soát dữ liệu cá nhân", "Bên thứ ba", "Bên xử lý dữ liệu cá nhân"]'::jsonb,1,'Ai quyết “để làm gì” – bên kiểm soát.','Khoản 7 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(145,4,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-2.svg','Một công ty in thẻ học sinh theo hợp đồng với trường. Công ty này đóng vai trò gì?','["Cơ quan quản lý nhà nước", "Chủ thể dữ liệu", "Bên xử lý dữ liệu cá nhân", "Bên kiểm soát dữ liệu cá nhân"]'::jsonb,2,'Làm theo yêu cầu qua hợp đồng – bên xử lý.','Khoản 8 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(146,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-1.svg','"Chủ thể dữ liệu cá nhân" là ai?','["Cơ quan công an", "Người thu thập dữ liệu", "Công ty lưu dữ liệu", "Người được dữ liệu cá nhân phản ánh"]'::jsonb,3,'Dữ liệu nói về ai – người đó là chủ thể.','Khoản 5 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(147,3,2,ARRAY['anh-rieng-tu']::text[],'img/anhrieng.svg','Chiếm đoạt, cố ý làm lộ, làm mất dữ liệu cá nhân thuộc nhóm nào theo Luật BVDLCN?','["Không có quy định", "Hành vi bị nghiêm cấm", "Sơ suất được miễn trách", "Chỉ vi phạm hợp đồng"]'::jsonb,1,'Làm lộ dữ liệu người khác – cấm.','Khoản 7 Điều 7 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(148,3,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-1.svg','Bạn cho người khác mượn căn cước, tài khoản để họ đăng ký sim, mở ví... rồi họ lừa đảo. Theo Luật BVDLCN?','["Không có quy định", "Cho người khác sử dụng dữ liệu cá nhân của mình để làm trái luật là bị nghiêm cấm", "Chỉ vi phạm nếu nhận tiền", "Không có lỗi vì chỉ cho mượn"]'::jsonb,1,'Cho mượn danh tính – mượn luôn rắc rối.','Khoản 5 Điều 7 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(149,3,2,ARRAY['bat-nat']::text[],'img/batnat.svg','Theo cẩm nang, có nên hứa giữ bí mật tuyệt đối khi bạn kể mình bị xâm hại trực tuyến?','["Có, và tự giải quyết", "Không, mà kể cho cả lớp", "Không nên hứa tuyệt đối – cần đưa người lớn tin cậy vào cuộc để bảo vệ bạn", "Có, phải giữ bí mật tuyệt đối"]'::jsonb,2,'Giữ riêng tư, đừng giữ nỗi sợ một mình.','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(150,4,2,ARRAY['luat-chung']::text[],'img/luat-1.svg','Luật An ninh mạng số 116/2025/QH15 được Quốc hội thông qua ngày nào?','["26/6/2025", "01/7/2026", "10/12/2025", "19/8/2026"]'::jsonb,2,'Ngày 10/12/2025 – ngày luật “chào đời”.','Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(151,3,2,ARRAY['nguoi-la']::text[],'img/nguoila.svg','Theo Luật ANM 2025, ai có trách nhiệm bảo đảm quyền của trẻ em, bảo vệ trẻ khi tham gia không gian mạng?','["Cơ quan, tổ chức, cha mẹ, người giám hộ, giáo viên, người chăm sóc và cá nhân liên quan", "Chỉ cha mẹ", "Chỉ công an", "Chỉ nhà mạng"]'::jsonb,0,'Bảo vệ trẻ online – việc của tất cả.','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(152,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-1.svg','Theo Luật BVDLCN, chủ thể dữ liệu có nghĩa vụ nào với dữ liệu của người khác?','["Chỉ phải bảo vệ dữ liệu người thân", "Được tự do chia sẻ nếu là bạn bè", "Không có nghĩa vụ", "Tôn trọng, bảo vệ dữ liệu cá nhân của người khác"]'::jsonb,3,'Bảo vệ dữ liệu mình, tôn trọng dữ liệu người.','Điểm b khoản 2 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(153,4,3,ARRAY['tin-gia']::text[],'img/tingia.svg','Đăng bản đồ Việt Nam thể hiện sai chủ quyền quốc gia trên mạng là?','["Lỗi thiết kế vô hại", "Tự do sáng tác", "Thông tin bị Luật ANM 2025 xác định là xâm phạm an ninh quốc gia", "Chỉ vi phạm nếu in ra giấy"]'::jsonb,2,'Bản đồ Tổ quốc – không “vẽ bậy”.','Điểm e khoản 1 Điều 13 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(154,4,2,ARRAY['link-la']::text[],'img/linkla-2.svg','Doanh nghiệp cung cấp dịch vụ thư điện tử phải làm gì với phần mềm độc hại theo Luật ANM 2025?','["Có hệ thống lọc phần mềm độc hại khi gửi, nhận, lưu trữ thông tin", "Không cần làm gì", "Chuyển trách nhiệm cho người dùng", "Chỉ cảnh báo khi người dùng hỏi"]'::jsonb,0,'Hộp thư có “lưới lọc” – luật yêu cầu.','Khoản 3 Điều 17 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(155,4,2,ARRAY['lua-dao']::text[],'img/luadao-2.svg','Bà Tư nhận cuộc gọi "công an" báo con trai liên quan đường dây ma túy, yêu cầu chuyển tiền "tạm giữ" vào tài khoản an toàn. Phản ứng đúng?','["Chuyển ngay để con khỏi bị bắt", "Cung cấp số tài khoản để họ kiểm tra", "Cúp máy, không chuyển tiền, liên hệ trực tiếp công an địa phương để xác minh", "Chuyển một nửa để thử"]'::jsonb,2,'Công an không làm việc qua điện thoại đòi chuyển tiền.','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(156,4,2,ARRAY['lua-dao']::text[],'img/luadao-2.svg','Một "nhân viên ngân hàng" gọi tới, đọc đúng họ tên, số căn cước của bạn rồi xin mã OTP để "hoàn tiền". Điều bạn nên suy luận?','["Đọc thêm số thẻ để họ đối chiếu", "Đưa OTP vì để hoàn tiền", "Họ biết số căn cước nên chắc là thật", "Biết thông tin của bạn không chứng minh họ là thật – dữ liệu có thể đã bị lộ; không đưa OTP"]'::jsonb,3,'Họ biết về bạn ≠ họ là người tốt.','Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Khoản 7 Điều 7 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(157,4,3,ARRAY['lua-dao']::text[],'img/luadao-2.svg','Ứng dụng "đầu tư nhiệm vụ: thả tim video nhận hoa hồng" cho rút lãi 2 lần rồi đòi nạp 50 triệu để "mở khóa". Mô hình này là?','["Đầu tư sinh lời thật", "Lừa đảo chiếm đoạt tài sản điển hình – dừng nạp, lưu bằng chứng, trình báo", "Nạp thêm để rút hết", "Lỗi hệ thống tạm thời"]'::jsonb,1,'Rút được lần đầu là mồi câu lần sau.','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(158,4,2,ARRAY['lua-dao']::text[],'img/luadao.svg','Bạn được mời làm "cộng tác viên", chỉ cần cho thuê tài khoản ngân hàng, mỗi tháng 3 triệu. Rủi ro pháp lý?','["Cho thuê, mua bán tài khoản ngân hàng là trái luật; chủ tài khoản có thể bị xử lý", "Chỉ người thuê chịu trách nhiệm", "Không rủi ro nếu không hỏi mục đích", "Thu nhập thụ động hợp pháp"]'::jsonb,0,'Thuê tài khoản = thuê luôn án phạt.','Điểm g khoản 4 Điều 13 Luật An ninh mạng số 116/2025/QH15; Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(159,4,2,ARRAY['deepfake']::text[],'img/deepfake-2.svg','Kế toán nhận video call "giám đốc" yêu cầu chuyển gấp 2 tỷ cho đối tác, hình ảnh mờ, mạng chập chờn. Quy trình đúng?','["Xác minh qua kênh độc lập (gọi số đã biết, gặp trực tiếp) và tuân thủ quy trình phê duyệt", "Hỏi giám đốc ngày sinh qua chính cuộc gọi đó", "Chuyển ngay vì giám đốc ra lệnh", "Chuyển trước, báo cáo sau"]'::jsonb,0,'Deepfake sợ nhất câu: “Để em gọi lại”.','Điểm g khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(160,4,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-1.svg','Cửa hàng bắt khách để lại số điện thoại mới bán hàng, rồi chia sẻ danh sách cho bên quảng cáo. Sai ở đâu?','["Chỉ sai nếu bán giá cao", "Không có sự đồng ý rõ ràng theo từng mục đích; chia sẻ/mua bán dữ liệu trái luật", "Không sai vì khách tự cho số", "Sai vì không in hóa đơn"]'::jsonb,1,'Cho số để mua hàng ≠ đồng ý bị spam.','Điểm a khoản 4 Điều 9 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 6 Điều 7 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(161,4,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-1.svg','Phụ huynh đăng ảnh con kèm tên trường, lớp, giờ tan học lên mạng công khai. Theo cẩm nang, rủi ro?','["Chỉ rủi ro nếu ảnh xấu", "Tăng nguy cơ kẻ xấu tiếp cận trẻ – nên hạn chế công khai thông tin nhận dạng", "Giúp con nổi tiếng", "Không rủi ro gì"]'::jsonb,1,'Khoe con vừa đủ – đừng khoe lộ trình.','Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình); Khoản 1 Điều 24 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(162,4,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-1.svg','Ứng dụng xem phim yêu cầu ảnh chụp căn cước để "xác minh". Bạn là người dùng mạng xã hội, căn cứ nào để từ chối?','["Luật BVDLCN cấm mạng xã hội yêu cầu ảnh/video chứa giấy tờ tùy thân làm yếu tố xác thực tài khoản", "Phải gửi theo quy định", "Không có căn cứ", "Chỉ được từ chối nếu dưới 18 tuổi"]'::jsonb,0,'Căn cước không phải vé xem phim.','Khoản 2 Điều 29 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(163,4,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu.svg','Doanh nghiệp tuyển dụng có được tự ý dùng hồ sơ ứng viên trượt để quảng cáo dịch vụ khác không?','["Được vì ứng viên đã nộp", "Được nếu sau 1 năm", "Không – dữ liệu chỉ xử lý theo mục đích đã được đồng ý", "Được nếu không ghi tên"]'::jsonb,2,'Nộp CV để xin việc, không phải để nhận quảng cáo.','Điểm a khoản 4 Điều 9 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(164,4,3,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-1.svg','Một công ty nhận yêu cầu xóa dữ liệu của khách hàng nhưng cố tình trì hoãn, gây khó khăn. Theo Luật BVDLCN?','["Được trì hoãn vô thời hạn", "Tổ chức có trách nhiệm tạo điều kiện, không được gây khó khăn việc thực hiện quyền của chủ thể dữ liệu", "Chỉ phải xử lý nếu khách trả phí", "Không có quy định"]'::jsonb,1,'Quyền của khách – doanh nghiệp phải mở cửa.','Khoản 4 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 5 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(165,4,2,ARRAY['tin-gia']::text[],'img/tingia-1.svg','Bạn nhận video "thực phẩm X gây ung thư" từ nhóm họ hàng, chưa rõ nguồn. Ứng xử của người trưởng thành?','["Kiểm chứng qua nguồn chính thống, không chuyển tiếp khi chưa rõ", "Thêm bình luận phóng đại", "Chuyển tiếp để “thà nhầm còn hơn bỏ sót”", "Đăng lên nhóm kinh doanh"]'::jsonb,0,'“Thà nhầm” có thể làm người khác thiệt thật.','Điểm d khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Nghị định 328/2026/NĐ-CP (phòng, chống tin giả, tin sai sự thật)','ORIGINAL'),
(166,2,1,ARRAY['tin-gia']::text[],'img/tingia-1.svg','Nhóm chat lớp 8A rần rần clip "trường sắp bị sập", ai cũng bấm chia sẻ. Bạn nên làm gì?','["Chia sẻ kèm câu \"không biết thật không nha\"", "Thêm hiệu ứng động đất cho clip \"căng\" hơn", "Chia sẻ thêm cho chắc ăn, lỡ thật thì sao", "Không chia sẻ, hỏi thầy cô hoặc xem thông báo chính thức của trường"]'::jsonb,3,'Chưa kiểm chứng – không chia sẻ, chặn tin đồn từ tay mình.','Điểm d khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15; Nghị định 328/2026/NĐ-CP ngày 19/8/2026 quy định phòng, chống tin giả, tin sai sự thật','ORIGINAL'),
(167,2,1,ARRAY['game']::text[],'img/game-2.svg','Trong game, một người tự xưng "admin" nhắn: "Gửi mật khẩu để anh nâng cấp nick VIP miễn phí". Bạn nên?','["Gửi mật khẩu cũ, giữ mật khẩu mới", "Không gửi, chặn và báo cáo tài khoản đó", "Gửi vì admin thì đáng tin", "Đổi mật khẩu thành \"123\" rồi gửi"]'::jsonb,1,'Admin thật không bao giờ xin mật khẩu.','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(168,2,1,ARRAY['bat-nat']::text[],'img/batnat-2.svg','Bạn thân bị cả nhóm nhắn tin chửi bới vì chuyện nhỏ. Bạn có thể giúp thế nào?','["Khuyên bạn xóa tài khoản và quên đi", "Im lặng để khỏi bị vạ lây", "Hỏi han bạn, giúp lưu bằng chứng và cùng báo thầy cô hoặc gọi 111", "Vào chửi lại cả nhóm cho hả"]'::jsonb,2,'Bạn bị bắt nạt – mình đứng cạnh, cùng báo người lớn.','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(169,2,1,ARRAY['anh-rieng-tu']::text[],'img/anhrieng-1.svg','Bạn chụp ảnh nhóm đi chơi, một bạn nói "đừng đăng ảnh tớ nhé". Bạn nên làm gì?','["Đăng rồi tag luôn bạn đó", "Không đăng ảnh có bạn đó, hoặc làm mờ/cắt bạn ra", "Đăng để chế độ \"chỉ bạn bè\"", "Vẫn đăng vì ảnh đẹp mà"]'::jsonb,1,'Ảnh có bạn – bạn đồng ý mới đăng.','Điều 32 Bộ luật Dân sự 2015; Điều 9 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(170,2,1,ARRAY['lua-dao']::text[],'img/luadao.svg','Trang bán hàng mời "nạp 200k nhận ngay iPhone", chỉ cần chuyển khoản trước. Bạn nghĩ gì?','["Đây là dấu hiệu lừa đảo – không chuyển tiền", "Rủ cả lớp cùng góp tiền nạp", "Cơ hội hiếm, nạp ngay kẻo lỡ", "Nạp thử 100k xem sao"]'::jsonb,0,'Rẻ bất thường + chuyển tiền trước = lừa đảo.','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(171,2,1,ARRAY['nguoi-la']::text[],'img/nguoila.svg','Bạn mới quen trên mạng luôn từ chối gọi video, nhưng hay hỏi trường học, giờ tan học của bạn. Nên làm gì?','["Hẹn gặp ở cổng trường cho tiện", "Cảnh giác, không cho thông tin, kể với bố mẹ", "Kể hết vì bạn ấy thân thiện", "Gửi luôn thời khóa biểu"]'::jsonb,1,'Bạn mạng hỏi giờ giấc, chỗ học – dừng lại, kể người lớn.','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(172,2,1,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-2.svg','Một trang "bói tên crush" bắt đăng nhập bằng Facebook và xin quyền đọc danh sách bạn bè. Bạn nên?','["Không đăng nhập, không cấp quyền đọc dữ liệu không cần thiết", "Đăng nhập luôn, bói xong thì thôi", "Cấp hết quyền cho kết quả chính xác", "Đăng nhập bằng tài khoản của bạn thân"]'::jsonb,0,'App đòi quyền quá đà – từ chối là khôn.','Điều 3, Điều 9 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(173,2,1,ARRAY['tai-khoan']::text[],'img/taikhoan.svg','Bạn dùng điện thoại mượn của bạn để vào Zalo. Dùng xong nên làm gì?','["Đổi ảnh đại diện của bạn cho vui", "Để nguyên cho lần sau đỡ đăng nhập", "Đăng xuất và không lưu mật khẩu trên máy bạn", "Nhờ bạn giữ tài khoản hộ"]'::jsonb,2,'Máy mượn dùng xong – đăng xuất ngay.','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(174,4,2,ARRAY['hack']::text[],'img/hack.svg','Nhân viên tò mò dùng tài khoản quản trị để xem hồ sơ lương đồng nghiệp ngoài phạm vi công việc. Đánh giá?','["Truy cập, xử lý dữ liệu cá nhân trái quy định – vi phạm", "Chỉ vi phạm nội quy", "Không sao nếu không kể ai", "Được phép vì có quyền quản trị"]'::jsonb,0,'Có chìa khóa không có nghĩa được mở mọi cửa.','Khoản 4 Điều 7 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 5 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(175,4,3,ARRAY['hack']::text[],'img/hack-1.svg','Công ty bị tấn công ransomware, dữ liệu khách hàng bị lộ. Theo Luật BVDLCN, việc cần làm có tính pháp lý?','["Đổ lỗi cho nhân viên IT trên mạng", "Giấu kín để giữ uy tín", "Thông báo vi phạm quy định về bảo vệ dữ liệu cá nhân theo quy định", "Trả tiền chuộc rồi im lặng"]'::jsonb,2,'Lộ dữ liệu – phải thông báo, không được giấu.','Điều 23 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(176,3,2,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-1.svg','Một ứng dụng học tập để lộ danh sách học sinh kèm số điện thoại của bạn. Bạn có những quyền gì?','["Chỉ được viết bình luận chê app", "Phải tự xóa số điện thoại của mình", "Yêu cầu xóa, hạn chế xử lý và yêu cầu bồi thường nếu bị thiệt hại", "Không có quyền gì vì đã dùng app miễn phí"]'::jsonb,2,'Dữ liệu bị lộ – bạn có quyền lên tiếng và đòi bồi thường.','Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(177,3,2,ARRAY['hack']::text[],'img/hack-1.svg','Bạn cùng lớp khoe "chiếm được nick Facebook của cô giáo" bằng cách đoán mật khẩu. Đánh giá?','["Lỗi của cô vì đặt mật khẩu dễ", "Chỉ là đùa, không sao", "Xâm nhập, chiếm quyền tài khoản trái phép – vi phạm pháp luật", "Đúng nếu chỉ xem không sửa gì"]'::jsonb,2,'Chiếm nick người khác là phạm luật, dù "cho vui".','Khoản 3 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(178,4,2,ARRAY['lua-dao']::text[],'img/luadao-2.svg','Người cao tuổi trong nhà nhận tin "trúng thưởng ô tô, nộp phí 5 triệu để nhận". Con cháu nên làm gì?','["Giải thích dấu hiệu lừa đảo, cùng kiểm tra và không nộp tiền", "Nộp một nửa", "Nộp giúp cho ông bà vui", "Chia sẻ lên mạng hỏi ý kiến"]'::jsonb,0,'Trúng thưởng mà phải nộp phí – trúng bẫy.','Điểm đ khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15; Khoản 1 Điều 35 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(179,4,3,ARRAY['lua-dao']::text[],'img/luadao-1.svg','Website giả mạo cổng dịch vụ công yêu cầu nhập thông tin định danh để "cập nhật dữ liệu". Hành vi tạo website này vi phạm?','["Không vi phạm vì chưa lấy được gì", "Là lỗi DNS", "Giả mạo trang thông tin điện tử của cơ quan, tổ chức – bị nghiêm cấm", "Chỉ vi phạm bản quyền giao diện"]'::jsonb,2,'Giống cổng công ≠ cổng công.','Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','ORIGINAL'),
(180,4,2,ARRAY['anh-rieng-tu']::text[],'img/anhrieng-2.svg','Chủ nhà trọ lắp camera hướng vào phòng ở của người thuê. Theo Luật BVDLCN?','["Không có quy định", "Xâm phạm dữ liệu cá nhân thu được từ ghi hình; cần tuân thủ quy định về ghi âm, ghi hình nơi công cộng và quyền riêng tư", "Được phép nếu không ghi âm", "Được phép vì là nhà của chủ"]'::jsonb,1,'Camera an ninh không phải camera nhìn trộm.','Điều 32 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Khoản 4 Điều 7 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(181,1,1,ARRAY['mat-khau']::text[],'img/matkhau-2.svg','Bạn cùng bàn hỏi: "Cho tớ biết mật khẩu Zalo của cậu đi!". Tí nên nói gì?','["\"Tớ viết lên bảng cho cậu chép\"", "\"Mật khẩu là bí mật, tớ không cho ai biết đâu!\"", "\"Được, nhưng cậu phải cho tớ mượn bút chì\"", "\"Tớ hát mật khẩu cho cả lớp nghe nhé!\""]'::jsonb,1,'Mật khẩu là bí mật, không nói ai một chút!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(182,1,1,ARRAY['nguoi-la']::text[],'img/nguoila-1.svg','Một chú lạ hoắc trên mạng hỏi: "Nhà cháu ở đâu thế?". Cún Bông nên làm gì?','["Không nói, kể ngay với bố mẹ", "Nói nhà ở \"sao Hỏa\" rồi gửi ảnh cổng nhà", "Hỏi chú có kẹo không rồi mới nói", "Gửi luôn bản đồ nhà mình"]'::jsonb,0,'Ai hỏi nhà em, mẹ cha biết thêm!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(183,1,1,ARRAY['link-la']::text[],'img/linkla-1.svg','Tin nhắn hiện lên: "Bấm vào đây để nhận cún con miễn phí!". Mèo Mít nên làm gì?','["Bấm ngay kẻo hết cún", "Gửi link cho cả lớp cùng bấm", "Không bấm, hỏi bố mẹ", "Bấm 10 lần cho được 10 con"]'::jsonb,2,'Link lạ mời chào, đừng bấm ào ào!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(184,1,1,ARRAY['bao-cao']::text[],'img/baocao-1.svg','Tí gặp chuyện buồn trên mạng, không biết kể ai. Tí có thể gọi số nào?','["999 – số của siêu nhân", "112233 – số của con mèo", "Không gọi ai, ôm gối khóc", "111"]'::jsonb,3,'Buồn thì bấm một một một, có người nghe hết!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(185,1,1,ARRAY['bat-nat']::text[],'img/batnat-2.svg','Có bạn nhắn tin chê Mèo Mít "xấu như khoai lang". Mèo Mít nên làm gì?','["Đăng lên mạng cho cả trường cùng chê bạn", "Chê lại \"xấu như củ khoai tây\"", "Không cãi nhau, lưu lại tin nhắn và kể với bố mẹ, thầy cô", "Buồn mà không kể ai"]'::jsonb,2,'Bị chê đừng chê, kể người lớn nghe!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(186,1,1,ARRAY['anh-rieng-tu']::text[],'img/anhrieng.svg','Người lạ trên mạng xin Tí gửi ảnh mặc đồ ngủ. Tí nên làm gì?','["Hỏi người đó có cho kẹo không", "Không gửi, chặn và kể với bố mẹ", "Gửi một tấm thôi", "Gửi ảnh mặc đồ siêu nhân thay thế"]'::jsonb,1,'Ảnh riêng của mình, không gửi người linh tinh!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(187,1,1,ARRAY['tin-gia']::text[],'img/tingia.svg','Trên mạng có tin: "Ăn kem mỗi sáng sẽ biết bay!". Cún Bông nên nghĩ gì?','["Tin ngay vì có ảnh minh họa", "Ăn 5 que kem rồi nhảy từ ghế xuống", "Tin này vô lý, hỏi bố mẹ, không chia sẻ", "Chia sẻ cho cả lớp cùng bay"]'::jsonb,2,'Tin nghe kỳ quặc, hỏi người lớn liền một mạch!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(188,1,1,ARRAY['game']::text[],'img/game-1.svg','Đang chơi game, có người nói: "Cho anh mã gửi về điện thoại của mẹ em, anh tặng skin". Tí nên làm gì?','["Chụp màn hình gửi luôn", "Đưa nửa mã thôi", "Không đưa mã, kể với mẹ", "Đọc mã thật to cho anh nghe"]'::jsonb,2,'Mã gửi về máy mẹ, không đưa ai nhé!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(189,1,1,ARRAY['mat-khau']::text[],'img/matkhau.svg','Tí dùng máy tính ở nhà bạn để vào game, chơi xong đi về. Tí cần nhớ làm gì?','["Viết mật khẩu ra giấy để lại", "Đăng xuất tài khoản trước khi về", "Để nguyên cho bạn chơi giúp", "Tắt quạt"]'::jsonb,1,'Máy nhà bạn dùng xong, đăng xuất là xong!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(190,1,1,ARRAY['nguoi-la']::text[],'img/nguoila-1.svg','Bạn mới quen trong game rủ Mèo Mít ra công viên gặp, "đừng nói ai nha". Mèo Mít làm gì?','["Rủ thêm em bé hàng xóm", "Không đi, kể ngay với bố mẹ", "Đi và mang theo con gấu bông", "Đi một mình cho bí mật"]'::jsonb,1,'Bạn mạng rủ đi, kể mẹ rồi tính gì!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(191,1,1,ARRAY['bao-cao']::text[],'img/baocao-2.svg','Cún Bông thấy video làm mình sợ hãi trên mạng. Việc đầu tiên nên làm?','["Dừng xem và kể với bố mẹ, thầy cô", "Xem tiếp cho hết", "Gửi cho bạn cùng sợ", "Giấu đi không kể ai"]'::jsonb,0,'Thấy sợ thì dừng, kể người lớn cùng!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(192,1,1,ARRAY['anh-rieng-tu']::text[],'img/anhrieng.svg','Tí muốn đăng ảnh bạn Na đang ngáp to lên mạng cho vui. Tí nên làm gì?','["Hỏi Na trước, Na không đồng ý thì không đăng", "Vẽ râu lên mặt Na rồi đăng", "Đăng luôn, Na sẽ thấy vui", "Đăng rồi tag cả trường"]'::jsonb,0,'Ảnh của bạn, hỏi bạn mới đăng!','Điều 32 Bộ luật Dân sự 2015; Điều 9 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(193,1,1,ARRAY['lua-dao']::text[],'img/luadao.svg','Có người nhắn: "Em trúng thưởng xe đạp, bảo bố mẹ chuyển tiền phí trước nhé!". Đây là gì?','["Có thể là lừa đảo – đưa bố mẹ xem", "Gửi luôn số tài khoản của bố", "Quà thật, chuyển tiền nhanh lên", "Trả lời \"Dạ, em cảm ơn ạ!\" rồi chờ xe"]'::jsonb,0,'Trúng thưởng mà đòi tiền, lừa đảo liền!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(194,1,1,ARRAY['hack']::text[],'img/hack-2.svg','Máy tính bỗng hiện chữ đỏ: "Máy bạn sắp nổ! Tải ngay ứng dụng này!". Mèo Mít làm gì?','["Bấm \"Đồng ý\" thật nhiều lần", "Không tải, gọi bố mẹ xem giúp", "Tải ngay kẻo máy nổ", "Ôm máy chạy ra sân"]'::jsonb,1,'Máy dọa đủ trò, gọi bố mẹ lo!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(195,1,1,ARRAY['webcam']::text[],'img/webcam.svg','Học online xong, Cún Bông nên làm gì với camera?','["Để camera bật cả đêm cho nó xem phim", "Quay camera ra cửa sổ", "Tắt hoặc che camera lại", "Dán kẹo cao su vào màn hình"]'::jsonb,2,'Học xong che cam, an toàn cả nhà!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(196,1,1,ARRAY['tai-khoan']::text[],'img/taikhoan.svg','Mẹ đưa điện thoại cho Tí chơi. Tí thấy ứng dụng ngân hàng của mẹ. Tí nên làm gì?','["Không bấm vào, chỉ chơi trò mẹ cho phép", "Chuyển tiền mua kẹo", "Bấm vào xem mẹ có bao nhiêu tiền", "Chụp ảnh gửi cho bạn"]'::jsonb,0,'Đồ của mẹ, không động vào nhé!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(197,1,1,ARRAY['du-lieu-ca-nhan']::text[],'img/dulieu-2.svg','Một trò chơi đố vui hỏi: "Nhập tên trường và địa chỉ nhà để nhận quà". Mèo Mít nên làm gì?','["Nhập địa chỉ nhà bạn thân", "Nhập ngay để lấy quà", "Không nhập, hỏi bố mẹ", "Nhập cả số điện thoại của bà"]'::jsonb,2,'Trò chơi đòi nhà, đừng nhập, hỏi ba!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Điều 24 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','ORIGINAL'),
(198,1,1,ARRAY['bat-nat']::text[],'img/batnat-1.svg','Cả nhóm chat chế ảnh bạn Bin thành con khỉ. Cún Bông nên làm gì?','["Không cười theo, không chia sẻ, kể với thầy cô", "Thả \"haha\" thật nhiều", "Gửi cho lớp khác xem", "Chế thêm ảnh con voi"]'::jsonb,0,'Bạn bị trêu chọc, mình không hùa theo!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(199,1,1,ARRAY['tin-gia']::text[],'img/tingia-1.svg','Bạn kể: "Nghe nói mai trường nghỉ vì có rồng bay qua". Tí nên làm gì?','["Gửi ngay cho cả lớp", "Vẽ thêm con rồng để đăng", "Hỏi thầy cô hoặc bố mẹ trước khi tin", "Sáng mai ở nhà ngủ luôn"]'::jsonb,2,'Tin chưa chắc, đừng vội nhắc!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(200,1,1,ARRAY['game']::text[],'img/game-2.svg','Cún Bông muốn chơi game tới nửa đêm. Lời khuyên nào đúng?','["Chơi tới sáng cho lên cấp", "Chơi trốn dưới chăn", "Chơi đúng giờ bố mẹ cho phép rồi đi ngủ", "Uống thật nhiều nước ngọt để thức"]'::jsonb,2,'Chơi đúng giờ, ngủ ngon mơ!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(201,1,1,ARRAY['nguoi-la']::text[],'img/nguoila-1.svg','Có lời mời kết bạn từ "Công chúa Tuyết thật 100%". Mèo Mít không quen. Nên làm gì?','["Đồng ý ngay vì là công chúa", "Không đồng ý, hỏi bố mẹ", "Gửi ảnh nhà mình để làm quen", "Nhắn xin quà trước"]'::jsonb,1,'Không quen không kết, an toàn tuyệt!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(202,1,1,ARRAY['bat-nat']::text[],'img/batnat.svg','Tí lỡ gửi tin nhắn trêu bạn làm bạn buồn. Tí nên làm gì?','["Xin lỗi bạn và không làm vậy nữa", "Đổ cho con mèo gửi", "Trêu thêm cho bạn quen", "Giả vờ không biết"]'::jsonb,0,'Lỡ làm bạn buồn, xin lỗi liền luôn!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(203,1,1,ARRAY['link-la']::text[],'img/linkla.svg','Tí nhặt được một chiếc USB ở sân trường. Tí nên làm gì?','["Gặm thử xem có cứng không", "Nộp cho thầy cô, không cắm vào máy", "Cắm vào máy ở nhà xem có gì", "Cắm vào máy của bạn"]'::jsonb,1,'USB nhặt được, nộp thầy là được!','Khoản 5 Điều 16 Luật An ninh mạng số 116/2025/QH15; Cẩm nang “Kết nối không tổn thương” 2026 (Chiến dịch Không Một Mình)','ORIGINAL'),
(204,4,2,ARRAY['pháp luật']::text[],'img/luat-2.svg','Đội "Thánh trả bài" của lớp 11A cãi nhau to: Luật An ninh mạng 2025 được Quốc hội khóa XV thông qua ở kỳ họp nào? Cả đội cược 1 hộp bánh tráng trộn. Bạn chọn?','["Kỳ họp thứ 10", "Kỳ họp thứ 11", "Kỳ họp thứ 9", "Kỳ họp thứ 8"]'::jsonb,0,'Kỳ họp thứ 10 – luật “điểm 10” ra đời.','Luật An ninh mạng số 116/2025/QH15','HHANM-1'),
(205,4,1,ARRAY['pháp luật']::text[],'img/luat-2.svg','Anh Ba là kỹ sư bảo mật, đang phân vân có nên nộp hồ sơ vào lực lượng an ninh mạng. Bạn trấn an anh: Nhà nước có chính sách gì khi tuyển dụng?','["Không có chính sách gì", "Ưu tiên bố trí nhân lực theo vị trí việc làm và đãi ngộ nhân tài", "Chỉ tuyển người trong ngành công an", "Chỉ tuyển người có bằng đại học"]'::jsonb,1,'Nhân tài an ninh mạng được ưu tiên và đãi ngộ.','Điều 31 Luật An ninh mạng số 116/2025/QH15','HHANM-2'),
(206,3,1,ARRAY['pháp luật']::text[],'img/luat.svg','Tí lớp 12 mê lập trình, hỏi thầy: "Em là dân thường thì có được vào lực lượng an ninh mạng không ạ?" Thầy trả lời sao?','["Có, nếu đủ tiêu chuẩn đạo đức và sức khỏe", "Chỉ tuyển người dưới 30 tuổi", "Chỉ tuyển nam giới", "Không, chỉ tuyển người quân đội"]'::jsonb,0,'Giỏi công nghệ, tốt đạo đức – cửa vẫn mở.','Điều 32 Luật An ninh mạng số 116/2025/QH15','HHANM-3'),
(207,4,2,ARRAY['pháp luật']::text[],'img/luat-2.svg','Chị kế toán cơ quan nhà nước hỏi: "Dự án nào thì phải bố trí tiền cho an ninh mạng hả anh?" Anh IT cười bí ẩn rồi trả lời…','["Dự án đầu tư chuyển đổi số", "Dự án ứng dụng CNTT hàng năm", "Dự án đầu tư xây dựng mới hệ thống", "Cả 3 phương án trên"]'::jsonb,3,'Có tiền làm số – phải có tiền giữ an toàn.','Điều 38 Luật An ninh mạng số 116/2025/QH15','HHANM-4'),
(208,4,3,ARRAY['pháp luật']::text[],'img/luat-1.svg','Bác Năm đố cả nhà trong bữa cơm: "Ai giúp Bộ trưởng Bộ Quốc phòng quản lý nhà nước về mật mã dân sự?" Thằng cháu nhanh nhảu trả lời…','["Tổng cục Tình báo", "Bộ Thông tin và Truyền thông", "Cục An ninh mạng và phòng, chống tội phạm sử dụng công nghệ cao", "Ban Cơ yếu Chính phủ"]'::jsonb,3,'Mật mã – nghĩ ngay đến “Cơ yếu”.','Điều 39 Luật An ninh mạng số 116/2025/QH15','HHANM-5'),
(209,4,2,ARRAY['pháp luật']::text[],'img/luat-1.svg','Mèo Mít làm thuyết trình "Bộ Công an làm gì cho không gian mạng?" và liệt kê một loạt việc. Đâu là kết luận đúng?','["Xây dựng chiến lược bảo vệ an ninh mạng", "Kiểm tra, thanh tra về an ninh mạng", "Phối hợp tuyên truyền, phản bác thông tin sai sự thật", "Tất cả các đáp án trên"]'::jsonb,3,'Bộ Công an: việc gì về an ninh mạng cũng có phần.','Điều 39 Luật An ninh mạng số 116/2025/QH15','HHANM-6'),
(210,4,1,ARRAY['pháp luật']::text[],'img/luat-2.svg','Cún Bông hỏi: "Ai là ''đội trưởng'' quản lý an ninh mạng trên cả nước vậy?" Câu "Chính phủ thống nhất quản lý nhà nước về an ninh mạng" là…','["Đúng", "Sai", "Do Quốc hội quản lý trực tiếp", "Chỉ quản lý ở các thành phố lớn"]'::jsonb,0,'Cả nước một mối – Chính phủ thống nhất quản lý.','Điều 39 Luật An ninh mạng số 116/2025/QH15','HHANM-7'),
(211,4,1,ARRAY['pháp luật']::text[],'img/luat-2.svg','Trong phim, nhân vật tự xưng "tôi đang đấu tranh bảo vệ an ninh mạng" chỉ vì đi comment cãi nhau. Theo luật, "đấu tranh bảo vệ an ninh mạng" là hoạt động có tổ chức của ai?','["Các doanh nghiệp nước ngoài", "Các câu lạc bộ tin học", "Lực lượng chuyên trách bảo vệ an ninh mạng", "Mọi cá nhân dùng Internet"]'::jsonb,2,'Comment cãi nhau không phải “đấu tranh” – đó là việc của lực lượng chuyên trách.','Điều 21 Luật An ninh mạng số 116/2025/QH15','HHANM-8'),
(212,4,2,ARRAY['tin giả']::text[],'img/tingia.svg','Hai nhóm tài khoản ảo "đánh nhau" bằng tin xuyên tạc, chiến tranh thông tin trên mạng. Luật nói ngăn chặn xung đột thông tin bằng cách nào?','["Sử dụng biện pháp công nghệ, kỹ thuật để giám sát, phản bác", "Loại trừ việc đăng tải thông tin ảnh hưởng đến quốc phòng, an ninh", "Hợp tác xác định nguồn gốc, đẩy lùi cuộc tấn công", "Tất cả các cách trên"]'::jsonb,3,'Xung đột thông tin – chặn bằng nhiều lớp.','Điều 22 Luật An ninh mạng số 116/2025/QH15','HHANM-9'),
(213,4,2,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Một viện nghiên cứu khoe "đang nghiên cứu phát triển an ninh mạng". Ông chú hỏi: "Nghiên cứu cái gì cơ?" Đáp án đầy đủ nhất là?','["Giải quyết nguy cơ đe dọa an ninh mạng", "Dự báo an ninh mạng", "Xây dựng hệ thống phần mềm bảo vệ an ninh mạng", "Tất cả các đáp án trên"]'::jsonb,3,'Nghiên cứu ANM: dự báo, giải quyết nguy cơ, làm phần mềm bảo vệ.','Điều 36 Luật An ninh mạng số 116/2025/QH15','HHANM-10'),
(214,4,1,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Server công ty của chị Hoa bị sự cố an ninh mạng lúc 2h sáng. Sếp hỏi: "Báo cho ai bây giờ?" Bạn trả lời?','["Báo cáo cho nhà mạng", "Ủy ban nhân dân xã", "Cơ quan chuyên trách của Bộ Công an hoặc Bộ Quốc phòng", "Cửa hàng máy tính"]'::jsonb,2,'Sự cố an ninh mạng – báo lực lượng chuyên trách, không báo… tiệm sửa máy.','Điều 40 Luật An ninh mạng số 116/2025/QH15','HHANM-11'),
(215,4,1,ARRAY['tài khoản']::text[],'img/taikhoan.svg','Nhà mạng gửi tin nhắn hướng dẫn cho Cún Bông. Theo luật, doanh nghiệp viễn thông phải hướng dẫn người dùng điều gì?','["Cách cài phần mềm lậu", "Cách vượt rào cản kỹ thuật", "Cách phòng ngừa nguy cơ mất ANM và xử lý sự cố", "Cách dùng mạng xã hội"]'::jsonb,2,'Nhà mạng phải dạy khách cách phòng sự cố, không dạy “vượt rào”.','Điều 41 Luật An ninh mạng số 116/2025/QH15','HHANM-12'),
(216,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Một người lạ gọi đến nhà mạng: "Cho tôi địa chỉ IP của thằng hàng xóm!" Theo luật, doanh nghiệp chỉ cung cấp thông tin định danh IP khi nào?','["Khi có yêu cầu của đối thủ cạnh tranh", "Luôn luôn công khai", "Khi có yêu cầu của lực lượng chuyên trách để bảo vệ ANM", "Khi có yêu cầu của cá nhân khác"]'::jsonb,2,'IP người dùng chỉ đưa cho lực lượng chuyên trách khi có yêu cầu đúng luật.','Điều 41 Luật An ninh mạng số 116/2025/QH15','HHANM-13'),
(217,4,3,ARRAY['pháp luật']::text[],'img/luat.svg','Hai anh luật sư cãi nhau: Luật ANM 2025 có thay cụm "an toàn thông tin mạng" bằng "an ninh mạng" trong Luật Phí và lệ phí không?','["Chỉ sửa tên điều", "Sai", "Đúng", "Chỉ sửa tên chương"]'::jsonb,2,'Một luật mới – đổi tên nhiều nơi.','Điều 43 Luật An ninh mạng số 116/2025/QH15','HHANM-14'),
(218,2,1,ARRAY['pháp luật']::text[],'img/luat-2.svg','Tí hỏi: "Vi phạm luật an ninh mạng thì chỉ bị khóa nick thôi đúng không?" Bạn trả lời sao?','["Chỉ bị khóa tài khoản", "Chỉ bị nhắc nhở", "Có, tùy theo tính chất và mức độ vi phạm", "Không, chỉ phạt hành chính"]'::jsonb,2,'Vi phạm nặng – có thể đi “học” ở nơi không có wifi.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','HHANM-15'),
(219,4,3,ARRAY['pháp luật']::text[],'img/luat-2.svg','Thầy giáo đố: Luật ANM 2025 sửa cụm "an toàn thông tin" thành "an ninh mạng" trong luật nào?','["Luật Lưu trữ", "Luật Bảo vệ quyền lợi người tiêu dùng", "Luật Công nghiệp công nghệ số", "Cả 3 luật trên"]'::jsonb,3,'Đổi tên đồng loạt – cả ba luật.','Điều 43 Luật An ninh mạng số 116/2025/QH15','HHANM-16'),
(220,4,1,ARRAY['pháp luật']::text[],'img/luat-2.svg','Mèo Mít hỏi bố: "Bảo vệ an ninh mạng phải tuân theo văn bản ''xịn'' nhất nào?" Bố trả lời…','["Quy định của công ty", "Hiến pháp", "Thông tư của Bộ", "Nghị định của Chính phủ"]'::jsonb,1,'Văn bản cao nhất – Hiến pháp.','Điều 4 Luật An ninh mạng số 116/2025/QH15','HHANM-17'),
(221,4,1,ARRAY['tấn công mạng']::text[],'img/hack-2.svg','Trong phim hành động, kẻ xấu tấn công mạng để làm loạn đất nước. "Khủng bố mạng" nhằm mục đích gì về chính trị?','["Để được bầu cử", "Làm mất ổn định chính trị", "Để tạo vị thế chính trị", "Để giữ ổn định chính trị"]'::jsonb,1,'Khủng bố mạng – muốn đất nước rối loạn.','Điều 2 Luật An ninh mạng số 116/2025/QH15','HHANM-18'),
(222,4,2,ARRAY['pháp luật']::text[],'img/luat-1.svg','Phòng IT của Bộ X cần cho quản trị viên hệ thống đi tập huấn chuyên sâu về an ninh mạng. Ai phối hợp tổ chức?','["Bộ Y tế", "Các doanh nghiệp tư nhân tự làm", "Bộ Lao động", "Bộ Công an phối hợp với các Bộ, ngành liên quan"]'::jsonb,3,'Tập huấn chuyên sâu – Bộ Công an phối hợp các bộ, ngành.','Điều 34 Luật An ninh mạng số 116/2025/QH15','HHANM-19'),
(223,4,1,ARRAY['pháp luật']::text[],'img/luat-1.svg','Cún Bông xem ảnh văn bản luật và thắc mắc chữ ký cuối cùng là của ai. Luật An ninh mạng 2025 do ai ký?','["Chủ tịch Quốc hội", "Chủ tịch nước", "Bộ trưởng Bộ Công an", "Thủ tướng Chính phủ"]'::jsonb,0,'Luật do Quốc hội thông qua – Chủ tịch Quốc hội ký.','Luật An ninh mạng số 116/2025/QH15; Luật Ban hành VBQPPL','HHANM-20'),
(224,4,3,ARRAY['pháp luật']::text[],'img/luat.svg','Công ty anh Ba có sản phẩm ANM đưa vào dùng trước khi luật có hiệu lực. Anh có bao lâu để đáp ứng điều kiện mới?','["03 tháng", "12 tháng kể từ ngày Luật có hiệu lực", "Không cần đáp ứng", "Vĩnh viễn"]'::jsonb,1,'Đồ cũ, luật mới – 12 tháng để “nâng cấp”.','Điều 45 Luật An ninh mạng số 116/2025/QH15','HHANM-21'),
(225,4,3,ARRAY['pháp luật']::text[],'img/luat-2.svg','Hệ thống thông tin của trường đại học phải bảo đảm điều kiện ANM theo luật mới. Thời gian chuyển tiếp là bao lâu?','["24 tháng", "06 tháng", "36 tháng", "12 tháng kể từ ngày Luật có hiệu lực"]'::jsonb,3,'Chuyển tiếp: 12 tháng tính từ ngày luật có hiệu lực.','Điều 45 Luật An ninh mạng số 116/2025/QH15','HHANM-22'),
(226,4,2,ARRAY['pháp luật']::text[],'img/luat-1.svg','Ông nội đọc báo hỏi: "Luật An toàn thông tin mạng 2015 giờ còn dùng không cháu?" Bạn trả lời…','["Chỉ có hiệu lực một nửa", "Hợp nhất vào Luật ANM 2025", "Vẫn có hiệu lực", "Hết hiệu lực"]'::jsonb,3,'Luật mới vào – luật cũ “nghỉ hưu”.','Khoản 2 Điều 44 Luật An ninh mạng số 116/2025/QH15','HHANM-23'),
(227,4,1,ARRAY['pháp luật']::text[],'img/luat-1.svg','Cô giáo đố: "Luật An ninh mạng 2025 có hiệu lực vào mùa nào năm 2026?" Mèo Mít đang cầm cây kem nghĩ ngay ra đáp án…','["Mùa thu (tháng 9)", "Mùa hè (tháng 7)", "Mùa đông (tháng 12)", "Mùa xuân (tháng 1)"]'::jsonb,1,'Mùa hè tháng 7 – luật mới “nóng hổi”.','Khoản 1 Điều 44 Luật An ninh mạng số 116/2025/QH15','HHANM-24'),
(228,4,2,ARRAY['pháp luật']::text[],'img/luat-2.svg','Chị luật sư hỏi đồng nghiệp: Luật Giao dịch điện tử cũng được sửa vài cụm từ cho khớp với Luật ANM 2025 – đúng hay sai?','["Chỉ sửa Luật Hình sự", "Đúng", "Sai", "Chỉ sửa Luật Dân sự"]'::jsonb,1,'Luật mới “chỉnh tề” luôn cả luật hàng xóm.','Điều 43 Luật An ninh mạng số 116/2025/QH15','HHANM-25'),
(229,3,1,ARRAY['tài khoản']::text[],'img/taikhoan-1.svg','Tí dùng máy tính cơ quan của mẹ, có tài khoản riêng, lại biết thông tin của bạn bè. Người dùng mạng có trách nhiệm bảo mật những gì?','["Thông tin đăng ký tài khoản của mình", "Thông tin cá nhân của người khác", "Mật khẩu máy tính của cơ quan", "Tất cả các thông tin trên"]'::jsonb,3,'Bảo mật tất cả: của mình, của người, của cơ quan.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15; Điểm b khoản 2 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-26'),
(230,4,2,ARRAY['pháp luật']::text[],'img/luat.svg','Công ty có giấy phép kinh doanh sản phẩm an toàn thông tin mạng cấp từ trước khi luật mới có hiệu lực. Giấy phép đó thì sao?','["Phải nộp lại cho Bộ Công an", "Có giá trị đến hết thời hạn ghi trên giấy phép", "Bị hủy bỏ", "Phải đổi ngay lập tức"]'::jsonb,1,'Giấy phép cũ còn hạn – dùng tới hết hạn.','Điều 45 Luật An ninh mạng số 116/2025/QH15','HHANM-27'),
(231,4,1,ARRAY['pháp luật']::text[],'img/luat.svg','Mèo Mít hỏi: "Học an ninh mạng ở môn nào ạ?" Nội dung giáo dục ANM là bắt buộc trong chương trình nào?','["Môn Âm nhạc", "Môn Ngoại ngữ", "Môn Toán", "Giáo dục quốc phòng và an ninh"]'::jsonb,3,'An ninh mạng học trong môn Giáo dục quốc phòng và an ninh.','Điều 33 Luật An ninh mạng số 116/2025/QH15','HHANM-28'),
(232,4,1,ARRAY['pháp luật']::text[],'img/luat.svg','Cún Bông mơ làm "siêu nhân an ninh mạng". Nhà nước có chính sách gì để thu hút nhân tài như Cún Bông?','["Buộc làm việc không lương", "Chỉ tuyển người nước ngoài", "Ưu tiên tuyển chọn, đào tạo, bồi dưỡng, đãi ngộ", "Không có chính sách gì"]'::jsonb,2,'Nhân tài số được ưu tiên đào tạo, đãi ngộ.','Điều 31 Luật An ninh mạng số 116/2025/QH15','HHANM-29'),
(233,4,1,ARRAY['pháp luật']::text[],'img/luat-2.svg','Trong game chiến thuật, Tí phải chọn "ai bảo vệ hệ thống thông tin quân sự". Đáp án đúng ngoài đời là?','["Bộ Công an", "Bộ Tư pháp", "Bộ Ngoại giao", "Bộ Quốc phòng"]'::jsonb,3,'Hệ thống quân sự – Bộ Quốc phòng lo.','Điểm b khoản 4 Điều 18 Luật An ninh mạng số 116/2025/QH15','HHANM-30'),
(234,4,3,ARRAY['pháp luật']::text[],'img/luat-2.svg','Trong buổi họp, sếp hỏi: Ban Cơ yếu Chính phủ giúp Bộ trưởng Bộ Quốc phòng quản lý nội dung gì?','["Quản lý thiết bị viễn thông", "Quản lý nhà nước về mật mã dân sự và ANM thuộc phạm vi quản lý", "Quản lý báo chí", "Quản lý mạng xã hội"]'::jsonb,1,'Cơ yếu: mật mã dân sự và ANM trong phạm vi quản lý.','Điều 39 Luật An ninh mạng số 116/2025/QH15','HHANM-31'),
(235,4,2,ARRAY['tấn công mạng']::text[],'img/hack.svg','Công ty chị Hoa vận hành hệ thống thông tin. Ngoài tự canh gác, chủ quản có trách nhiệm gì về giám sát ANM?','["Kết nối với hệ thống giám sát của Trung tâm An ninh mạng quốc gia", "Tự giám sát và không cần báo cáo", "Chỉ giám sát khi có sự cố", "Thuê công ty nước ngoài giám sát"]'::jsonb,0,'Giám sát không đơn độc – kết nối Trung tâm An ninh mạng quốc gia.','Điểm b khoản 1 Điều 40 Luật An ninh mạng số 116/2025/QH15','HHANM-32'),
(236,4,2,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Ứng dụng giao đồ ăn bị sự cố an ninh mạng. Doanh nghiệp phải làm gì?','["Triển khai phương án ứng cứu khẩn cấp", "Báo cáo ngay cho cơ quan chuyên trách", "Phối hợp xử lý theo yêu cầu", "Tất cả các trách nhiệm trên"]'::jsonb,3,'Có sự cố: ứng cứu, báo cáo, phối hợp – đủ ba việc.','Điều 41 Luật An ninh mạng số 116/2025/QH15','HHANM-33'),
(237,4,3,ARRAY['pháp luật']::text[],'img/luat-2.svg','Bạn A nói: "Luật ANM 2025 đổi từ ''an toàn thông tin mạng'' thành ''an ninh mạng'' trong nhiều luật khác." Đúng hay sai?','["Chỉ sửa trong Luật Hình sự", "Đúng", "Sai", "Chỉ sửa trong Luật Dân sự"]'::jsonb,1,'Một luật mới – đổi tên hàng loạt.','Điều 43 Luật An ninh mạng số 116/2025/QH15','HHANM-34'),
(238,4,2,ARRAY['pháp luật']::text[],'img/luat-2.svg','Bà ngoại hỏi: "Luật An toàn thông tin mạng 86/2015 hết hiệu lực bao giờ?"','["Khi Luật ANM 2025 có hiệu lực", "Đã hết hiệu lực từ 2020", "Khi có Nghị định mới", "Vẫn còn hiệu lực song song"]'::jsonb,0,'Luật mới chạy – luật cũ dừng.','Khoản 2 Điều 44 Luật An ninh mạng số 116/2025/QH15','HHANM-35'),
(239,4,1,ARRAY['pháp luật']::text[],'img/luat-1.svg','Mèo Mít đánh dấu lịch: ngày Luật An ninh mạng 2025 bắt đầu có hiệu lực là ngày nào?','["01/07/2026", "31/12/2025", "01/01/2026", "01/01/2027"]'::jsonb,0,'01/7/2026 – nhớ “mùng 1 tháng 7”.','Khoản 1 Điều 44 Luật An ninh mạng số 116/2025/QH15','HHANM-36'),
(240,2,1,ARRAY['pháp luật']::text[],'img/luat.svg','Tí phá hỏng tài khoản game của bạn bằng cách xâm nhập trái phép, gây thiệt hại. Tí có phải bồi thường không?','["Không phải bồi thường", "Chỉ bị phạt hành chính", "Đúng", "Sai"]'::jsonb,2,'Gây thiệt hại – phải bồi thường.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','HHANM-37'),
(241,4,3,ARRAY['pháp luật']::text[],'img/luat-2.svg','Hệ thống đã được xác định cấp độ theo luật cũ có thời gian chuyển tiếp bao lâu?','["12 tháng kể từ ngày luật mới có hiệu lực", "06 tháng", "36 tháng", "24 tháng"]'::jsonb,0,'Chuyển tiếp 12 tháng – khỏi lo “sốc luật”.','Điều 45 Luật An ninh mạng số 116/2025/QH15','HHANM-38'),
(242,4,3,ARRAY['pháp luật']::text[],'img/luat.svg','Phòng IT có 5 người: ai bắt buộc phải đi tập huấn kỹ năng chuyên sâu về an ninh mạng?','["Học sinh tiểu học", "Công nhân xây dựng", "Nhân viên văn phòng bình thường", "Người trực tiếp quản trị hệ thống thông tin Cấp độ 3, 4, 5"]'::jsonb,3,'Quản trị hệ thống cấp độ 3, 4, 5 – bắt buộc tập huấn.','Điều 34 Luật An ninh mạng số 116/2025/QH15','HHANM-39'),
(243,4,1,ARRAY['pháp luật']::text[],'img/luat.svg','Ông nội hỏi Cún Bông: "Sao Nhà nước lại ưu tiên dạy an ninh mạng cho trẻ con và người già như ông?"','["Để họ bán hàng đa cấp", "Nâng cao khả năng tự bảo vệ quyền và lợi ích trên mạng", "Để họ đi thi đấu game", "Để họ tự cài phần mềm lậu"]'::jsonb,1,'Biết để tự bảo vệ mình trên mạng.','Khoản 1 Điều 35 Luật An ninh mạng số 116/2025/QH15','HHANM-40'),
(244,4,1,ARRAY['pháp luật']::text[],'img/luat-2.svg','Câu nói "Chính phủ thống nhất quản lý nhà nước về an ninh mạng" – đúng hay sai?','["Sai", "Chỉ Bộ Quốc phòng quản lý", "Chỉ Bộ Công an quản lý", "Đúng"]'::jsonb,3,'Cả nước – Chính phủ thống nhất quản lý.','Điều 39 Luật An ninh mạng số 116/2025/QH15','HHANM-41'),
(245,4,2,ARRAY['pháp luật']::text[],'img/luat-1.svg','Mèo Mít làm poster "Bộ Công an quản lý nhà nước về ANM những gì?" Đáp án đầy đủ là?','["Phòng ngừa, đấu tranh chống tội phạm mạng", "Kiểm tra, thanh tra về ANM", "Xây dựng chiến lược bảo vệ ANM", "Tất cả các nội dung trên"]'::jsonb,3,'Bộ Công an: phòng chống tội phạm, thanh tra, chiến lược.','Điều 39 Luật An ninh mạng số 116/2025/QH15','HHANM-42'),
(246,4,3,ARRAY['pháp luật']::text[],'img/luat-1.svg','Chị kế toán đơn vị dùng ngân sách nhà nước tính kinh phí: tối thiểu bao nhiêu % kinh phí CNTT phải dành cho an ninh mạng?','["5%", "20%", "10%", "15%"]'::jsonb,3,'15% tiền CNTT dành cho an ninh mạng.','Điều 38 Luật An ninh mạng số 116/2025/QH15','HHANM-43'),
(247,4,1,ARRAY['pháp luật']::text[],'img/luat-2.svg','Cún Bông hỏi: "Lực lượng chuyên trách bảo vệ an ninh mạng ở đâu ạ?"','["Bộ Công an", "Bộ Quốc phòng", "Cả a và b đều đúng", "Mọi doanh nghiệp"]'::jsonb,2,'Chuyên trách ANM: Bộ Công an và Bộ Quốc phòng.','Điều 30 Luật An ninh mạng số 116/2025/QH15','HHANM-44'),
(248,4,2,ARRAY['tấn công mạng']::text[],'img/hack.svg','Một khách hàng mua dịch vụ bảo mật để… che giấu hành vi phạm pháp. Doanh nghiệp ANM phải từ chối – đúng hay sai?','["Vẫn cung cấp nếu trả tiền cao", "Sai", "Đúng", "Chỉ từ chối khi có lệnh tòa án"]'::jsonb,2,'Khách phạm luật – trả bao nhiêu cũng từ chối.','Điều 29 Luật An ninh mạng số 116/2025/QH15','HHANM-45'),
(249,4,1,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Tí hỏi: "Dịch vụ an ninh mạng là gì vậy anh?" Đâu là đáp án đầy đủ?','["Tư vấn an ninh mạng", "Ứng cứu sự cố an ninh mạng", "Khôi phục dữ liệu", "Tất cả các dịch vụ trên"]'::jsonb,3,'Tư vấn, ứng cứu, khôi phục – đều là dịch vụ ANM.','Điều 28 Luật An ninh mạng số 116/2025/QH15','HHANM-46'),
(250,4,1,ARRAY['tấn công mạng']::text[],'img/hack.svg','Mèo Mít đi hội chợ công nghệ. Sản phẩm an ninh mạng gồm loại nào?','["Sản phẩm mật mã dân sự", "Sản phẩm chống tấn công, xâm nhập", "Sản phẩm giám sát an ninh mạng", "Tất cả các loại trên"]'::jsonb,3,'Mật mã, chống xâm nhập, giám sát – đều là sản phẩm ANM.','Điều 28 Luật An ninh mạng số 116/2025/QH15','HHANM-47'),
(251,4,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Tí giữ "kho báu dữ liệu" của lớp. Bảo đảm an ninh dữ liệu cần biện pháp gì?','["Kỹ thuật, tổ chức và pháp lý", "Chỉ biện pháp pháp lý", "Chỉ biện pháp kỹ thuật", "Chỉ biện pháp tổ chức"]'::jsonb,0,'Kỹ thuật + tổ chức + pháp lý = dữ liệu an toàn.','Điều 26 Luật An ninh mạng số 116/2025/QH15','HHANM-48'),
(252,1,1,ARRAY['game']::text[],'img/game.svg','Cún Bông 9 tuổi hỏi: "Con được chơi game học tập và vào câu lạc bộ trên mạng không mẹ?" Trẻ em có quyền vui chơi trên mạng không?','["Sai", "Chỉ trẻ em từ 15 tuổi", "Đúng", "Chỉ khi có sự đồng ý của nhà trường"]'::jsonb,2,'Trẻ em được vui chơi, vui mà an toàn mới hay!','Khoản 1 Điều 16 Luật An ninh mạng số 116/2025/QH15','HHANM-49'),
(253,4,1,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Trong phim gián điệp, nhân vật làm nhiều việc mờ ám trên mạng. Hành vi nào là gián điệp mạng?','["Xâm nhập trái phép để chiếm đoạt bí mật nhà nước", "Cố ý làm lộ bí mật nhà nước trên mạng", "Nghe lén cuộc đàm thoại trái phép trên mạng", "Tất cả các hành vi trên"]'::jsonb,3,'Xâm nhập, làm lộ bí mật, nghe lén – đều là gián điệp mạng.','Điều 15 Luật An ninh mạng số 116/2025/QH15','HHANM-50'),
(254,4,3,ARRAY['pháp luật']::text[],'img/luat-1.svg','Bộ Y tế có đội bảo vệ ANM riêng. Lực lượng bảo vệ ANM tại bộ, ngành do ai trực tiếp quản lý?','["Ủy ban nhân dân cấp xã", "Bộ Công an", "Bộ Quốc phòng", "Cơ quan, tổ chức chủ quản hệ thống thông tin"]'::jsonb,3,'Đội ANM ở bộ nào – bộ đó (chủ quản) quản lý.','Điều 30 Luật An ninh mạng số 116/2025/QH15','HHANM-51'),
(255,4,2,ARRAY['tấn công mạng']::text[],'img/hack.svg','Doanh nghiệp bán phần mềm bảo mật phát hiện khách dùng sản phẩm để làm việc phạm pháp. Phải làm gì?','["Khách hàng là cá nhân", "Khách hàng là người quen", "Khách hàng vi phạm pháp luật về sử dụng sản phẩm", "Khách hàng mua số lượng lớn"]'::jsonb,2,'Khách phạm pháp – ngừng bán.','Điều 29 Luật An ninh mạng số 116/2025/QH15','HHANM-52'),
(256,4,1,ARRAY['tấn công mạng']::text[],'img/hack.svg','Công ty thuê đội chuyên gia "kiểm tra, đánh giá an ninh mạng". Hoạt động này là gì?','["Thủ tục hành chính", "Dịch vụ an ninh mạng", "Hoạt động giải trí", "Sản phẩm an ninh mạng"]'::jsonb,1,'Kiểm tra, đánh giá ANM là một dịch vụ.','Điều 28 Luật An ninh mạng số 116/2025/QH15','HHANM-53'),
(257,4,3,ARRAY['pháp luật']::text[],'img/luat-1.svg','Ai ban hành Quy chuẩn kỹ thuật quốc gia về an ninh mạng?','["Bộ trưởng Bộ Công an", "Bộ Khoa học Công nghệ", "Bộ Xây dựng", "Bộ Giáo dục"]'::jsonb,0,'Quy chuẩn ANM – Bộ trưởng Bộ Công an ban hành.','Điều 27 Luật An ninh mạng số 116/2025/QH15','HHANM-54'),
(258,4,2,ARRAY['tin giả']::text[],'img/tingia-1.svg','Hai phe tài khoản ảo "đấu khẩu" bằng tin giả trên mạng gây hỗn loạn. Xung đột thông tin trên mạng gây tổn hại điều gì?','["Gây tổn hại đến an ninh quốc gia, trật tự an toàn xã hội", "Chỉ ảnh hưởng đến cá nhân", "Chỉ ảnh hưởng đến tốc độ mạng", "Chỉ ảnh hưởng đến doanh thu quảng cáo"]'::jsonb,0,'Xung đột thông tin – hại an ninh, trật tự xã hội.','Điều 22 Luật An ninh mạng số 116/2025/QH15','HHANM-55'),
(259,4,2,ARRAY['pháp luật']::text[],'img/luat.svg','Cơ quan nhà nước triển khai bảo vệ an ninh mạng. Có cần đầu tư hạ tầng không?','["Chỉ đầu tư cho máy tính của lãnh đạo", "Chỉ đầu tư khi có sự cố", "Không, chỉ cần mua phần mềm", "Có, đầu tư phù hợp với điều kiện bảo đảm ANM"]'::jsonb,3,'Bảo vệ ANM – cần đầu tư đúng chỗ.','Điều 23 Luật An ninh mạng số 116/2025/QH15','HHANM-56'),
(260,4,3,ARRAY['tấn công mạng']::text[],'img/hack-2.svg','Chủ quản hệ thống thông tin quan trọng về an ninh quốc gia có trách nhiệm gì về kiểm tra ANM?','["Tự kiểm tra hàng năm", "Đánh giá điều kiện ANM khi thiết lập, mở rộng", "Báo cáo kết quả kiểm tra định kỳ bằng văn bản", "Tất cả các đáp án trên"]'::jsonb,3,'Hệ thống quan trọng – tự kiểm, đánh giá, báo cáo đủ cả.','Điều 11 Luật An ninh mạng số 116/2025/QH15','HHANM-57'),
(261,4,2,ARRAY['tin giả']::text[],'img/tingia-2.svg','Fanpage đăng nội dung vi phạm pháp luật, cơ quan chức năng yêu cầu gỡ. Doanh nghiệp phải gỡ chậm nhất bao lâu?','["24 giờ", "48 giờ", "72 giờ", "12 giờ"]'::jsonb,0,'Gỡ nội dung vi phạm: trong 24 giờ.','Điều 25 Luật An ninh mạng số 116/2025/QH15','HHANM-58'),
(262,4,3,ARRAY['tin giả']::text[],'img/tingia-1.svg','Tình huống khẩn cấp: tin xâm phạm an ninh quốc gia lan nhanh. Doanh nghiệp phải xóa chậm nhất trong bao lâu?','["12 giờ", "03 giờ", "06 giờ", "01 giờ"]'::jsonb,2,'Khẩn cấp – 6 giờ phải xóa.','Điều 25 Luật An ninh mạng số 116/2025/QH15','HHANM-59'),
(263,4,2,ARRAY['pháp luật']::text[],'img/luat.svg','Một ứng dụng nước ngoài muốn kinh doanh dịch vụ mạng tại Việt Nam. Họ phải làm gì?','["Chỉ cần có trang web tiếng Việt", "Không cần đại diện pháp lý", "Chỉ cần cung cấp dịch vụ từ xa", "Đặt chi nhánh hoặc văn phòng đại diện tại Việt Nam"]'::jsonb,3,'Kinh doanh ở Việt Nam – có chi nhánh hoặc văn phòng đại diện.','Điều 25 Luật An ninh mạng số 116/2025/QH15','HHANM-60'),
(264,4,3,ARRAY['tấn công mạng']::text[],'img/hack.svg','Phim bom tấn: mạng quốc gia đang bị tấn công dữ dội, cả phòng chỉ huy hét "Ngắt cổng quốc tế!". Ngoài đời, ai có thẩm quyền quyết định việc này?','["Trưởng công an xã", "Bộ trưởng Bộ Công an (theo ủy quyền của Thủ tướng)", "Giám đốc công ty viễn thông", "Hiệu trưởng nhà trường"]'::jsonb,1,'Ngắt cổng quốc tế – Bộ trưởng Bộ Công an theo ủy quyền Thủ tướng.','Điều 20 Luật An ninh mạng số 116/2025/QH15','HHANM-61'),
(265,4,2,ARRAY['tin giả']::text[],'img/tingia-1.svg','Chị Hoa viết bài cho fanpage công ty và phát hiện trong bài có nội dung vi phạm pháp luật. Người soạn thảo thông tin phải làm gì?','["Gỡ bỏ thông tin", "Chịu trách nhiệm theo quy định của pháp luật", "Phối hợp với lực lượng chuyên trách", "Tất cả các đáp án trên"]'::jsonb,3,'Lỡ đăng sai – gỡ, chịu trách nhiệm, phối hợp.','Điều 14 Luật An ninh mạng số 116/2025/QH15','HHANM-62'),
(266,4,2,ARRAY['tấn công mạng']::text[],'img/hack-2.svg','Có người đăng tài liệu "MẬT" của nhà nước lên mạng để câu like. Cơ quan nào phát hiện, xử lý?','["Bộ Y tế", "Bộ Tài chính", "Bộ Nông nghiệp", "Bộ Công an (trừ trường hợp quân sự, cơ yếu)"]'::jsonb,3,'Bí mật nhà nước bị đăng – Bộ Công an vào cuộc.','Điều 15 Luật An ninh mạng số 116/2025/QH15','HHANM-63'),
(267,4,2,ARRAY['pháp luật']::text[],'img/luat.svg','Nhà đầu tư hỏi: Xây hạ tầng công nghiệp an ninh mạng thì được ưu đãi gì?','["Chỉ ưu đãi về nước", "Chỉ ưu đãi về điện", "Không có ưu đãi", "Thuế, đất đai"]'::jsonb,3,'Công nghiệp ANM – ưu đãi thuế, đất đai.','Điều 37 Luật An ninh mạng số 116/2025/QH15','HHANM-64'),
(268,2,1,ARRAY['người lạ']::text[],'img/nguoila-1.svg','Bố đăng ký tài khoản cho Cún Bông bằng thông tin của bố. Bố có trách nhiệm gì?','["Giám sát nội dung trẻ em truy cập", "Quản lý nội dung trẻ em chia sẻ", "Cả a và b đều đúng", "Để trẻ tự do sử dụng"]'::jsonb,2,'Bố mẹ đứng tên – bố mẹ giám sát cả xem lẫn chia sẻ.','Khoản 2 Điều 16 Luật An ninh mạng số 116/2025/QH15','HHANM-65'),
(269,4,2,ARRAY['lừa đảo']::text[],'img/linkla-2.svg','Nhà mạng phải ngăn phần mềm độc hại lây lan. Họ làm theo yêu cầu của ai?','["Theo yêu cầu của đối thủ", "Cơ quan nhà nước có thẩm quyền", "Không cần theo yêu cầu của ai", "Theo yêu cầu của khách hàng"]'::jsonb,1,'Chặn mã độc – theo yêu cầu cơ quan có thẩm quyền.','Khoản 4 Điều 17 Luật An ninh mạng số 116/2025/QH15','HHANM-66'),
(270,4,1,ARRAY['tấn công mạng']::text[],'img/hack-2.svg','Trong trò chơi "Ai bảo vệ ai", Tí phải nối: hệ thống thông tin quân sự bị tấn công mạng – ai chủ trì xử lý?','["Bộ Quốc phòng", "Ban Cơ yếu Chính phủ", "Bộ Ngoại giao", "Bộ Công an"]'::jsonb,0,'Quân sự – Bộ Quốc phòng.','Điểm b khoản 4 Điều 18 Luật An ninh mạng số 116/2025/QH15','HHANM-67'),
(271,2,1,ARRAY['báo cáo']::text[],'img/baocao-1.svg','Mèo Mít thấy nhóm lạ bàn kế hoạch "đánh sập mạng" để gây sợ hãi. Phải báo cho ai?','["Không cần báo", "Báo kịp thời cho lực lượng bảo vệ an ninh mạng", "Báo cho người thân", "Báo cho báo chí"]'::jsonb,1,'Thấy dấu hiệu khủng bố mạng – báo ngay lực lượng bảo vệ ANM.','Điều 19 Luật An ninh mạng số 116/2025/QH15','HHANM-68'),
(272,3,2,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Hacker lấy trộm dữ liệu lưu trên mạng của một shop online. Hành vi này có phải "tấn công mạng" không?','["Có", "Chỉ khi dữ liệu đó là bí mật nhà nước", "Chỉ khi tấn công vào ngân hàng", "Không"]'::jsonb,0,'Chiếm đoạt dữ liệu qua mạng = tấn công mạng.','Điểm c khoản 1 Điều 18 Luật An ninh mạng số 116/2025/QH15','HHANM-69'),
(273,3,2,ARRAY['tin giả']::text[],'img/tingia-2.svg','Trên mạng xuất hiện tin kích động bạo loạn, có nguy cơ lan rộng. Tình huống này được gọi là gì?','["Tin đồn bình thường", "Sự cố mạng đơn giản", "Tranh luận xã hội", "Tình huống nguy hiểm về an ninh mạng"]'::jsonb,3,'Kích động bạo loạn trên mạng = tình huống nguy hiểm về ANM.','Điều 20 Luật An ninh mạng số 116/2025/QH15','HHANM-70'),
(274,4,3,ARRAY['pháp luật']::text[],'img/luat.svg','Hệ thống thông tin đã xác định cấp độ theo luật cũ được giữ cấp độ – và phải bảo đảm điều kiện mới trong bao lâu?','["24 tháng", "6 tháng", "Vĩnh viễn", "12 tháng kể từ ngày Luật này có hiệu lực"]'::jsonb,3,'Giữ cấp độ cũ, 12 tháng để chuẩn hóa.','Điều 45 Luật An ninh mạng số 116/2025/QH15','HHANM-71'),
(275,4,3,ARRAY['pháp luật']::text[],'img/luat.svg','Phần mềm bảo mật bán từ năm 2025 phải bảo đảm điều kiện ANM theo luật mới trong bao lâu?','["05 năm", "03 tháng", "12 tháng kể từ ngày Luật này có hiệu lực", "Không cần bảo đảm"]'::jsonb,2,'12 tháng để “lên đời” theo luật mới.','Điều 45 Luật An ninh mạng số 116/2025/QH15','HHANM-72'),
(276,4,2,ARRAY['pháp luật']::text[],'img/luat.svg','Cô hiệu trưởng hỏi: "Ai chủ trì phối hợp với các bộ, ngành để bồi dưỡng kiến thức an ninh mạng?"','["Bộ Quốc phòng", "Bộ Nội vụ", "Bộ Công an", "Bộ Ngoại giao"]'::jsonb,2,'Bồi dưỡng ANM – Bộ Công an chủ trì.','Điều 33 Luật An ninh mạng số 116/2025/QH15','HHANM-73'),
(277,4,2,ARRAY['pháp luật']::text[],'img/luat.svg','Doanh nghiệp đầu tư xây hạ tầng công nghiệp an ninh mạng được hưởng gì?','["Bị hạn chế đầu tư", "Phải đóng phí cao hơn", "Được hưởng ưu đãi về thuế, đất đai", "Không có ưu đãi"]'::jsonb,2,'Xây hạ tầng ANM – được ưu đãi thuế, đất.','Điều 37 Luật An ninh mạng số 116/2025/QH15','HHANM-74'),
(278,4,1,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Tí xem phim về "chiến sĩ an ninh mạng". Lực lượng chuyên trách có quyền gì khi làm nhiệm vụ?','["Kiểm tra an ninh mạng", "Đấu tranh bảo vệ an ninh mạng", "Ứng phó sự cố an ninh mạng", "Tất cả các quyền trên"]'::jsonb,3,'Kiểm tra, đấu tranh, ứng phó – đều thuộc quyền của lực lượng chuyên trách.','Điều 5 Luật An ninh mạng số 116/2025/QH15','HHANM-75'),
(279,2,1,ARRAY['pháp luật']::text[],'img/luat-2.svg','Tí xâm nhập máy tính của bạn, làm mất bài tập lớn. Theo luật, Tí phải làm gì?','["Bị phạt tù", "Phải bồi thường thiệt hại theo quy định", "Chỉ cần xin lỗi", "Không phải làm gì"]'::jsonb,1,'Gây thiệt hại – bồi thường theo quy định.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','HHANM-76'),
(280,4,1,ARRAY['pháp luật']::text[],'img/luat-2.svg','Cô giáo hỏi: "Mục đích cao nhất của Luật An ninh mạng là gì?" Cún Bông giơ tay…','["Tăng doanh thu cho các nhà mạng", "Bảo vệ ANQG, trật tự an toàn xã hội", "Theo dõi thông tin cá nhân", "Cấm sử dụng Internet"]'::jsonb,1,'Luật ANM bảo vệ an ninh quốc gia và trật tự xã hội.','Điều 1 Luật An ninh mạng số 116/2025/QH15; Điều 4 Luật An ninh mạng số 116/2025/QH15','HHANM-77'),
(281,3,2,ARRAY['tin giả']::text[],'img/tingia.svg','Mèo Mít thấy bài viết bôi nhọ chính quyền, xúc phạm quốc kỳ và kêu gọi chiến tranh. Những nội dung nào là tuyên truyền chống Nhà nước, kích động?','["Xuyên tạc, bôi nhọ, phỉ báng chính quyền nhân dân", "Chiến tranh tâm lý, kích động chiến tranh xâm lược", "Xúc phạm quốc kỳ, quốc huy, quốc ca", "Tất cả các phương án trên"]'::jsonb,3,'Bôi nhọ, chiến tranh tâm lý, xúc phạm quốc kỳ – đều bị cấm.','Khoản 1 Điều 13 Luật An ninh mạng số 116/2025/QH15','HHANM-78'),
(282,4,3,ARRAY['tin giả']::text[],'img/tingia.svg','Page "Bóc phốt" bịa chuyện làm mất uy tín một công ty. Hành vi này được quy định ở đâu trong Luật ANM?','["Khoản 3, Điều 13", "Khoản 2, Điều 12", "Khoản 1, Điều 12", "Khoản 4, Điều 13"]'::jsonb,0,'Bịa đặt hại uy tín tổ chức – khoản 3 Điều 13.','Điểm a khoản 3 Điều 13 Luật An ninh mạng số 116/2025/QH15','HHANM-79'),
(283,3,2,ARRAY['tin giả']::text[],'img/tingia-1.svg','Một tài khoản liên tục kích động chia rẽ tôn giáo, chia rẽ các tầng lớp nhân dân. Thông tin phá hoại chính sách đoàn kết bao gồm những gì?','["Kích động, gây mâu thuẫn giữa các tầng lớp nhân dân", "Kích động, gây mâu thuẫn giữa người theo tôn giáo với người không theo tôn giáo", "Phá hoại, cản trở việc thực hiện chính sách đoàn kết quốc tế", "Tất cả các nội dung trên"]'::jsonb,3,'Gây chia rẽ dưới mọi hình thức – đều phá hoại đoàn kết.','Khoản 2 Điều 13 Luật An ninh mạng số 116/2025/QH15','HHANM-80'),
(284,3,2,ARRAY['mua sắm']::text[],'img/muasam-2.svg','Shop A giả logo, mạo danh thương hiệu shop B để bán hàng nhái trên mạng. Bị xử lý theo luật nào?','["Không bị xử lý", "Chỉ Luật Dân sự", "Luật An ninh mạng và các luật liên quan", "Chỉ Luật Hình sự"]'::jsonb,2,'Nhái thương hiệu trên mạng – Luật ANM và các luật liên quan.','Điểm c khoản 3 Điều 13 Luật An ninh mạng số 116/2025/QH15','HHANM-81'),
(285,3,1,ARRAY['tin giả']::text[],'img/tingia.svg','Ai đó đăng nội dung đồi trụy lên nhóm chat. Việc đăng tải này bị nghiêm cấm theo luật nào?','["Luật Đất đai", "Luật An ninh mạng", "Luật Bảo vệ môi trường", "Luật Giao thông"]'::jsonb,1,'Đồi trụy trên mạng – Luật An ninh mạng cấm.','Điểm d khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','HHANM-82'),
(286,2,1,ARRAY['mua sắm']::text[],'img/muasam.svg','Có tài khoản rao bán pháo nổ, ma túy trên mạng. Đây là hành vi vi phạm gì?','["Vi phạm về sở hữu trí tuệ", "Vi phạm về thuế", "Vi phạm về trật tự, an toàn xã hội", "Vi phạm về môi trường"]'::jsonb,2,'Mua bán hàng cấm trên mạng – vi phạm trật tự an toàn xã hội.','Điểm đ khoản 4 Điều 13 Luật An ninh mạng số 116/2025/QH15','HHANM-83'),
(287,4,2,ARRAY['tấn công mạng']::text[],'img/hack-2.svg','Admin website trường phát hiện có bài vi phạm an ninh quốc gia trên hệ thống. Chủ quản phải làm gì?','["Gỡ bỏ thông tin vi phạm", "Triển khai biện pháp quản lý, kỹ thuật để ngăn chặn", "Báo cáo cơ quan chuyên trách bảo vệ ANM", "Tất cả các trách nhiệm trên"]'::jsonb,3,'Gỡ, chặn, báo cáo – làm đủ cả ba.','Điều 14 Luật An ninh mạng số 116/2025/QH15','HHANM-84'),
(288,4,2,ARRAY['tin giả']::text[],'img/tingia-1.svg','Lực lượng chuyên trách bảo vệ ANM có thẩm quyền gì với thông tin xâm phạm an ninh quốc gia?','["Áp dụng biện pháp kỹ thuật để xử lý thông tin", "Yêu cầu doanh nghiệp gỡ bỏ thông tin", "Đấu tranh, phòng chống hành vi vi phạm", "Tất cả các thẩm quyền trên"]'::jsonb,3,'Xử lý kỹ thuật, yêu cầu gỡ, đấu tranh – đều là thẩm quyền.','Điều 14 Luật An ninh mạng số 116/2025/QH15','HHANM-85'),
(289,4,1,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Trong phim, "điệp viên mạng" làm đủ trò. Gián điệp mạng gồm những hành vi nào?','["Chiếm đoạt, mua bán, cố ý làm lộ thông tin bí mật nhà nước", "Cố ý xóa, làm hư hỏng thông tin thuộc bí mật nhà nước", "Nghe lén, ghi âm trái phép các cuộc đàm thoại trên mạng", "Tất cả các hành vi trên"]'::jsonb,3,'Lộ, xóa bí mật, nghe lén – đều là gián điệp mạng.','Điều 15 Luật An ninh mạng số 116/2025/QH15','HHANM-86'),
(290,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Một cán bộ soạn văn bản mật trên máy tính. Khi lưu trữ, phải làm gì?','["Phải bảo đảm an toàn, bí mật theo quy định pháp luật", "Chỉ cần đặt mật khẩu đơn giản", "Không được lưu trữ trên mạng Internet", "Cả a và c đều đúng"]'::jsonb,3,'Văn bản mật – giữ an toàn và không lưu lên Internet.','Điều 15 Luật An ninh mạng số 116/2025/QH15','HHANM-87'),
(291,2,1,ARRAY['người lạ']::text[],'img/nguoila-1.svg','Ứng dụng video mà Cún Bông hay xem có trách nhiệm gì với trẻ em?','["Kiểm soát nội dung để không gây nguy hại cho trẻ em", "Ngăn chặn chia sẻ và xóa bỏ thông tin xâm hại trẻ em", "Phối hợp với cơ quan chức năng để xử lý", "Tất cả các trách nhiệm trên"]'::jsonb,3,'Nền tảng phải kiểm soát, chặn, xóa nội dung hại trẻ và phối hợp xử lý.','Khoản 3 Điều 16 Luật An ninh mạng số 116/2025/QH15','HHANM-88'),
(292,4,3,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Bộ Công an có trách nhiệm gì trong phòng, chống gián điệp mạng?','["Kiểm tra ANM đối với hệ thống thông tin quan trọng về ANQG", "Giám sát ANM đối với hệ thống thông tin quan trọng về ANQG", "Phát hiện, xử lý hành vi đăng tải bí mật nhà nước", "Tất cả các trách nhiệm trên"]'::jsonb,3,'Chống gián điệp mạng: kiểm tra, giám sát, xử lý.','Điều 15 Luật An ninh mạng số 116/2025/QH15','HHANM-89'),
(293,1,1,ARRAY['quyền riêng tư']::text[],'img/anhrieng-1.svg','Tí hỏi: "Chuyện riêng của con trên mạng có được giữ kín không?" Câu "Trẻ em có quyền giữ chuyện riêng tư" là đúng hay sai?','["Chỉ trẻ em trên 14 tuổi", "Tùy vào loại mạng xã hội", "Sai", "Đúng"]'::jsonb,3,'Chuyện riêng của em, không ai được xem!','Khoản 1 Điều 16 Luật An ninh mạng số 116/2025/QH15','HHANM-90'),
(294,3,2,ARRAY['báo cáo']::text[],'img/baocao-1.svg','Bác bảo vệ trường thấy clip xâm hại trẻ em lan trên mạng. Ai phải thông báo cho lực lượng chuyên trách?','["Chỉ trẻ em bị hại", "Chỉ nhà trường", "Cơ quan, tổ chức, cá nhân phát hiện", "Chỉ cha mẹ trẻ em"]'::jsonb,2,'Ai phát hiện – người đó báo.','Khoản 4 Điều 16 Luật An ninh mạng số 116/2025/QH15','HHANM-91'),
(295,4,3,ARRAY['pháp luật']::text[],'img/luat-1.svg','Kế toán cơ quan nhà nước hỏi: tối thiểu bao nhiêu % kinh phí chuyển đổi số, CNTT phải dành cho an ninh mạng?','["20%", "5%", "15%", "10%"]'::jsonb,2,'15% – “mười lăm phần trăm cho áo giáp”.','Điều 38 Luật An ninh mạng số 116/2025/QH15','HHANM-92'),
(296,4,2,ARRAY['pháp luật']::text[],'img/luat-1.svg','Ông nội cầm cuốn luật cũ hỏi: "Luật nào hết hiệu lực khi Luật ANM 2025 chạy?"','["Luật An toàn thông tin mạng năm 2015", "Luật Viễn thông năm 2023", "Luật Công nghệ thông tin năm 2006", "Luật Giao dịch điện tử năm 2023"]'::jsonb,0,'Luật An toàn thông tin mạng 2015 – hết hiệu lực.','Khoản 2 Điều 44 Luật An ninh mạng số 116/2025/QH15','HHANM-93'),
(297,4,2,ARRAY['pháp luật']::text[],'img/luat-1.svg','Giấy phép kinh doanh dịch vụ an toàn thông tin mạng cấp năm 2024 còn dùng được tới khi nào?','["Bị thu hồi ngay", "Hết năm 2026", "Có giá trị mãi mãi", "Hết thời hạn ghi trên giấy phép"]'::jsonb,3,'Giấy phép cũ – dùng đến hết thời hạn ghi trên giấy.','Điều 45 Luật An ninh mạng số 116/2025/QH15','HHANM-94'),
(298,3,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Cún Bông hỏi: "Nhà mạng giữ thông tin của mình bao lâu?" Đáp án đúng nhất là?','["Theo quy định của pháp luật", "Vĩnh viễn", "01 năm", "Không cần lưu trữ"]'::jsonb,0,'Lưu bao lâu – theo quy định pháp luật, không tùy hứng.','Điều 25 Luật An ninh mạng số 116/2025/QH15','HHANM-95'),
(299,4,2,ARRAY['tin giả']::text[],'img/tingia-2.svg','Có yêu cầu gỡ thông tin vi phạm gửi tới nhà mạng (trường hợp thường). Hạn chót là bao lâu?','["48 giờ", "72 giờ", "12 giờ", "24 giờ"]'::jsonb,3,'Trường hợp thường: 24 giờ.','Điều 25 Luật An ninh mạng số 116/2025/QH15','HHANM-96'),
(300,4,2,ARRAY['pháp luật']::text[],'img/luat.svg','Vì sao phải bảo vệ hạ tầng không gian mạng quốc gia? Đáp án đầy đủ nhất?','["Bảo đảm chủ quyền lãnh thổ trên không gian mạng", "Thúc đẩy kinh tế - xã hội", "Bảo vệ quyền lợi hợp pháp của cá nhân", "Tất cả các mục đích trên"]'::jsonb,3,'Bảo vệ hạ tầng mạng – vì chủ quyền, kinh tế và quyền lợi người dân.','Điều 24 Luật An ninh mạng số 116/2025/QH15','HHANM-97'),
(301,4,2,ARRAY['pháp luật']::text[],'img/luat.svg','Cơ quan nhà nước triển khai bảo vệ ANM gồm những nội dung nào?','["Xây dựng quy chế sử dụng mạng máy tính nội bộ", "Ứng dụng công nghệ bảo vệ hệ thống thông tin", "Bồi dưỡng kiến thức ANM cho cán bộ, nhân viên", "Tất cả các nội dung trên"]'::jsonb,3,'Quy chế, công nghệ, bồi dưỡng – đủ bộ.','Điều 23 Luật An ninh mạng số 116/2025/QH15','HHANM-98'),
(302,4,2,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Nhà nước khuyến khích các cơ quan, tổ chức tự chủ về điều gì trong an ninh mạng?','["Sản xuất, kiểm tra, đánh giá thiết bị số và dịch vụ mạng", "Không khuyến khích tự chủ", "Chỉ tự chủ về nhân sự hành chính", "Chỉ tự chủ về kinh phí"]'::jsonb,0,'Tự chủ: sản xuất, kiểm tra, đánh giá thiết bị số và dịch vụ mạng.','Điều 37 Luật An ninh mạng số 116/2025/QH15','HHANM-99'),
(303,4,2,ARRAY['tin giả']::text[],'img/tingia.svg','Tí tưởng "xung đột thông tin trên không gian mạng" là hai bạn cãi nhau trong nhóm chat. Thật ra nó là gì?','["Người mua và người bán hàng", "Các tổ chức trong và ngoài nước sử dụng biện pháp công nghệ gây hại cho nhau", "Hai cá nhân cãi nhau", "Hai máy tính bị virus"]'::jsonb,1,'Xung đột thông tin – giữa các tổ chức dùng công nghệ gây hại nhau.','Điều 22 Luật An ninh mạng số 116/2025/QH15','HHANM-100'),
(304,4,1,ARRAY['pháp luật']::text[],'img/luat-1.svg','Cún Bông hỏi: "Chú công an mạng làm ở bộ nào?" Lực lượng chuyên trách bảo vệ ANM ở những bộ nào?','["Bộ Y tế và Bộ Giáo dục", "Bộ Ngoại giao và Bộ Tư pháp", "Bộ Công an và Bộ Quốc phòng", "Bộ Tài chính và Bộ Nội vụ"]'::jsonb,2,'Chuyên trách ANM: Bộ Công an và Bộ Quốc phòng.','Điều 30 Luật An ninh mạng số 116/2025/QH15','HHANM-101'),
(305,4,2,ARRAY['tấn công mạng']::text[],'img/hack.svg','Hệ thống của trường bị sự cố an ninh mạng. Chủ quản hệ thống phải làm gì?','["Xóa hết dấu vết sự cố", "Tạm dừng mạng vĩnh viễn", "Tự ý sửa chữa không cần báo cáo", "Báo cáo ngay cho cơ quan chuyên trách"]'::jsonb,3,'Có sự cố – báo ngay cơ quan chuyên trách, đừng xóa dấu vết.','Điều 40 Luật An ninh mạng số 116/2025/QH15','HHANM-102'),
(306,4,2,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Hệ thống giám sát ANM của một cơ quan phải kết nối về đâu?','["Trung tâm An ninh mạng quốc gia thuộc Bộ Công an hoặc Trung tâm An ninh mạng của tỉnh, thành phố", "Trung tâm điện máy gần nhất", "Không cần kết nối", "Cửa hàng máy tính"]'::jsonb,0,'Kết nối về Trung tâm An ninh mạng quốc gia hoặc của tỉnh.','Điều 40 Luật An ninh mạng số 116/2025/QH15','HHANM-103'),
(307,4,2,ARRAY['pháp luật']::text[],'img/luat.svg','Bộ Công an có trách nhiệm gì trong quản lý nhà nước về ANM?','["Xây dựng chiến lược, kế hoạch bảo vệ ANM", "Phòng ngừa, đấu tranh với hoạt động xâm phạm ANM", "Kiểm tra, thanh tra về ANM", "Tất cả các trách nhiệm trên"]'::jsonb,3,'Chiến lược, phòng ngừa, thanh tra – Bộ Công an lo cả.','Điều 39 Luật An ninh mạng số 116/2025/QH15','HHANM-104'),
(308,4,3,ARRAY['pháp luật']::text[],'img/luat-1.svg','Ban Cơ yếu Chính phủ giúp Bộ trưởng Bộ Quốc phòng quản lý nội dung gì về ANM?','["Quản lý về trò chơi trực tuyến", "Quản lý nhà nước về mật mã dân sự và ANM thuộc phạm vi quản lý", "Quản lý về thiết bị điện tử gia dụng", "Quản lý về mạng xã hội"]'::jsonb,1,'Cơ yếu: mật mã dân sự và ANM trong phạm vi quản lý.','Điều 39 Luật An ninh mạng số 116/2025/QH15','HHANM-105'),
(309,4,1,ARRAY['pháp luật']::text[],'img/luat.svg','Mèo Mít viết lên lịch bàn học: Luật An ninh mạng 116/2025/QH15 có hiệu lực từ ngày nào?','["01/07/2026", "01/03/2026", "01/01/2027", "01/01/2026"]'::jsonb,0,'01/7/2026.','Khoản 1 Điều 44 Luật An ninh mạng số 116/2025/QH15','HHANM-106'),
(310,4,2,ARRAY['pháp luật']::text[],'img/luat.svg','Theo Điều 43, cụm từ "an toàn thông tin mạng" trong các luật liên quan thường được thay bằng cụm từ nào?','["Tin học văn phòng", "An ninh mạng", "Mạng máy tính", "Bảo mật tuyệt đối"]'::jsonb,1,'“An toàn thông tin mạng” đổi thành “an ninh mạng”.','Điều 43 Luật An ninh mạng số 116/2025/QH15','HHANM-107'),
(311,4,3,ARRAY['pháp luật']::text[],'img/luat-1.svg','Luật ANM 2025 sửa đổi, bổ sung luật nào liên quan?','["Luật Lưu trữ", "Luật Bảo vệ quyền lợi người tiêu dùng", "Luật Phí và lệ phí", "Tất cả các luật trên"]'::jsonb,3,'Lưu trữ, bảo vệ người tiêu dùng, phí và lệ phí – đều được sửa.','Điều 43 Luật An ninh mạng số 116/2025/QH15','HHANM-108'),
(312,3,2,ARRAY['pháp luật']::text[],'img/luat-2.svg','Anh Ba xâm phạm ANM thì bị xử lý thế nào?','["Xử phạt vi phạm hành chính", "Tùy tính chất, mức độ vi phạm mà áp dụng các biện pháp trên", "Xử lý kỷ luật", "Truy cứu trách nhiệm hình sự"]'::jsonb,1,'Tùy mức độ: kỷ luật, phạt hành chính hoặc hình sự.','Khoản 2 Điều 42 Luật An ninh mạng số 116/2025/QH15','HHANM-109'),
(313,3,1,ARRAY['tài khoản']::text[],'img/taikhoan-1.svg','Cún Bông có tài khoản học trực tuyến. Người dùng mạng có trách nhiệm gì?','["Tuân thủ quy định của pháp luật về ANM", "Bảo mật thông tin đăng ký tài khoản của mình", "Kịp thời cung cấp thông tin liên quan đến bảo vệ ANM cho cơ quan thẩm quyền", "Tất cả các trách nhiệm trên"]'::jsonb,3,'Tuân thủ luật, giữ tài khoản, báo cáo khi cần.','Điều 42 Luật An ninh mạng số 116/2025/QH15','HHANM-110'),
(314,4,1,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Trò chơi trí nhớ: "Hệ thống thông tin quân sự – ai bảo vệ?" Tí lật thẻ…','["Bộ Quốc phòng", "Bộ Công an", "Bộ Khoa học và Công nghệ", "Bộ Thông tin và Truyền thông"]'::jsonb,0,'Quân sự – Bộ Quốc phòng.','Điểm b khoản 4 Điều 18 Luật An ninh mạng số 116/2025/QH15','HHANM-111'),
(315,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Lực lượng chuyên trách yêu cầu nhà mạng cung cấp thông tin. Đó là thông tin gì?','["Bí mật đời tư của khách hàng", "Danh bạ điện thoại cá nhân của nhân viên", "Định danh địa chỉ IP của tổ chức, cá nhân sử dụng dịch vụ", "Toàn bộ doanh thu của công ty"]'::jsonb,2,'Nhà mạng cung cấp định danh địa chỉ IP khi được yêu cầu.','Khoản 5 Điều 41 Luật An ninh mạng số 116/2025/QH15','HHANM-112'),
(316,4,1,ARRAY['tài khoản']::text[],'img/taikhoan-1.svg','Nhà mạng gửi tin "Cách phòng tránh mất an toàn khi dùng mạng". Họ phải hướng dẫn gì?','["Cách trốn tránh cơ quan chức năng", "Cách cài đặt phần mềm lậu", "Cách hack tài khoản người khác", "Cách phòng ngừa đối với nguy cơ mất ANM và xử lý sự cố"]'::jsonb,3,'Nhà mạng dạy cách phòng ngừa và xử lý sự cố.','Điều 41 Luật An ninh mạng số 116/2025/QH15','HHANM-113'),
(317,4,2,ARRAY['tấn công mạng']::text[],'img/hack.svg','Ứng dụng ngân hàng gặp sự cố ANM. Doanh nghiệp phải làm gì ngay?','["Phương án tăng giá dịch vụ", "Phương án phá dỡ hệ thống", "Phương án ứng cứu khẩn cấp", "Phương án quảng cáo mới"]'::jsonb,2,'Sự cố xảy ra – kích hoạt ứng cứu khẩn cấp.','Điều 41 Luật An ninh mạng số 116/2025/QH15','HHANM-114'),
(318,4,2,ARRAY['lừa đảo']::text[],'img/linkla.svg','Hộp thư email nhà Tí có bộ lọc mã độc. Câu "Doanh nghiệp thư điện tử phải có hệ thống lọc phần mềm độc hại" là…','["Đúng", "Tùy doanh thu của công ty", "Không bắt buộc", "Sai"]'::jsonb,0,'Email phải có “lưới lọc” mã độc.','Khoản 3 Điều 17 Luật An ninh mạng số 116/2025/QH15','HHANM-115'),
(319,3,1,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Tí đọc truyện về hacker. Tấn công mạng gồm những hoạt động nào?','["Phát tán chương trình tin học gây hại (mã độc)", "Xâm nhập chiếm đoạt dữ liệu, chiếm quyền điều khiển hệ thống", "Gây cản trở, làm tê liệt hoạt động của mạng viễn thông", "Tất cả các phương án trên"]'::jsonb,3,'Phát tán mã độc, chiếm quyền, làm tê liệt – đều là tấn công mạng.','Khoản 1 Điều 18 Luật An ninh mạng số 116/2025/QH15','HHANM-116'),
(320,4,2,ARRAY['pháp luật']::text[],'img/luat-2.svg','Chứng nhận hợp quy về an ninh mạng được thực hiện theo pháp luật về lĩnh vực nào?','["Tiêu chuẩn và quy chuẩn kỹ thuật", "Pháp luật về lao động", "Pháp luật về hình sự", "Pháp luật về đất đai"]'::jsonb,0,'Hợp quy – theo luật tiêu chuẩn và quy chuẩn kỹ thuật.','Điều 27 Luật An ninh mạng số 116/2025/QH15','HHANM-117'),
(321,4,2,ARRAY['tấn công mạng']::text[],'img/hack.svg','Doanh nghiệp bảo mật phải từ chối khách khi nào?','["Khách hàng mua số lượng ít", "Khách hàng vi phạm pháp luật về sử dụng sản phẩm", "Khách hàng không có trang web", "Khách hàng là người nước ngoài"]'::jsonb,1,'Khách dùng sản phẩm phạm pháp – từ chối.','Điều 29 Luật An ninh mạng số 116/2025/QH15','HHANM-118'),
(322,4,1,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Mèo Mít lập danh sách "Dịch vụ an ninh mạng". Đáp án đầy đủ?','["Tư vấn an ninh mạng", "Ứng cứu sự cố an ninh mạng", "Khôi phục dữ liệu", "Cả 3 dịch vụ trên"]'::jsonb,3,'Tư vấn, ứng cứu, khôi phục – cả ba.','Điều 28 Luật An ninh mạng số 116/2025/QH15','HHANM-119'),
(323,4,2,ARRAY['tấn công mạng']::text[],'img/hack.svg','Anh Ba mở công ty bán dịch vụ an ninh mạng. Cần điều kiện gì?','["Chỉ cần có vốn lớn", "Phải có giấy phép kinh doanh theo quy định", "Chỉ cần có máy móc hiện đại", "Không cần điều kiện gì"]'::jsonb,1,'Kinh doanh ANM – phải có giấy phép.','Điều 29 Luật An ninh mạng số 116/2025/QH15','HHANM-120'),
(324,4,2,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Mạng nhà Tí chậm vì đứt cáp – có phải "sự cố an ninh mạng"? Định nghĩa đúng là?','["Sự việc bất ngờ xảy ra xâm phạm ANQG, trật tự an toàn xã hội trên không gian mạng", "Việc mạng bị chậm do đứt cáp", "Việc quên mật khẩu đăng nhập", "Việc máy tính bị hỏng phần cứng"]'::jsonb,0,'Sự cố ANM: sự việc bất ngờ xâm phạm an ninh, trật tự trên mạng.','Điều 2 Luật An ninh mạng số 116/2025/QH15','HHANM-121'),
(325,4,2,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Hội chợ công nghệ trưng bày "Sản phẩm an ninh mạng". Gồm loại nào?','["Sản phẩm mật mã dân sự", "Sản phẩm kiểm tra, đánh giá ANM", "Sản phẩm chống tấn công, xâm nhập", "Cả 3 loại trên"]'::jsonb,3,'Mật mã dân sự, kiểm tra đánh giá, chống xâm nhập – đều là sản phẩm ANM.','Điều 28 Luật An ninh mạng số 116/2025/QH15','HHANM-122'),
(326,4,1,ARRAY['pháp luật']::text[],'img/luat.svg','Cún Bông hỏi: "Ai quản lý an ninh mạng của cả nước?"','["Viện kiểm sát nhân dân tối cao", "Tòa án nhân dân tối cao", "Chính phủ", "Quốc hội"]'::jsonb,2,'Chính phủ thống nhất quản lý.','Điều 39 Luật An ninh mạng số 116/2025/QH15','HHANM-123'),
(327,4,3,ARRAY['pháp luật']::text[],'img/luat.svg','Lực lượng bảo vệ ANM tại bộ, ngành, UBND tỉnh do ai quản lý?','["Bộ Công an", "Doanh nghiệp", "Thủ tướng Chính phủ", "Cơ quan, tổ chức chủ quản trực tiếp quản lý hệ thống thông tin"]'::jsonb,3,'Ai chủ quản hệ thống – người đó quản lý lực lượng.','Điều 30 Luật An ninh mạng số 116/2025/QH15','HHANM-124'),
(328,4,1,ARRAY['pháp luật']::text[],'img/luat-2.svg','Tí hỏi: "Giỏi an ninh mạng thì Nhà nước có chăm lo không?"','["Chỉ dành cho người có bằng tiến sĩ", "Ưu tiên tuyển chọn, đào tạo, bồi dưỡng, đãi ngộ", "Không có chính sách đặc biệt", "Buộc phải làm việc không lương"]'::jsonb,1,'Nhân tài ANM được ưu tiên tuyển chọn, đãi ngộ.','Điều 31 Luật An ninh mạng số 116/2025/QH15','HHANM-125'),
(329,4,1,ARRAY['pháp luật']::text[],'img/luat.svg','Mèo Mít muốn vào lực lượng ANM khi lớn. Cần tiêu chuẩn gì?','["Phẩm chất đạo đức tốt, đủ sức khỏe", "Có trình độ, kiến thức về ANM, CNTT", "Có nguyện vọng", "Tất cả các tiêu chuẩn trên"]'::jsonb,3,'Đạo đức, sức khỏe, trình độ, nguyện vọng – đủ cả.','Điều 32 Luật An ninh mạng số 116/2025/QH15','HHANM-126'),
(330,4,3,ARRAY['pháp luật']::text[],'img/luat-2.svg','Ai xây dựng dự thảo tiêu chuẩn quốc gia về an ninh mạng?','["Bộ Công an", "Bộ Quốc phòng", "Bộ Thông tin và Truyền thông", "Bộ Khoa học và Công nghệ"]'::jsonb,0,'Tiêu chuẩn ANM – Bộ Công an dự thảo.','Điều 27 Luật An ninh mạng số 116/2025/QH15','HHANM-127'),
(331,4,2,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Công ty muốn kinh doanh sản phẩm, dịch vụ ANM phải có gì?','["Nhiều nhân viên giỏi", "Vốn trên 1000 tỷ", "Giấy phép kinh doanh sản phẩm, dịch vụ ANM", "Văn phòng to đẹp"]'::jsonb,2,'Có giấy phép mới được kinh doanh ANM.','Điều 29 Luật An ninh mạng số 116/2025/QH15','HHANM-128'),
(332,4,1,ARRAY['pháp luật']::text[],'img/luat.svg','Lực lượng chuyên trách bảo vệ an ninh mạng ở đâu?','["Bộ Công an", "Bộ Quốc phòng", "Cả a và b đều đúng", "Chỉ tại các tỉnh thành lớn"]'::jsonb,2,'Bộ Công an và Bộ Quốc phòng – cả hai.','Điều 30 Luật An ninh mạng số 116/2025/QH15','HHANM-129'),
(333,4,1,ARRAY['pháp luật']::text[],'img/luat-1.svg','Công dân đủ đạo đức, sức khỏe, trình độ có thể được tuyển vào lực lượng ANM – đúng hay sai?','["Chỉ tuyển người nước ngoài", "Đúng", "Chỉ tuyển nam giới", "Sai"]'::jsonb,1,'Đủ tiêu chuẩn – có thể được tuyển chọn.','Điều 32 Luật An ninh mạng số 116/2025/QH15','HHANM-130'),
(334,4,1,ARRAY['pháp luật']::text[],'img/luat-2.svg','Mèo Mít hỏi chị: "Ở trường, học về an ninh mạng trong môn nào?" Chị trả lời…','["Môn Vẽ", "Môn Giáo dục quốc phòng và an ninh", "Môn Toán", "Môn Ngoại ngữ"]'::jsonb,1,'An ninh mạng học trong môn Giáo dục quốc phòng và an ninh.','Điều 33 Luật An ninh mạng số 116/2025/QH15','HHANM-131'),
(335,4,2,ARRAY['pháp luật']::text[],'img/luat-2.svg','Lực lượng bảo vệ ANM của các bộ, ngành cần bồi dưỡng nghiệp vụ. Cơ quan nào chủ trì?','["Bộ Công an", "Bộ Nội vụ", "Bộ Khoa học Công nghệ", "Bộ Tài chính"]'::jsonb,0,'Bồi dưỡng nghiệp vụ ANM – Bộ Công an chủ trì.','Điều 33 Luật An ninh mạng số 116/2025/QH15','HHANM-132'),
(336,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Một app nước ngoài có nhiều người dùng Việt Nam. Dữ liệu cá nhân người dùng phải lưu ở đâu?','["Không cần lưu trữ", "Tại Việt Nam theo quy định", "Chỉ tại nước ngoài", "Tại trụ sở doanh nghiệp"]'::jsonb,1,'Dữ liệu người dùng Việt – lưu tại Việt Nam theo quy định.','Điều 25 Luật An ninh mạng số 116/2025/QH15','HHANM-133'),
(337,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Công ty của chị Hoa muốn bảo đảm an ninh dữ liệu. Nội dung nào cần làm?','["Xây dựng chính sách bảo đảm an ninh dữ liệu", "Sử dụng mật mã để bảo vệ dữ liệu", "Kiểm tra, đánh giá rủi ro định kỳ", "Tất cả các nội dung trên"]'::jsonb,3,'Chính sách, mật mã, đánh giá rủi ro – làm đủ cả ba.','Điều 26 Luật An ninh mạng số 116/2025/QH15','HHANM-134'),
(338,2,1,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Tí thấy người bán "tool tấn công mạng" trên nhóm chat. Sản xuất, mua bán công cụ tấn công mạng là gì?','["Hành vi được khuyến khích", "Hành vi vi phạm bị nghiêm cấm", "Hành vi kinh doanh tự do", "Chỉ vi phạm khi tấn công thật"]'::jsonb,1,'Bán “vũ khí số” – hành vi bị nghiêm cấm.','Điểm đ khoản 1 Điều 18 Luật An ninh mạng số 116/2025/QH15','HHANM-135'),
(339,4,2,ARRAY['tấn công mạng']::text[],'img/hack-2.svg','Tấn công mạng xâm phạm an ninh quốc gia xảy ra. Lực lượng chuyên trách được làm gì?','["Yêu cầu doanh nghiệp cung cấp thông tin, tài liệu liên quan", "Yêu cầu doanh nghiệp chặn lọc thông tin để ngăn chặn", "Chủ trì, phối hợp với chủ quản hệ thống để xử lý", "Tất cả các phương án trên"]'::jsonb,3,'Yêu cầu thông tin, chặn lọc, chủ trì xử lý – đều được làm.','Khoản 3 Điều 18 Luật An ninh mạng số 116/2025/QH15','HHANM-136'),
(340,4,3,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Tình huống nguy hiểm về ANM xảy ra. Biện pháp xử lý có thể gồm những gì?','["Ngừng cung cấp thông tin mạng tại khu vực cụ thể", "Ngắt cổng kết nối mạng quốc tế", "Bố trí lực lượng ngăn chặn, loại bỏ tình huống", "Tất cả các biện pháp trên"]'::jsonb,3,'Ngừng mạng khu vực, ngắt cổng quốc tế, ngăn chặn – đều có thể.','Điều 20 Luật An ninh mạng số 116/2025/QH15','HHANM-137'),
(341,4,2,ARRAY['tấn công mạng']::text[],'img/hack.svg','Tình huống nào là "nguy hiểm về an ninh mạng"?','["Tấn công vào hệ thống thông tin quan trọng về ANQG", "Xuất hiện thông tin kích động bạo loạn có nguy cơ xảy ra", "Tấn công mạng xâm phạm nghiêm trọng chủ quyền quốc gia", "Cả 3 phương án trên"]'::jsonb,3,'Tấn công hệ thống quan trọng, kích động bạo loạn, xâm phạm chủ quyền – đều nguy hiểm.','Điều 20 Luật An ninh mạng số 116/2025/QH15','HHANM-138'),
(342,4,2,ARRAY['tấn công mạng']::text[],'img/hack.svg','Chủ quản hệ thống thông tin rà soát hệ thống định kỳ để làm gì?','["Loại trừ nguy cơ khủng bố mạng", "Để tiết kiệm điện năng", "Để tăng tốc độ mạng", "Để quảng cáo sản phẩm"]'::jsonb,0,'Rà soát định kỳ – loại trừ nguy cơ khủng bố mạng.','Điều 19 Luật An ninh mạng số 116/2025/QH15','HHANM-139'),
(343,4,2,ARRAY['tấn công mạng']::text[],'img/hack.svg','Đấu tranh bảo vệ ANM gồm những nội dung nào?','["Giám sát thông tin mạng và phòng ngừa, đấu tranh xử lý vi phạm", "Sử dụng giải pháp kỹ thuật ngăn chặn thông tin vi phạm", "Làm tê liệt hoạt động sử dụng không gian mạng xâm phạm ANQG", "Tất cả các nội dung trên"]'::jsonb,3,'Giám sát, chặn thông tin vi phạm, vô hiệu hóa kẻ xâm phạm – đủ cả.','Điều 21 Luật An ninh mạng số 116/2025/QH15','HHANM-140'),
(344,4,2,ARRAY['tấn công mạng']::text[],'img/hack.svg','Nghiên cứu, phát triển an ninh mạng gồm những gì?','["Xây dựng hệ thống phần mềm bảo vệ an ninh mạng", "Dự báo an ninh mạng", "Giải quyết nguy cơ đe dọa ANM", "Tất cả các nội dung trên"]'::jsonb,3,'Làm phần mềm, dự báo, giải quyết nguy cơ – đều là nghiên cứu ANM.','Điều 36 Luật An ninh mạng số 116/2025/QH15','HHANM-141'),
(345,4,1,ARRAY['pháp luật']::text[],'img/luat-1.svg','Bà nội và Cún Bông cùng đi học lớp "Lướt mạng an toàn". Nhà nước ưu tiên phổ biến kiến thức ANM cho ai?','["Các hacker chuyên nghiệp", "Người nước ngoài du lịch", "Trẻ em, người cao tuổi", "Các triệu phú"]'::jsonb,2,'Trẻ em và người cao tuổi – được ưu tiên học trước.','Khoản 1 Điều 35 Luật An ninh mạng số 116/2025/QH15','HHANM-142'),
(346,4,3,ARRAY['pháp luật']::text[],'img/luat-1.svg','Ai bắt buộc phải tập huấn kiến thức, kỹ năng chuyên sâu về ANM?','["Học sinh tiểu học", "Mọi người dân dùng internet", "Người trực tiếp quản trị hệ thống thông tin Cấp độ 3, 4, 5", "Nhân viên bán hàng"]'::jsonb,2,'Quản trị hệ thống cấp độ 3, 4, 5 – bắt buộc tập huấn.','Điều 34 Luật An ninh mạng số 116/2025/QH15','HHANM-143'),
(347,4,2,ARRAY['pháp luật']::text[],'img/luat-1.svg','Ai chủ trì bồi dưỡng nghiệp vụ ANM cho cán bộ, công chức, viên chức?','["Bộ Lao động - Thương binh và Xã hội", "Bộ Công an", "Bộ Văn hóa", "Bộ Giáo dục và Đào tạo"]'::jsonb,1,'Bồi dưỡng ANM cho cán bộ – Bộ Công an chủ trì.','Điều 33 Luật An ninh mạng số 116/2025/QH15','HHANM-144'),
(348,4,1,ARRAY['pháp luật']::text[],'img/luat-2.svg','Tí đố em: "Học an ninh mạng ở môn nào?" Không phải Văn, không phải Hóa…','["Môn Hóa học", "Môn Sinh học", "Môn Giáo dục quốc phòng và an ninh", "Môn Văn học"]'::jsonb,2,'Môn Giáo dục quốc phòng và an ninh.','Điều 33 Luật An ninh mạng số 116/2025/QH15','HHANM-145'),
(349,4,3,ARRAY['tin giả']::text[],'img/tingia.svg','Tin xâm phạm an ninh quốc gia lan nhanh, tình huống khẩn cấp. Phải xóa chậm nhất bao lâu?','["06 giờ", "03 giờ", "12 giờ", "24 giờ"]'::jsonb,0,'Khẩn cấp: 06 giờ.','Điều 25 Luật An ninh mạng số 116/2025/QH15','HHANM-146'),
(350,4,1,ARRAY['pháp luật']::text[],'img/luat-2.svg','Nhà nước khuyến khích ai nâng cao năng lực tự chủ về ANM?','["Chỉ cơ quan nhà nước", "Không khuyến khích ai", "Chỉ các doanh nghiệp nước ngoài", "Cơ quan, tổ chức và cá nhân"]'::jsonb,3,'Cơ quan, tổ chức và cá nhân – ai cũng được khuyến khích.','Điều 37 Luật An ninh mạng số 116/2025/QH15','HHANM-147'),
(351,4,2,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Biện pháp bảo vệ an ninh mạng gồm những gì?','["Thẩm định, đánh giá điều kiện ANM", "Kiểm tra, giám sát ANM", "Ứng phó, khắc phục sự cố ANM", "Tất cả các biện pháp trên"]'::jsonb,3,'Thẩm định, giám sát, ứng phó – đều là biện pháp bảo vệ ANM.','Điều 5 Luật An ninh mạng số 116/2025/QH15','HHANM-148'),
(352,4,1,ARRAY['pháp luật']::text[],'img/luat-1.svg','Một nguyên tắc bảo vệ an ninh mạng là đặt dưới sự lãnh đạo của tổ chức nào?','["Đoàn Thanh niên", "Các doanh nghiệp công nghệ", "Hiệp hội Internet", "Đảng Cộng sản Việt Nam"]'::jsonb,3,'Bảo vệ ANM đặt dưới sự lãnh đạo của Đảng Cộng sản Việt Nam.','Điều 4 Luật An ninh mạng số 116/2025/QH15','HHANM-149'),
(353,4,2,ARRAY['pháp luật']::text[],'img/luat-1.svg','Nhà nước ưu tiên bảo vệ an ninh mạng trong những lĩnh vực nào?','["Thương mại điện tử giá rẻ", "Quốc phòng, an ninh, cơ yếu, kinh tế - xã hội trọng điểm", "Mạng xã hội cá nhân", "Giải trí trực tuyến"]'::jsonb,1,'Ưu tiên: quốc phòng, an ninh, cơ yếu, kinh tế – xã hội trọng điểm.','Điều 3 Luật An ninh mạng số 116/2025/QH15','HHANM-150'),
(354,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Công ty bảo mật giữ thông tin khách hàng. Phải lưu giữ, bảo mật bao lâu?','["Không cần lưu giữ", "2 năm", "Theo quy định của pháp luật", "1 năm"]'::jsonb,2,'Lưu bao lâu – theo quy định pháp luật.','Điều 29 Luật An ninh mạng số 116/2025/QH15','HHANM-151'),
(355,4,2,ARRAY['tấn công mạng']::text[],'img/hack-2.svg','Trong phim, nhóm xấu tấn công mạng để mọi người hoảng sợ. "Khủng bố mạng" nhằm mục đích gì?','["Gây hoang mang trong công chúng hoặc làm mất ổn định chính trị", "Để thi đấu game online", "Để thử nghiệm vũ khí mới", "Để tống tiền cá nhân"]'::jsonb,0,'Khủng bố mạng: gây hoang mang hoặc làm mất ổn định chính trị.','Điều 2 Luật An ninh mạng số 116/2025/QH15','HHANM-152'),
(356,4,3,ARRAY['AI-deepfake']::text[],'img/deepfake.svg','Ai đó làm website giả mạo cổng thông tin của cơ quan nhà nước. Hành vi bị cấm ở khoản nào Điều 7 Luật ANM?','["Khoản 4", "Khoản 3", "Khoản 2", "Khoản 1"]'::jsonb,2,'Giả mạo trang thông tin – khoản 2 Điều 7.','Điểm e khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','HHANM-153'),
(357,4,2,ARRAY['tấn công mạng']::text[],'img/hack-2.svg','Gián điệp mạng xâm phạm bí mật nhà nước gồm những hành vi nào?','["Chiếm đoạt, mua bán bí mật nhà nước trên mạng", "Cố ý làm lộ thông tin thuộc bí mật nhà nước", "Nghe lén, ghi hình trái phép cuộc đàm thoại", "Tất cả các hành vi trên"]'::jsonb,3,'Chiếm đoạt, làm lộ, nghe lén – đều là gián điệp mạng.','Điều 15 Luật An ninh mạng số 116/2025/QH15','HHANM-154'),
(358,4,2,ARRAY['tin giả']::text[],'img/tingia-2.svg','Doanh nghiệp nhận yêu cầu xóa thông tin vi phạm (trường hợp bình thường). Phải xóa trong bao lâu?','["48 giờ", "12 giờ", "72 giờ", "24 giờ"]'::jsonb,3,'Bình thường 24 giờ, khẩn cấp 6 giờ.','Điều 25 Luật An ninh mạng số 116/2025/QH15','HHANM-155'),
(359,1,1,ARRAY['người lạ']::text[],'img/nguoila.svg','Cún Bông hỏi: "Trên mạng trẻ em được những quyền gì ạ?"','["Được tiếp cận thông tin, vui chơi, giải trí", "Được bảo vệ bí mật đời sống riêng tư", "Được bảo vệ khỏi các nội dung gây nguy hại", "Cả 3 quyền trên"]'::jsonb,3,'Được chơi, được giữ kín, được bảo vệ – nhớ cả ba nha!','Khoản 1 Điều 16 Luật An ninh mạng số 116/2025/QH15','HHANM-156'),
(360,4,2,ARRAY['tấn công mạng']::text[],'img/hack-2.svg','Tấn công mạng xâm phạm an ninh quốc gia xảy ra. Ai chủ trì xử lý?','["Lực lượng chuyên trách bảo vệ ANM", "Chủ quản hệ thống tự xử lý", "Cửa hàng sửa chữa máy tính", "Ủy ban nhân dân xã"]'::jsonb,0,'Lực lượng chuyên trách bảo vệ ANM chủ trì.','Khoản 3 Điều 18 Luật An ninh mạng số 116/2025/QH15','HHANM-157'),
(361,4,3,ARRAY['pháp luật']::text[],'img/luat-2.svg','Cơ quan nào chủ trì hợp tác quốc tế về an ninh mạng?','["Bộ Thông tin và Truyền thông", "Bộ Công an", "Bộ Giáo dục và Đào tạo", "Bộ Ngoại giao"]'::jsonb,1,'Hợp tác quốc tế về ANM – Bộ Công an chủ trì.','Điều 6 Luật An ninh mạng số 116/2025/QH15','HHANM-158'),
(362,3,1,ARRAY['tin giả']::text[],'img/tingia.svg','Tí thấy bài xuyên tạc lịch sử, bịa đặt vu khống, chống Nhà nước. Hành vi nào bị nghiêm cấm?','["Xuyên tạc lịch sử, phủ nhận thành tựu cách mạng", "Bịa đặt, vu khống thông tin sai sự thật", "Tuyên truyền chống Nhà nước", "Tất cả các hành vi trên"]'::jsonb,3,'Tất cả đều bị nghiêm cấm.','Khoản 1 Điều 7 Luật An ninh mạng số 116/2025/QH15','HHANM-159'),
(363,3,1,ARRAY['lừa đảo']::text[],'img/linkla.svg','Một bạn khoe "viết virus phá máy tính trường cho vui". Hành vi phát tán mã độc phá hoại bị xử lý theo Luật ANM – đúng hay sai?','["Chỉ xử lý hành chính", "Sai", "Đúng", "Chỉ nhắc nhở"]'::jsonb,2,'Viết mã độc phá hoại – sai luật, bị xử lý.','Khoản 4 Điều 7 Luật An ninh mạng số 116/2025/QH15','HHANM-160'),
(364,4,2,ARRAY['tin giả']::text[],'img/tingia-1.svg','Phòng ngừa thông tin xâm phạm an ninh quốc gia là trách nhiệm của ai?','["Chỉ của Bộ Công an", "Chỉ của nhà mạng", "Chủ quản hệ thống thông tin và các cơ quan chức năng", "Chỉ của người dân"]'::jsonb,2,'Chủ quản hệ thống và cơ quan chức năng cùng phòng ngừa.','Điều 14 Luật An ninh mạng số 116/2025/QH15','HHANM-161'),
(365,4,2,ARRAY['pháp luật']::text[],'img/luat-2.svg','Hệ thống thông tin được phân loại thành mấy cấp độ?','["3 cấp độ", "6 cấp độ", "4 cấp độ", "5 cấp độ"]'::jsonb,3,'5 cấp độ – như 5 ngón tay.','Điều 8 Luật An ninh mạng số 116/2025/QH15','HHANM-162'),
(366,4,2,ARRAY['pháp luật']::text[],'img/luat-1.svg','Hệ thống thông tin cấp độ 5 bị sự cố sẽ gây tổn hại đến mức nào?','["Tổn hại đến lợi ích cá nhân", "Tổn hại đặc biệt nghiêm trọng đến an ninh quốc gia", "Tổn hại nghiêm trọng đến lợi ích công cộng", "Tổn hại đến một doanh nghiệp"]'::jsonb,1,'Cấp độ 5 – tổn hại đặc biệt nghiêm trọng an ninh quốc gia.','Điều 8 Luật An ninh mạng số 116/2025/QH15','HHANM-163'),
(367,4,3,ARRAY['pháp luật']::text[],'img/luat-2.svg','Ai quyết định danh mục hệ thống thông tin quan trọng về an ninh quốc gia?','["Bộ trưởng Bộ Quốc phòng", "Chủ tịch nước", "Bộ trưởng Bộ Công an", "Thủ tướng Chính phủ"]'::jsonb,3,'Danh mục hệ thống quan trọng – Thủ tướng quyết định.','Điều 9 Luật An ninh mạng số 116/2025/QH15','HHANM-164'),
(368,4,2,ARRAY['pháp luật']::text[],'img/luat-2.svg','Lĩnh vực nào có hệ thống thông tin quan trọng về an ninh quốc gia?','["Quân sự, an ninh, ngoại giao", "Năng lượng, tài chính, ngân hàng", "Điều khiển giao thông vận tải quốc gia", "Cả 3 phương án trên"]'::jsonb,3,'Quân sự, tài chính, giao thông – đều có hệ thống quan trọng.','Điều 9 Luật An ninh mạng số 116/2025/QH15','HHANM-165'),
(369,4,2,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Hệ thống thông tin quan trọng về ANQG phải kiểm tra an ninh mạng khi nào?','["Trước khi đưa vào vận hành và định kỳ hàng năm", "Khi có sự cố xảy ra", "Không cần kiểm tra", "5 năm một lần"]'::jsonb,0,'Trước khi vận hành và định kỳ hàng năm.','Điều 11 Luật An ninh mạng số 116/2025/QH15','HHANM-166'),
(370,4,3,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Bộ Công an kiểm tra an ninh mạng đột xuất hệ thống của một cơ quan khi nào?','["Có hành vi xâm phạm ANQG", "Có yêu cầu của chủ quản hệ thống", "Khi phát hiện mã độc phát tán", "Cả a và b đều đúng"]'::jsonb,3,'Có xâm phạm ANQG hoặc có yêu cầu của chủ quản.','Điều 12 Luật An ninh mạng số 116/2025/QH15','HHANM-167'),
(371,3,1,ARRAY['tin giả']::text[],'img/tingia-1.svg','Những nội dung kích động bạo loạn, phá rối an ninh trên mạng gồm gì?','["Tuyên truyền xuyên tạc, phỉ báng chính quyền", "Kích động chiến tranh xâm lược", "Xúc phạm quốc kỳ, quốc huy, quốc ca", "Tất cả nội dung trên"]'::jsonb,3,'Xuyên tạc, kích động chiến tranh, xúc phạm quốc kỳ – đều bị cấm.','Khoản 1 Điều 13 Luật An ninh mạng số 116/2025/QH15','HHANM-168'),
(372,4,2,ARRAY['lừa đảo']::text[],'img/linkla-2.svg','Phần mềm độc hại đe dọa an ninh quốc gia. Ai chủ trì phòng chống?','["Bộ Y tế", "Bộ Công an phối hợp với Bộ Quốc phòng", "Bộ Văn hóa", "Bộ Tài chính"]'::jsonb,1,'Bộ Công an chủ trì, phối hợp Bộ Quốc phòng.','Khoản 5 Điều 17 Luật An ninh mạng số 116/2025/QH15','HHANM-169'),
(373,4,1,ARRAY['pháp luật']::text[],'img/luat-1.svg','Nhà nước làm gì để bà ngoại và Tí biết dùng mạng an toàn?','["Thu học phí cao", "Chỉ phát tờ rơi", "Cấm họ dùng mạng", "Ưu tiên phổ biến, hướng dẫn để nâng cao khả năng tự bảo vệ"]'::jsonb,3,'Ưu tiên phổ biến, hướng dẫn để tự bảo vệ.','Khoản 1 Điều 35 Luật An ninh mạng số 116/2025/QH15','HHANM-170'),
(374,4,2,ARRAY['pháp luật']::text[],'img/luat-2.svg','Bảo vệ ANM trong cơ quan nhà nước gồm những nội dung nào?','["Xây dựng quy chế sử dụng mạng máy tính nội bộ", "Ứng dụng giải pháp công nghệ bảo vệ ANM", "Bồi dưỡng kiến thức ANM cho cán bộ", "Tất cả các phương án trên"]'::jsonb,3,'Quy chế, công nghệ, bồi dưỡng – đủ cả.','Điều 23 Luật An ninh mạng số 116/2025/QH15','HHANM-171'),
(375,4,2,ARRAY['pháp luật']::text[],'img/luat-1.svg','Bảo vệ hạ tầng không gian mạng quốc gia phải gắn với điều gì?','["Chỉ bảo vệ các trang web cá nhân", "Chỉ phục vụ giải trí", "Yêu cầu phát triển kinh tế - xã hội", "Chỉ tập trung vào quân sự"]'::jsonb,2,'Bảo vệ hạ tầng mạng gắn với phát triển kinh tế – xã hội.','Điều 24 Luật An ninh mạng số 116/2025/QH15','HHANM-172'),
(376,4,1,ARRAY['tin giả']::text[],'img/tingia-2.svg','Website cơ quan nhà nước không được đăng thông tin nào?','["Thông tin lịch làm việc", "Thông tin về thủ tục hành chính", "Thông tin xâm phạm chủ quyền quốc gia", "Thông tin tuyên truyền pháp luật"]'::jsonb,2,'Không đăng thông tin xâm phạm chủ quyền quốc gia.','Điểm e khoản 1 Điều 13 Luật An ninh mạng số 116/2025/QH15','HHANM-173'),
(377,4,2,ARRAY['tin giả']::text[],'img/tingia-1.svg','Nhà mạng nhận yêu cầu xóa thông tin vi phạm (trường hợp thường). Hạn bao lâu?','["48 giờ", "24 giờ", "12 giờ", "72 giờ"]'::jsonb,1,'24 giờ – một ngày là hết hạn.','Điều 25 Luật An ninh mạng số 116/2025/QH15','HHANM-174'),
(378,4,1,ARRAY['pháp luật']::text[],'img/luat-2.svg','Ai chịu trách nhiệm triển khai bảo vệ ANM trong cơ quan, tổ chức?','["Nhân viên IT", "Người đứng đầu cơ quan, tổ chức", "Bảo vệ cơ quan", "Nhà cung cấp mạng"]'::jsonb,1,'Người đứng đầu chịu trách nhiệm.','Điều 23 Luật An ninh mạng số 116/2025/QH15','HHANM-175'),
(379,4,2,ARRAY['tin giả']::text[],'img/tingia.svg','"Xung đột thông tin trên không gian mạng" thật ra là gì?','["Việc cài đặt nhầm phần mềm", "Việc hai người tranh cãi trên Facebook", "Việc các tổ chức trong và ngoài nước sử dụng biện pháp công nghệ gây tổn hại đến hệ thống thông tin của nhau", "Việc mạng bị nghẽn do nhiều người truy cập"]'::jsonb,2,'Các tổ chức dùng công nghệ gây hại hệ thống của nhau.','Điều 22 Luật An ninh mạng số 116/2025/QH15','HHANM-176'),
(380,4,2,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Đấu tranh bảo vệ an ninh mạng là hoạt động của ai?','["Lực lượng chuyên trách bảo vệ ANM", "Mọi người dân tự phát", "Các công ty bán phần mềm diệt virus", "Các hacker tự do"]'::jsonb,0,'Lực lượng chuyên trách bảo vệ ANM.','Điều 21 Luật An ninh mạng số 116/2025/QH15','HHANM-177'),
(381,4,2,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','"Tình huống nguy hiểm về an ninh mạng" gồm những trường hợp nào?','["Tấn công vào hệ thống thông tin quan trọng về ANQG quy mô lớn", "Xuất hiện thông tin kích động bạo loạn có nguy cơ xảy ra", "Tấn công mạng xâm phạm nghiêm trọng chủ quyền quốc gia", "Tất cả các trường hợp trên"]'::jsonb,3,'Tấn công quy mô lớn, kích động bạo loạn, xâm phạm chủ quyền – đều là.','Điều 20 Luật An ninh mạng số 116/2025/QH15','HHANM-178'),
(382,4,1,ARRAY['pháp luật']::text[],'img/luat-1.svg','Cơ quan nhà nước phải xây dựng phương án bảo đảm ANM cho hệ thống của mình – đúng hay sai?','["Sai", "Tùy kinh phí", "Không bắt buộc", "Đúng"]'::jsonb,3,'Có hệ thống – phải có phương án bảo vệ.','Điều 23 Luật An ninh mạng số 116/2025/QH15','HHANM-179'),
(383,4,1,ARRAY['tin giả']::text[],'img/tingia-1.svg','Website cơ quan nhà nước không được đăng nội dung gì?','["Thủ tục hành chính", "Các thông tin có nội dung xâm phạm ANQG", "Tin tức hoạt động của cơ quan", "Lịch tiếp dân"]'::jsonb,1,'Thông tin xâm phạm an ninh quốc gia.','Khoản 1 Điều 13 Luật An ninh mạng số 116/2025/QH15','HHANM-180'),
(384,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Doanh nghiệp dịch vụ mạng tại Việt Nam lưu dữ liệu cá nhân người dùng ở đâu?','["Chỉ lưu tại nước ngoài", "Không cần lưu trữ", "Lưu tại bất cứ đâu", "Tại Việt Nam (theo quy định Chính phủ)"]'::jsonb,3,'Lưu tại Việt Nam theo quy định Chính phủ.','Điều 25 Luật An ninh mạng số 116/2025/QH15','HHANM-181'),
(385,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Bảo đảm an ninh dữ liệu là tổng thể các biện pháp gì?','["Chỉ dùng mật khẩu mạnh", "Kỹ thuật, tổ chức và pháp lý", "Chỉ thuê bảo vệ canh gác máy chủ", "Chỉ mua bảo hiểm dữ liệu"]'::jsonb,1,'Kỹ thuật + tổ chức + pháp lý.','Điều 26 Luật An ninh mạng số 116/2025/QH15','HHANM-182'),
(386,4,2,ARRAY['pháp luật']::text[],'img/luat-2.svg','Chứng nhận hợp quy về ANM thực hiện theo quy định nào?','["Theo quy định của pháp luật về tiêu chuẩn và quy chuẩn kỹ thuật", "Theo tiêu chuẩn quốc tế", "Không cần chứng nhận", "Do doanh nghiệp tự đặt ra"]'::jsonb,0,'Theo pháp luật về tiêu chuẩn và quy chuẩn kỹ thuật.','Điều 27 Luật An ninh mạng số 116/2025/QH15','HHANM-183'),
(387,4,1,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Dịch vụ an ninh mạng gồm những gì?','["Kiểm tra, đánh giá ANM", "Tư vấn an ninh mạng", "Ứng cứu sự cố an ninh mạng", "Tất cả các dịch vụ trên"]'::jsonb,3,'Kiểm tra, tư vấn, ứng cứu – đều là dịch vụ ANM.','Điều 28 Luật An ninh mạng số 116/2025/QH15','HHANM-184'),
(388,4,3,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Ai có thẩm quyền quyết định xử lý tình huống nguy hiểm về ANM trên cả nước?','["Chủ tịch xã", "Bộ trưởng Bộ Công an hoặc Thủ tướng Chính phủ", "Trưởng phòng IT", "Giám đốc doanh nghiệp"]'::jsonb,1,'Bộ trưởng Bộ Công an hoặc Thủ tướng.','Điều 20 Luật An ninh mạng số 116/2025/QH15','HHANM-185'),
(389,2,1,ARRAY['tấn công mạng']::text[],'img/hack-2.svg','Đâu là tấn công mạng?','["Phát tán chương trình tin học gây hại", "Xâm nhập, chiếm đoạt quyền điều khiển hệ thống", "Gây cản trở, làm tê liệt hoạt động hệ thống", "Tất cả các phương án trên"]'::jsonb,3,'Phát tán mã độc, chiếm quyền, làm tê liệt – đều là tấn công mạng.','Khoản 1 Điều 18 Luật An ninh mạng số 116/2025/QH15','HHANM-186'),
(390,1,1,ARRAY['người lạ']::text[],'img/nguoila-2.svg','Bố mẹ của Tí cần làm gì khi Tí dùng mạng?','["Cấm tuyệt đối trẻ dùng internet", "Để trẻ tự do khám phá", "Đăng ký tài khoản bằng thông tin của mình và giám sát trẻ", "Giao toàn bộ việc quản lý cho nhà trường"]'::jsonb,2,'Bố mẹ đứng tên, trông chừng bé luôn!','Khoản 2 Điều 16 Luật An ninh mạng số 116/2025/QH15','HHANM-187'),
(391,4,2,ARRAY['pháp luật']::text[],'img/luat.svg','Bảo vệ hạ tầng không gian mạng quốc gia để làm gì?','["Phát triển kinh tế - xã hội", "Bảo đảm chủ quyền lãnh thổ trên không gian mạng", "Khuyến khích đầu tưxây dựng cơ sở hạ tầng không gian mạng quốc gia.", "Cả 3 phương án trên"]'::jsonb,3,'Phát triển kinh tế, bảo đảm chủ quyền, khuyến khích đầu tư – cả ba.','Điều 24 Luật An ninh mạng số 116/2025/QH15','HHANM-188'),
(392,4,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Luật Bảo vệ dữ liệu cá nhân 2025 quy định về những gì?','["Dữ liệu cá nhân, bảo vệ dữ liệu cá nhân", "Quyền, nghĩa vụ của cơ quan, tổ chức, cá nhân liên quan", "Trách nhiệm của các bên liên quan", "Tất cả các phương án trên"]'::jsonb,3,'Dữ liệu cá nhân, quyền nghĩa vụ, trách nhiệm các bên – đủ cả.','Điều 1 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-189'),
(393,4,1,ARRAY['pháp luật']::text[],'img/luat-2.svg','Luật An ninh mạng 2025 quy định về những gì?','["An ninh mạng, bảo vệ an ninh mạng", "Quyền, nghĩa vụ của cơ quan, tổ chức có liên quan", "Trách nhiệm của cá nhân có liên quan", "Tất cả các phương án trên"]'::jsonb,3,'An ninh mạng, quyền nghĩa vụ, trách nhiệm – đủ cả.','Điều 1 Luật An ninh mạng số 116/2025/QH15','HHANM-190'),
(394,4,2,ARRAY['tấn công mạng']::text[],'img/hack-2.svg','Website của trường do thầy Hiệu trưởng quản lý trực tiếp. Ai là "chủ quản hệ thống thông tin"?','["Người sử dụng hệ thống", "Cảnh sát mạng", "Cơ quan, tổ chức, cá nhân có thẩm quyền quản lý trực tiếp", "Nhà cung cấp thiết bị"]'::jsonb,2,'Ai có thẩm quyền quản lý trực tiếp – người đó là chủ quản.','Điều 2 Luật An ninh mạng số 116/2025/QH15','HHANM-191'),
(395,2,1,ARRAY['tấn công mạng']::text[],'img/hack-1.svg','Kẻ xấu tấn công mạng nhằm mục đích gì?','["Kiểm tra tính bảo mật của người dùng", "Quảng cáo sản phẩm", "Chiếm đoạt thông tin, gây rối loạn, đình trệ hệ thống", "Giúp hệ thống chạy nhanh hơn"]'::jsonb,2,'Chiếm thông tin, gây rối loạn, đình trệ hệ thống.','Điều 2 Luật An ninh mạng số 116/2025/QH15','HHANM-192'),
(396,2,1,ARRAY['lừa đảo']::text[],'img/linkla.svg','Máy tính tự xóa ảnh, chạy lung tung sau khi cài app lạ. "Phần mềm độc hại" là gì?','["Phần mềm bị lỗi code", "Phần mềm có khả năng gây hoạt động không bình thường hoặc sao chép, xóa dữ liệu trái phép", "Phần mềm tốn nhiều dung lượng", "Phần mềm chưa được mua bản quyền"]'::jsonb,1,'Mã độc làm máy chạy bất thường, sao chép hoặc xóa dữ liệu trái phép.','Điều 2 Luật An ninh mạng số 116/2025/QH15','HHANM-193'),
(397,4,1,ARRAY['pháp luật']::text[],'img/luat-2.svg','Không gian mạng quốc gia thuộc quyền quản lý của ai?','["Các tập đoàn viễn thông", "Các nhà cung cấp dịch vụ mạng", "Liên hợp quốc", "Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam"]'::jsonb,3,'Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam.','Điều 2 Luật An ninh mạng số 116/2025/QH15','HHANM-194'),
(398,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','"An ninh thông tin mạng" bảo đảm những tính chất nào của thông tin?','["Tính nguyên vẹn", "Tính bảo mật", "Tính khả dụng", "Tất cả các tính chất trên"]'::jsonb,3,'Nguyên vẹn, bảo mật, khả dụng – cả ba.','Điều 2 Luật An ninh mạng số 116/2025/QH15','HHANM-195'),
(399,4,2,ARRAY['pháp luật']::text[],'img/luat.svg','Theo luật, "an ninh mạng" được hiểu là gì?','["Sự ổn định, an ninh, an toàn của không gian mạng", "Hoạt động trên không gian mạng không gây phương hại đến ANQG", "Đảm bảo quyền và lợi ích hợp pháp của tổ chức, cá nhân", "Cả 3 phương án trên"]'::jsonb,3,'Ổn định, an toàn, không phương hại – cả ba ý.','Điều 2 Luật An ninh mạng số 116/2025/QH15','HHANM-196'),
(400,3,1,ARRAY['pháp luật']::text[],'img/luat-1.svg','Luật An ninh mạng áp dụng cho ai?','["Cơ quan, tổ chức Việt Nam", "Cá nhân Việt Nam", "Cơ quan, tổ chức, cá nhân nước ngoài trực tiếp tham gia bảo vệ ANM tại VN", "Tất cả các đối tượng trên"]'::jsonb,3,'Tổ chức, cá nhân Việt Nam và nước ngoài liên quan – tất cả.','Điều 1 Luật An ninh mạng số 116/2025/QH15','HHANM-197'),
(401,4,2,ARRAY['tin giả']::text[],'img/tingia-2.svg','Lập hội nhóm trên mạng để xúi giục người khác chống chính quyền vi phạm nhóm điều cấm nào?','["Điều cấm về thực hiện hành vi", "Điều cấm về thông tin", "Không vi phạm", "Điều cấm về sản xuất công cụ"]'::jsonb,0,'Lập nhóm xúi giục – vi phạm điều cấm về thực hiện hành vi.','Điểm a khoản 2 Điều 7 Luật An ninh mạng số 116/2025/QH15','HHANM-198'),
(402,3,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Dữ liệu cá nhân được lưu trữ trong bao lâu?','["50 năm", "Phù hợp với mục đích xử lý (trừ khi pháp luật quy định khác)", "Vĩnh viễn", "10 năm"]'::jsonb,1,'Lưu vừa đủ cho mục đích xử lý.','Điều 3 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-199'),
(403,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Bên nào quyết định mục đích và phương tiện xử lý dữ liệu cá nhân?','["Bên xử lý dữ liệu", "Bên kiểm soát dữ liệu cá nhân", "Chủ thể dữ liệu", "Bên thứ ba"]'::jsonb,1,'Bên kiểm soát dữ liệu cá nhân.','Khoản 7 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-200'),
(404,3,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Câu lạc bộ muốn đăng danh sách thành viên kèm số điện thoại lên fanpage. Công khai dữ liệu cá nhân phải bảo đảm điều gì?','["Chỉ công khai trên báo giấy", "Phải phù hợp với mục đích cụ thể và không xâm phạm quyền chủ thể", "Công khai càng rộng càng tốt", "Không cần bảo đảm gì"]'::jsonb,1,'Công khai đúng mục đích, không xâm phạm quyền chủ thể.','Điều 16 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-201'),
(405,2,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Tí phát hiện app học tập ghi sai ngày sinh của mình. Tí có được tự sửa không?','["Chỉ khi có lệnh của tòa án", "Không bao giờ", "Chỉ khi trả phí", "Được tự chỉnh sửa theo thỏa thuận hoặc đề nghị bên kiểm soát chỉnh sửa"]'::jsonb,3,'Dữ liệu của mình – được tự sửa hoặc đề nghị sửa.','Điều 13 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-202'),
(406,2,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Nhóm lạ chiếm đoạt, làm lộ và mua bán dữ liệu cá nhân. Theo Luật BVDLCN, hành vi nào bị cấm?','["Xử lý dữ liệu nhằm chống lại Nhà nước VN", "Mua, bán dữ liệu cá nhân (trừ trường hợp luật định)", "Chiếm đoạt, cố ý làm lộ dữ liệu cá nhân", "Tất cả các hành vi trên"]'::jsonb,3,'Chống Nhà nước, mua bán, làm lộ dữ liệu – đều bị cấm.','Điều 7 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-203'),
(407,4,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Bảo vệ dữ liệu cá nhân phải gắn liền với lợi ích nào?','["Lợi ích quốc gia, dân tộc và phát triển kinh tế - xã hội", "Lợi ích của các sàn thương mại", "Chỉ lợi ích của cá nhân", "Lợi ích của các nhà mạng"]'::jsonb,0,'Gắn với lợi ích quốc gia, dân tộc và phát triển kinh tế – xã hội.','Điều 3 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-204'),
(408,2,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Mèo Mít hỏi: "Dữ liệu của con thì con có quyền gì?" Bạn trả lời…','["Được biết về hoạt động xử lý", "Đồng ý hoặc không đồng ý cho phép xử lý", "Yêu cầu cung cấp, xóa, hạn chế xử lý", "Tất cả các quyền trên"]'::jsonb,3,'Được biết, được đồng ý hay không, được yêu cầu xóa – đủ cả.','Khoản 1 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-205'),
(409,2,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Dữ liệu của chị Hoa bị lộ gây thiệt hại. Chị có quyền đòi bồi thường không?','["Có quyền yêu cầu bồi thường theo quy định pháp luật", "Không", "Chỉ khi thiệt hại trên 1 tỷ đồng", "Chỉ khi có sự đồng ý của bên xử lý"]'::jsonb,0,'Bị thiệt hại – có quyền đòi bồi thường.','Điểm đ khoản 1 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-206'),
(410,2,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Cún Bông có nghĩa vụ gì với dữ liệu cá nhân?','["Tự bảo vệ dữ liệu của mình", "Tôn trọng, bảo vệ dữ liệu của người khác", "Cung cấp đầy đủ, chính xác dữ liệu khi đồng ý xử lý", "Tất cả các nghĩa vụ trên"]'::jsonb,3,'Giữ của mình, tôn trọng của người, khai đúng khi được hỏi.','Khoản 2 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-207'),
(411,3,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Bạn A giận app nên cố tình gây khó khăn cho việc thực hiện quyền hợp pháp của bên kiểm soát dữ liệu. Có được không?','["Có", "Không được gây khó khăn, cản trở", "Tùy trường hợp", "Được phép nếu thấy không thích"]'::jsonb,1,'Đòi quyền mình – không được cản trở quyền hợp pháp của người khác.','Điểm b khoản 3 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-208'),
(412,3,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Tí gửi yêu cầu xóa dữ liệu cho một app. Bên kiểm soát phải thực hiện khi nào?','["Khi nào rảnh thì làm", "Không cần thực hiện", "Sau 1 năm", "Kịp thời trong thời hạn theo quy định"]'::jsonb,3,'Kịp thời, trong thời hạn luật định.','Khoản 5 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-209'),
(413,4,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Hợp tác quốc tế về bảo vệ dữ liệu cá nhân gồm những gì?','["Trao đổi kinh nghiệm xây dựng pháp luật", "Phòng ngừa, đấu tranh hành vi xâm phạm", "Chuyển giao công nghệ bảo vệ", "Tất cả các nội dung trên"]'::jsonb,3,'Trao đổi kinh nghiệm, chống vi phạm, chuyển giao công nghệ – đủ cả.','Điều 6 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-210'),
(414,3,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Một công ty xử lý dữ liệu cá nhân trái luật nghiêm trọng. Có thể bị xử lý hình sự không?','["Chỉ bị khóa tài khoản", "Không, chỉ phạt tiền", "Có thể bị truy cứu trách nhiệm hình sự tùy mức độ", "Chỉ bị nhắc nhở"]'::jsonb,2,'Tùy mức độ – có thể truy cứu hình sự.','Điều 8 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-211'),
(415,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Một người bán dữ liệu cá nhân thu lời lớn. Mức phạt tiền tối đa với hành vi mua bán dữ liệu là bao nhiêu?','["10 lần khoản thu có được (hoặc theo quy định khoản 5)", "500 triệu đồng", "Không bị phạt tiền", "100 triệu đồng"]'::jsonb,0,'Bán dữ liệu – phạt tới 10 lần khoản thu.','Điều 8 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-212'),
(416,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Mức phạt tiền tối đa cho các vi phạm bảo vệ dữ liệu cá nhân khác (ngoài mua bán, chuyển xuyên biên giới) là bao nhiêu?','["500 triệu đồng", "3 tỷ đồng", "5 tỷ đồng", "1 tỷ đồng"]'::jsonb,1,'Vi phạm khác – tối đa 3 tỷ đồng.','Điều 8 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-213'),
(417,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Tổ chức vi phạm quy định chuyển dữ liệu xuyên biên giới bị phạt tối đa bao nhiêu?','["5% doanh thu năm trước liền kề", "2 tỷ đồng", "10% doanh thu", "1% doanh thu"]'::jsonb,0,'Xuyên biên giới sai luật – tới 5% doanh thu năm trước.','Điều 8 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-214'),
(418,3,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Một nguyên tắc bảo vệ dữ liệu cá nhân là gì?','["Thu thập càng nhiều càng tốt", "Công khai dữ liệu cho mọi người", "Lưu trữ dữ liệu vĩnh viễn", "Chỉ xử lý đúng phạm vi, mục đích cụ thể, rõ ràng"]'::jsonb,3,'Thu đúng, dùng đúng mục đích – không “gom” bừa.','Điều 3 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-215'),
(419,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Công ty làm "đánh giá tác động xử lý dữ liệu cá nhân" để làm gì?','["Phân tích rủi ro và áp dụng biện pháp giảm thiểu, bảo vệ dữ liệu", "Để thu phí người dùng", "Để thống kê dân số", "Để quảng cáo sản phẩm"]'::jsonb,0,'Đánh giá rủi ro để giảm thiểu, bảo vệ dữ liệu.','Khoản 12 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-216'),
(420,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','"Khử nhận dạng dữ liệu cá nhân" là gì?','["Là việc khóa tài khoản người dùng", "Quá trình thay đổi/xóa thông tin để không thể xác định một người cụ thể", "Là việc thay đổi mật khẩu", "Là việc xóa dữ liệu vĩnh viễn"]'::jsonb,1,'Đổi hoặc xóa thông tin để không nhận ra ai.','Khoản 11 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-217'),
(421,3,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Hoạt động nào là "xử lý dữ liệu cá nhân"?','["Thu thập, phân tích, tổng hợp", "Mã hóa, giải mã, chỉnh sửa", "Xóa, hủy, chuyển giao", "Tất cả các hoạt động trên"]'::jsonb,3,'Thu thập, mã hóa, xóa, chuyển giao – đều là xử lý.','Khoản 6 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-218'),
(422,3,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Mèo Mít hỏi: "Dữ liệu về con thì con là gì của nó?" "Chủ thể dữ liệu cá nhân" là ai?','["Người mua bán dữ liệu", "Cơ quan quản lý dữ liệu", "Người xử lý dữ liệu", "Người được dữ liệu cá nhân phản ánh"]'::jsonb,3,'Dữ liệu nói về ai – người đó là chủ thể.','Khoản 5 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-219'),
(423,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Dữ liệu nào không còn là dữ liệu cá nhân?','["Dữ liệu lưu trong USB", "Dữ liệu sau khi khử nhận dạng", "Dữ liệu đã được mã hóa", "Dữ liệu ghi trên giấy"]'::jsonb,1,'Đã khử nhận dạng – không còn là dữ liệu cá nhân.','Khoản 1 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-220'),
(424,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Dữ liệu cá nhân gồm những loại nào?','["Dữ liệu định danh và dữ liệu phi định danh", "Dữ liệu cá nhân cơ bản và dữ liệu cá nhân nhạy cảm", "Dữ liệu cơ bản và dữ liệu nâng cao", "Dữ liệu công khai và dữ liệu mật"]'::jsonb,1,'Cơ bản và nhạy cảm.','Khoản 1 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-221'),
(425,3,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Luật Bảo vệ dữ liệu cá nhân áp dụng cho ai?','["Cơ quan, tổ chức, cá nhân Việt Nam", "Cơ quan, tổ chức, cá nhân nước ngoài tại Việt Nam", "Tổ chức nước ngoài xử lý dữ liệu của công dân Việt Nam", "Tất cả các đối tượng trên"]'::jsonb,3,'Trong nước, nước ngoài tại VN, và tổ chức nước ngoài xử lý dữ liệu công dân VN.','Điều 1 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-222'),
(426,2,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Tên, ngày sinh, số điện thoại của Tí là gì? "Dữ liệu cá nhân" được hiểu là gì?','["Thông tin về thời tiết vùng miền", "Dữ liệu về tài chính doanh nghiệp", "Dữ liệu số hoặc thông tin xác định/giúp xác định một con người cụ thể", "Dữ liệu về các loài động vật"]'::jsonb,2,'Dữ liệu giúp nhận ra một người cụ thể.','Khoản 1 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-223'),
(427,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Cá nhân vi phạm bảo vệ dữ liệu bị phạt tối đa bằng bao nhiêu so với tổ chức?','["Gấp đôi mức tổ chức", "Bằng mức tổ chức", "Bằng một phần hai (1/2) mức tổ chức", "Bằng một phần ba (1/3) mức tổ chức"]'::jsonb,2,'Cá nhân – bằng một nửa mức của tổ chức.','Điều 8 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-224'),
(428,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Cơ quan chuyên trách kiểm tra định kỳ việc chuyển dữ liệu xuyên biên giới tối đa mấy lần mỗi năm?','["1 tháng 1 lần", "5 năm 1 lần", "Không quá 01 lần trong năm (trừ khi có vi phạm/sự cố)", "Hàng tuần"]'::jsonb,2,'Không quá 1 lần mỗi năm (trừ khi có vi phạm, sự cố).','Điều 20 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-225'),
(429,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Hồ sơ đánh giá tác động chuyển dữ liệu xuyên biên giới phải gửi trong bao lâu?','["60 ngày kể từ ngày đầu tiên chuyển dữ liệu", "30 ngày", "1 năm", "10 ngày"]'::jsonb,0,'60 ngày từ lần chuyển đầu tiên.','Điều 20 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-226'),
(430,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Trường hợp nào là chuyển dữ liệu cá nhân xuyên biên giới?','["Chuyển đến hệ thống lưu trữ ngoài lãnh thổ Việt Nam", "Chuyển cho tổ chức nước ngoài", "Sử dụng nền tảng nước ngoài để xử lý dữ liệu thu thập tại VN", "Tất cả các trường hợp trên"]'::jsonb,3,'Lưu ngoài lãnh thổ, chuyển cho tổ chức nước ngoài, dùng nền tảng nước ngoài – đều là.','Điều 20 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-227'),
(431,3,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Khi nào xử lý dữ liệu cá nhân không cần sự đồng ý?','["Để bảo vệ tính mạng, sức khỏe trong tình trạng cấp bách", "Để giải quyết tình trạng khẩn cấp về quốc phòng, an ninh", "Phục vụ hoạt động của cơ quan nhà nước theo luật định", "Tất cả các trường hợp trên"]'::jsonb,3,'Cứu tính mạng, khẩn cấp quốc phòng an ninh, nhiệm vụ nhà nước theo luật.','Điều 19 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-228'),
(432,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Xử lý dữ liệu phục vụ thí điểm cơ chế đặc biệt được ưu tiên ở lĩnh vực nào?','["Thời trang", "Giải trí", "Du lịch", "Chuyển đổi số quốc gia, khoa học công nghệ"]'::jsonb,3,'Chuyển đổi số quốc gia, khoa học công nghệ.','Điều 18 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-229'),
(433,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Chuyển giao dữ liệu cá nhân có thu phí theo luật có bị coi là "mua bán dữ liệu" không?','["Không được xác định là mua, bán dữ liệu cá nhân", "Có", "Tùy vào hợp đồng", "Chỉ khi thu phí cao"]'::jsonb,0,'Chuyển giao đúng luật có thu phí – không phải mua bán.','Điều 17 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-230'),
(434,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Phòng nhân sự chuyển dữ liệu cho phòng kế toán trong cùng công ty. Có cần xin đồng ý lại không?','["Không được phép", "Được phép để xử lý phù hợp mục đích đã xác lập", "Có", "Chỉ khi sếp đồng ý"]'::jsonb,1,'Trong cùng tổ chức, đúng mục đích – được chuyển.','Điều 17 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-231'),
(435,4,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Công khai dữ liệu cá nhân có thể bằng hình thức nào?','["Đăng tải trên trang thông tin điện tử", "Phương tiện thông tin đại chúng", "Các hình thức khác theo quy định", "Tất cả các phương án trên"]'::jsonb,3,'Web, báo chí, hình thức khác theo quy định.','Điều 16 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-232'),
(436,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Hồ sơ đánh giá tác động chuyển dữ liệu xuyên biên giới gửi cho ai?','["Ngân hàng Nhà nước", "Ủy ban nhân dân xã", "Bộ Tài chính", "Cơ quan chuyên trách bảo vệ dữ liệu cá nhân (thuộc Bộ Công an)"]'::jsonb,3,'Cơ quan chuyên trách bảo vệ dữ liệu cá nhân (Bộ Công an).','Điều 20 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-233'),
(437,3,2,ARRAY['cookie']::text[],'img/cookie-1.svg','Trang web bán giày theo dõi bạn để hiện quảng cáo riêng. Cần điều kiện gì?','["Chỉ cần cài đặt cookies", "Chỉ cần có trang web", "Sự đồng ý của chủ thể dữ liệu cá nhân", "Không cần điều kiện gì"]'::jsonb,2,'Theo dõi để quảng cáo – phải được đồng ý.','Điều 28 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-234'),
(438,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Công ty quảng cáo có được thuê bên khác làm toàn bộ dịch vụ dùng dữ liệu cá nhân không?','["Không được thuê lại hoặc thỏa thuận để bên khác thay mặt thực hiện toàn bộ", "Chỉ khi thuê công ty nước ngoài", "Chỉ khi được chủ thể đồng ý", "Được phép"]'::jsonb,0,'Không được “khoán trắng” cho bên khác.','Điều 28 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-235'),
(439,2,1,ARRAY['cookie']::text[],'img/cookie.svg','Cún Bông nhận quảng cáo liên tục. Bên quảng cáo phải cho Cún Bông cách gì?','["Không cần cung cấp gì", "Phương thức để từ chối nhận thông tin quảng cáo", "Phương thức nộp thêm phí", "Phương thức xem dữ liệu của người khác"]'::jsonb,1,'Phải có nút từ chối quảng cáo.','Điều 28 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-236'),
(440,2,1,ARRAY['tài khoản']::text[],'img/taikhoan-2.svg','Ngân hàng phát hiện thông tin tài khoản của bác Năm bị lộ. Ngân hàng phải làm gì?','["Không cần thông báo", "Thông báo cho chủ thể dữ liệu cá nhân", "Tạm khóa tài khoản vĩnh viễn", "Chỉ cần sửa lỗi hệ thống"]'::jsonb,1,'Lộ thông tin – phải báo cho khách.','Điều 27 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-237'),
(441,3,2,ARRAY['tài khoản']::text[],'img/taikhoan-1.svg','Ngân hàng muốn dùng thông tin tín dụng để chấm điểm khách. Khi nào thì không được?','["Khi chưa có sự đồng ý của chủ thể dữ liệu", "Luôn được phép dùng", "Khi khách hàng nợ xấu", "Khi khách hàng là người nước ngoài"]'::jsonb,0,'Chưa đồng ý – không được chấm điểm.','Điều 27 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-238'),
(442,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Dịch vụ quảng cáo được dùng dữ liệu cá nhân từ nguồn nào?','["Từ các mạng xã hội trái phép", "Từ bất kỳ nguồn nào trên internet", "Từ danh bạ điện thoại mua được", "Được bên kiểm soát chuyển giao theo thỏa thuận hoặc tự thu thập qua hoạt động KD"]'::jsonb,3,'Do bên kiểm soát chuyển giao theo thỏa thuận hoặc tự thu thập hợp pháp.','Điều 28 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-239'),
(443,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Hồ sơ đánh giá tác động phải cập nhật định kỳ bao lâu khi có thay đổi?','["1 năm", "1 tháng", "06 tháng", "5 năm"]'::jsonb,2,'6 tháng một lần khi có thay đổi.','Điều 22 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-240'),
(444,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Ai không phải lập hồ sơ đánh giá tác động xử lý dữ liệu cá nhân?','["Mọi doanh nghiệp", "Cơ quan nhà nước có thẩm quyền", "Các ngân hàng", "Các công ty công nghệ lớn"]'::jsonb,1,'Cơ quan nhà nước có thẩm quyền.','Điều 21 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-241'),
(445,2,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Shop online muốn đưa dữ liệu khách cho công ty khác. Cần điều gì?','["Không cần gì", "Chỉ cần trả tiền", "Được chủ thể dữ liệu đồng ý (trừ khi pháp luật quy định khác)", "Chỉ cần bên thứ ba yêu cầu"]'::jsonb,2,'Muốn cung cấp cho bên thứ ba – phải được đồng ý.','Điều 15 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-242'),
(446,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Dữ liệu đã khử nhận dạng có được "nhận dạng lại" không?','["Được phép thoải mái", "Chỉ dành cho mục đích quảng cáo", "Được nếu trả tiền cho chủ thể", "Không được tái nhận dạng (trừ khi pháp luật quy định khác)"]'::jsonb,3,'Đã khử – không được tái nhận dạng.','Điều 14 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-243'),
(447,3,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Hành vi nào bị cấm với dữ liệu đã bị xóa?','["Lưu trữ bản sao", "Thông báo cho chủ thể dữ liệu", "Kiểm tra dung lượng bộ nhớ", "Cố ý khôi phục trái phép dữ liệu cá nhân đã bị xóa, hủy"]'::jsonb,3,'Cố ý khôi phục trái phép dữ liệu đã xóa.','Điều 14 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-244'),
(448,4,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Khi nào dữ liệu cá nhân được xóa, hủy?','["Chủ thể dữ liệu yêu cầu", "Đã hoàn thành mục đích xử lý", "Hết thời hạn lưu trữ", "Tất cả các trường hợp trên"]'::jsonb,3,'Khi chủ thể yêu cầu, hết mục đích, hết hạn lưu – đều xóa.','Điều 14 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-245'),
(449,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Dữ liệu cá nhân là bí mật nhà nước được mã hóa theo quy định nào?','["Không cần mã hóa", "Quy định của công ty", "Pháp luật về bảo vệ bí mật nhà nước và cơ yếu", "Quy định của quốc tế"]'::jsonb,2,'Theo pháp luật bảo vệ bí mật nhà nước và cơ yếu.','Điều 12 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-246'),
(450,4,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Mèo Mít viết thư bằng mật mã cho bạn. "Mã hóa dữ liệu cá nhân" là gì?','["Là việc đổi tên file", "Là việc in dữ liệu ra giấy", "Là việc xóa dữ liệu", "Chuyển dữ liệu sang dạng không nhận biết được nếu không giải mã"]'::jsonb,3,'Mã hóa: không có chìa thì không đọc được.','Điều 12 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-247'),
(451,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Ai được phân tích, tổng hợp dữ liệu cá nhân phục vụ lãnh đạo, chỉ đạo?','["Mọi doanh nghiệp", "Cơ quan Đảng, Nhà nước có thẩm quyền", "Các công ty quảng cáo", "Các cá nhân kinh doanh"]'::jsonb,1,'Cơ quan Đảng, Nhà nước có thẩm quyền.','Điều 11 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-248'),
(452,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Rút lại sự đồng ý có làm các xử lý trước đó trở thành trái luật không?','["Tùy bên kiểm soát quyết định", "Không áp dụng đối với hoạt động xử lý trước thời điểm yêu cầu", "Có, xử lý cũ trở thành bất hợp pháp", "Có, phải xóa sạch hết"]'::jsonb,1,'Rút đồng ý chỉ có hiệu lực từ nay về sau.','Khoản 4 Điều 10 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-249'),
(453,1,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Tí đã cho một ứng dụng dùng ảnh của mình, giờ Tí không muốn nữa. Tí có được đổi ý không?','["Có quyền yêu cầu rút lại sự đồng ý", "Không được rút lại", "Chỉ được rút lại sau 10 năm", "Chỉ khi nộp phí"]'::jsonb,0,'Đồng ý được thì rút lại được!','Khoản 1 Điều 10 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-250'),
(454,2,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','App hỏi xin dữ liệu, Cún Bông im lặng không trả lời. Như vậy có coi là đồng ý không?','["Có", "Không được coi là sự đồng ý", "Tùy vào loại dữ liệu", "Chỉ khi dữ liệu không quan trọng"]'::jsonb,1,'Im lặng không phải là đồng ý.','Điểm d khoản 4 Điều 9 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-251'),
(455,3,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Sự đồng ý của chủ thể dữ liệu có hiệu lực khi nào?','["Khi có sự đồng ý của hàng xóm", "Khi chủ thể dữ liệu giữ im lặng", "Dựa trên sự tự nguyện và biết rõ các thông tin cần thiết", "Khi bị ép buộc"]'::jsonb,2,'Tự nguyện và biết rõ – mới là đồng ý.','Khoản 2 Điều 9 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-252'),
(456,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Phát hiện vi phạm bảo vệ dữ liệu gây tổn hại an ninh quốc gia. Phải thông báo cơ quan chức năng trong bao lâu?','["12 giờ", "24 giờ", "72 giờ kể từ khi phát hiện", "1 tuần"]'::jsonb,2,'Thông báo trong 72 giờ.','Điều 23 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-253'),
(457,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Dữ liệu đã được đồng ý xử lý theo Nghị định 13/2023 thì sau khi có luật mới có phải xin lại không?','["Chỉ xin lại với dữ liệu nhạy cảm", "Có", "Không phải xin đồng ý lại hoặc thỏa thuận lại", "Tùy doanh nghiệp quyết định"]'::jsonb,2,'Đã đồng ý hợp lệ – không phải xin lại.','Điều 39 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-254'),
(458,4,1,ARRAY['báo cáo']::text[],'img/baocao-2.svg','Bà ngoại muốn phản ánh việc bị lộ số điện thoại. Cổng thông tin quốc gia về bảo vệ dữ liệu cá nhân dùng để làm gì?','["Để xem phim", "Để chơi game", "Tuyên truyền chính sách, hỗ trợ hướng dẫn và tiếp nhận phản ánh vi phạm", "Để bán hàng trực tuyến"]'::jsonb,2,'Cổng quốc gia: tuyên truyền, hướng dẫn, nhận phản ánh.','Khoản 2 Điều 39 Nghị định 356/2025/NĐ-CP','HHANM-255'),
(459,4,1,ARRAY['pháp luật']::text[],'img/luat-2.svg','Mèo Mít khoanh lịch Tết dương: Luật Bảo vệ dữ liệu cá nhân có hiệu lực từ ngày nào?','["26/6/2025", "01/7/2026", "01/01/2026", "01/5/2026"]'::jsonb,2,'01/01/2026.','Điều 38 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-256'),
(460,4,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Ai thống nhất quản lý nhà nước về bảo vệ dữ liệu cá nhân?','["Quốc hội", "Viện kiểm sát", "Chính phủ", "Tòa án"]'::jsonb,2,'Chính phủ.','Điều 36 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-257'),
(461,4,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Bộ Công an là đầu mối quản lý nhà nước về bảo vệ dữ liệu cá nhân – đúng hay sai?','["Sai", "Chỉ quản lý ở Hà Nội", "Chỉ quản lý dữ liệu tội phạm", "Đúng"]'::jsonb,3,'Đúng – Bộ Công an là đầu mối.','Điều 36 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-258'),
(462,4,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','UBND cấp tỉnh quản lý nhà nước về bảo vệ dữ liệu cá nhân ở phạm vi nào?','["Tại địa phương theo chức năng, nhiệm vụ", "Toàn quốc", "Chỉ tại các trường học", "Chỉ tại các khu công nghiệp"]'::jsonb,0,'Tại địa phương mình.','Điều 36 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-259'),
(463,3,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Bên kiểm soát dữ liệu gây thiệt hại cho khách hàng. Họ có trách nhiệm gì?','["Chỉ cần xin lỗi", "Đổ lỗi cho bên xử lý", "Chịu trách nhiệm bồi thường thiệt hại theo quy định", "Không chịu trách nhiệm"]'::jsonb,2,'Gây thiệt hại – bồi thường.','Điều 37 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-260'),
(464,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Bên xử lý dữ liệu chỉ được nhận dữ liệu sau khi có gì với bên kiểm soát?','["Thỏa thuận miệng", "Không cần thỏa thuận", "Thỏa thuận, hợp đồng về xử lý dữ liệu cá nhân", "Thỏa thuận về giá cả"]'::jsonb,2,'Phải có thỏa thuận, hợp đồng xử lý dữ liệu.','Điều 37 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-261'),
(465,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Doanh nghiệp siêu nhỏ được miễn lập hồ sơ đánh giá tác động trong bao lâu?','["5 năm (trừ trường hợp kinh doanh dịch vụ xử lý dữ liệu đặc thù)", "Vĩnh viễn", "1 năm", "10 năm"]'::jsonb,0,'Siêu nhỏ – miễn 5 năm (trừ dịch vụ xử lý dữ liệu đặc thù).','Điều 38 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-262'),
(466,2,1,ARRAY['cookie']::text[],'img/cookie.svg','Trang mạng xã hội hiện bảng "cookies". Họ phải cho người dùng lựa chọn gì?','["Không cần lựa chọn", "Lựa chọn mua thêm cookies", "Lựa chọn bắt buộc chấp nhận", "Lựa chọn từ chối thu thập và chia sẻ cookies"]'::jsonb,3,'Có quyền từ chối cookies.','Khoản 3 Điều 29 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-263'),
(467,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Có tranh chấp "khách đã đồng ý hay chưa". Ai phải chứng minh sự đồng ý?','["Nhà mạng", "Cơ quan công an", "Chủ thể dữ liệu", "Bên kiểm soát dữ liệu hoặc bên kiểm soát và xử lý"]'::jsonb,3,'Bên kiểm soát phải chứng minh.','Khoản 2 Điều 6 Nghị định 356/2025/NĐ-CP; Điều 9 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-264'),
(468,4,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Cơ quan chuyên trách bảo vệ dữ liệu cá nhân thuộc bộ nào?','["Bộ Thông tin và Truyền thông", "Bộ Công an", "Bộ Khoa học và Công nghệ", "Bộ Tư pháp"]'::jsonb,1,'Bộ Công an.','Điều 33 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-265'),
(469,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','"Dữ liệu lớn" (Big Data) có đặc điểm gì?','["Chỉ xử lý dữ liệu của 1 người", "Chỉ dùng để giải trí", "Không cần lưu trữ", "Quy mô lớn, tính liên tục, tích hợp từ nhiều nguồn"]'::jsonb,3,'Quy mô lớn, liên tục, nhiều nguồn.','Khoản 1 Điều 9 Nghị định 356/2025/NĐ-CP; Điều 30 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-266'),
(470,4,3,ARRAY['tài khoản']::text[],'img/taikhoan.svg','Ngân hàng phải tự đánh giá tuân thủ bảo vệ dữ liệu định kỳ bao lâu?','["01 năm/lần", "05 năm/lần", "06 tháng/lần", "02 năm/lần"]'::jsonb,0,'Mỗi năm một lần.','Khoản 1 Điều 8 Nghị định 356/2025/NĐ-CP; Điều 27 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-267'),
(471,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Chuyển dữ liệu nhạy cảm giữa các tổ chức cần biện pháp bảo mật nào?','["Bảo mật vật lý thiết bị lưu trữ", "Mã hóa, ẩn danh dữ liệu", "Có thỏa thuận bằng văn bản", "Tất cả các biện pháp trên"]'::jsonb,3,'Bảo mật thiết bị, mã hóa, thỏa thuận bằng văn bản – đủ cả.','Khoản 1, khoản 2 Điều 7 Nghị định 356/2025/NĐ-CP; Điều 17 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-268'),
(472,3,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Tổng đài gọi xin đồng ý xử lý dữ liệu qua cuộc gọi có ghi âm. Có hợp lệ không?','["Có, nếu bảo đảm khả năng kiểm chứng được", "Chỉ khi gọi cho người thân", "Không", "Chỉ khi gọi vào ban ngày"]'::jsonb,0,'Hợp lệ nếu kiểm chứng được.','Khoản 3 Điều 9 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-269'),
(473,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Nhận yêu cầu xóa dữ liệu cá nhân, bên kiểm soát phải thực hiện trong bao nhiêu ngày?','["20 ngày", "30 ngày", "45 ngày", "07 ngày"]'::jsonb,0,'Xóa dữ liệu – trong 20 ngày.','Khoản 4 Điều 5 Nghị định 356/2025/NĐ-CP; Điều 14 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-270'),
(474,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Chị Hoa yêu cầu một công ty ngừng xử lý dữ liệu của mình. Công ty có bao lâu để thực hiện?','["15 ngày", "30 ngày", "05 ngày", "60 ngày"]'::jsonb,0,'Ngừng xử lý – trong 15 ngày.','Khoản 2 Điều 5 Nghị định 356/2025/NĐ-CP; Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-271'),
(475,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Nhận yêu cầu rút lại sự đồng ý hợp lệ, bên kiểm soát phải phản hồi trong bao lâu?','["02 ngày làm việc", "24 giờ", "05 ngày", "10 ngày"]'::jsonb,0,'Phản hồi trong 2 ngày làm việc.','Khoản 2 Điều 5 Nghị định 356/2025/NĐ-CP; Điều 10 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-272'),
(476,3,2,ARRAY['tài khoản']::text[],'img/taikhoan.svg','Số tài khoản và lịch sử giao dịch ngân hàng của bác Năm thuộc loại dữ liệu nào?','["Dữ liệu cơ bản", "Dữ liệu công khai", "Dữ liệu cá nhân nhạy cảm", "Dữ liệu của ngân hàng"]'::jsonb,2,'Tiền nong ngân hàng – dữ liệu nhạy cảm.','Khoản 3 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; điểm k khoản 1 Điều 4 Nghị định 356/2025/NĐ-CP','HHANM-273'),
(477,4,3,ARRAY['AI-deepfake']::text[],'img/deepfake.svg','Công ty dùng AI xử lý dữ liệu cá nhân. Phải phân loại hệ thống AI theo tiêu chí nào?','["Theo mức độ rủi ro", "Theo năm sản xuất", "Theo giá tiền", "Theo quốc gia"]'::jsonb,0,'AI xử lý dữ liệu – phân loại theo mức độ rủi ro.','Điều 30 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-274'),
(478,3,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Bệnh viện xử lý dữ liệu sức khỏe của bệnh nhân. Khi nào không cần sự đồng ý?','["Khi bệnh viện muốn nghiên cứu", "Trường hợp cấp bách bảo vệ tính mạng (Điều 19)", "Khi bác sĩ yêu cầu", "Không bao giờ cần đồng ý"]'::jsonb,1,'Cấp bách cứu người – không cần chờ đồng ý.','Điều 19 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-275'),
(479,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Công ty lắp phần mềm theo dõi máy tính nhân viên. Phải bảo đảm điều gì?','["Chỉ cần sếp biết", "Người lao động phải biết rõ biện pháp đó", "Chỉ áp dụng cho nhân viên mới", "Phải giữ bí mật tuyệt đối với nhân viên"]'::jsonb,1,'Dùng công nghệ quản lý – nhân viên phải được biết.','Điều 25 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-276'),
(480,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Anh Ba trượt phỏng vấn. Công ty phải làm gì với hồ sơ của anh (nếu không thỏa thuận khác)?','["Chuyển cho công ty khác", "Lưu trữ vĩnh viễn", "Xóa, hủy thông tin đã cung cấp", "Đăng công khai trên web"]'::jsonb,2,'Không tuyển – xóa, hủy hồ sơ.','Điều 25 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-277'),
(481,4,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Chị Tư nộp CV xin việc. Thông tin trong CV được dùng vào mục đích gì?','["Để thống kê dân số", "Để quảng cáo dịch vụ", "Để bán cho các công ty khác", "Phục vụ mục đích tuyển dụng và mục đích khác theo thỏa thuận hợp pháp"]'::jsonb,3,'CV chỉ để tuyển dụng (hoặc mục đích đã thỏa thuận hợp pháp).','Điều 25 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-278'),
(482,3,2,ARRAY['người lạ']::text[],'img/nguoila.svg','Khi nào phải ngừng xử lý dữ liệu cá nhân của trẻ em?','["Người đại diện rút lại sự đồng ý", "Theo yêu cầu của cơ quan có thẩm quyền khi có căn cứ xâm phạm quyền trẻ em", "Cả a và b đều đúng", "Khi trẻ em không sử dụng dịch vụ nữa"]'::jsonb,2,'Bố mẹ rút đồng ý hoặc cơ quan có thẩm quyền yêu cầu.','Khoản 3 Điều 24 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-279'),
(483,2,2,ARRAY['quyền riêng tư']::text[],'img/anhrieng-1.svg','Một kênh YouTube muốn kể chuyện đời tư của bạn Na 8 tuổi. Cần sự đồng ý của ai?','["Chỉ cần người đại diện đồng ý", "Chỉ cần trẻ em đồng ý", "Trẻ em và người đại diện theo pháp luật", "Không cần ai đồng ý"]'::jsonb,2,'Trẻ từ 7 tuổi – cần cả bé và bố mẹ đồng ý.','Khoản 2 Điều 24 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-280'),
(484,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Công ty bảo hiểm muốn chuyển dữ liệu khách cho đối tác tái bảo hiểm. Được không?','["Được, mà không cần thông báo", "Chỉ khi khách hàng yêu cầu", "Được, nhưng phải nêu rõ trong hợp đồng với khách hàng", "Không được phép"]'::jsonb,2,'Được – nhưng phải ghi rõ trong hợp đồng với khách.','Điều 26 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-281'),
(485,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Vân tay, khuôn mặt của Tí là "dữ liệu sinh trắc học". Định nghĩa đúng là gì?','["Dữ liệu về quần áo", "Dữ liệu về cân nặng", "Dữ liệu về sở thích ăn uống", "Dữ liệu về thuộc tính vật lý, đặc điểm sinh học cá biệt và ổn định để xác định một người"]'::jsonb,3,'Đặc điểm sinh học riêng, ổn định để xác định một người.','Khoản 2 Điều 31 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-282'),
(486,4,3,ARRAY['pháp luật']::text[],'img/luat-2.svg','Tiêu chuẩn về bảo vệ dữ liệu cá nhân được ban hành theo luật nào?','["Luật Đất đai", "Luật Tiêu chuẩn và quy chuẩn kỹ thuật", "Luật Đầu tư", "Luật Giáo dục"]'::jsonb,1,'Theo Luật Tiêu chuẩn và quy chuẩn kỹ thuật.','Điều 34 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-283'),
(487,3,2,ARRAY['camera']::text[],'img/webcam-1.svg','Siêu thị lắp camera nơi công cộng. Họ phải làm gì (trừ khi luật định khác)?','["Giữ bí mật việc mình đang quay phim", "Chỉ quay phim vào ban đêm", "Thu tiền người bị ghi hình", "Thông báo để chủ thể dữ liệu biết mình đang bị ghi âm, ghi hình"]'::jsonb,3,'Quay ở nơi công cộng – phải thông báo cho mọi người biết.','Điều 32 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-284'),
(488,3,2,ARRAY['camera']::text[],'img/webcam-1.svg','Khi nào được ghi hình nơi công cộng mà không cần đồng ý?','["Để thực hiện nhiệm vụ quốc phòng, an ninh, trật tự xã hội", "Để trêu chọc người khác", "Để livestream bán hàng", "Để quay phim lén"]'::jsonb,0,'Nhiệm vụ quốc phòng, an ninh, trật tự xã hội.','Điều 32 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-285'),
(489,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Dữ liệu vân tay của khách bị xử lý gây thiệt hại. Tổ chức phải làm gì?','["Xóa dấu vết thiệt hại", "Im lặng xử lý nội bộ", "Bồi thường bằng hiện vật", "Thông báo cho chủ thể dữ liệu theo quy định"]'::jsonb,3,'Gây thiệt hại – phải thông báo cho chủ thể.','Điểm b khoản 4 Điều 31 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-286'),
(490,2,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Điện thoại của Cún Bông biết Cún đang ở đâu. "Dữ liệu vị trí cá nhân" xác định qua công nghệ nào?','["Công nghệ lọc nước", "Công nghệ in ấn", "Công nghệ định vị (GPS, RFID...)", "Công nghệ sinh học"]'::jsonb,2,'Định vị (GPS, RFID…) biết bạn ở đâu.','Khoản 1 Điều 31 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-287'),
(491,2,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','App mạng xã hội đòi ảnh căn cước để xác thực tài khoản. Theo luật?','["Số điện thoại", "Họ tên thật", "Email", "Hình ảnh, video chứa nội dung đầy đủ hoặc một phần giấy tờ tùy thân"]'::jsonb,3,'Không được đòi ảnh, video giấy tờ tùy thân để xác thực.','Khoản 2 Điều 29 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-288'),
(492,4,2,ARRAY['AI-deepfake']::text[],'img/deepfake-1.svg','Xử lý dữ liệu với AI, blockchain phải tuân thủ nguyên tắc gì?','["Xử lý để gây hại cho đối thủ", "Không cần tuân thủ luật", "Xử lý càng nhiều càng tốt", "Xử lý đúng mục đích, giới hạn phạm vi cần thiết"]'::jsonb,3,'Đúng mục đích, giới hạn phạm vi cần thiết.','Điều 30 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-289'),
(493,2,1,ARRAY['quyền riêng tư']::text[],'img/anhrieng.svg','Mạng xã hội nào dưới đây đang làm điều bị cấm (trừ khi luật định khác)?','["Nghe lén, ghi âm cuộc gọi và đọc tin nhắn khi không được đồng ý", "Cho phép đăng ảnh", "Hiển thị quảng cáo", "Cho phép kết bạn"]'::jsonb,0,'Nghe lén, đọc tin nhắn khi chưa được đồng ý – bị cấm.','Khoản 5 Điều 29 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-290'),
(494,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Số định danh cá nhân, số hộ chiếu thuộc loại dữ liệu nào?','["Dữ liệu nhạy cảm", "Dữ liệu công cộng", "Dữ liệu mật", "Dữ liệu cá nhân cơ bản"]'::jsonb,3,'Số định danh, hộ chiếu – dữ liệu cơ bản.','Khoản 2 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; khoản 7 Điều 3 Nghị định 356/2025/NĐ-CP','HHANM-291'),
(495,4,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Lực lượng bảo vệ dữ liệu cá nhân gồm những ai?','["Cơ quan chuyên trách Bộ Công an", "Bộ phận, nhân sự bảo vệ dữ liệu trong tổ chức", "Tổ chức cung cấp dịch vụ bảo vệ dữ liệu", "Tất cả các đối tượng trên"]'::jsonb,3,'Cơ quan chuyên trách, bộ phận trong tổ chức, đơn vị dịch vụ – đủ cả.','Điều 33 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-292'),
(496,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Cơ quan chuyên trách trả kết quả hồ sơ đánh giá tác động trong bao lâu?','["15 ngày", "20 ngày", "10 ngày", "07 ngày"]'::jsonb,0,'Trả kết quả trong 15 ngày.','Khoản 5 Điều 18, khoản 5 Điều 19 Nghị định 356/2025/NĐ-CP','HHANM-293'),
(497,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Hồ sơ đánh giá tác động chuyển dữ liệu xuyên biên giới nộp trong bao lâu từ lần chuyển đầu?','["30 ngày", "90 ngày", "60 ngày", "15 ngày"]'::jsonb,2,'60 ngày.','Điều 20 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-294'),
(498,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Báo cáo đánh giá tác động chuyển dữ liệu xuyên biên giới phải mô tả gì?','["Mục đích chuyển và loại dữ liệu chuyển", "Sơ đồ luồng xử lý dữ liệu", "Phương án bảo đảm an toàn dữ liệu", "Tất cả các nội dung trên"]'::jsonb,3,'Mục đích, sơ đồ luồng dữ liệu, phương án an toàn – đủ cả.','Điều 20 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Nghị định 356/2025/NĐ-CP ngày 31/12/2025 quy định chi tiết Luật Bảo vệ dữ liệu cá nhân','HHANM-295'),
(499,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Hồ sơ đánh giá tác động chuyển dữ liệu xuyên biên giới gồm tài liệu nào?','["Báo cáo đánh giá theo Mẫu số 09", "Bản sao hợp đồng chuyển giao dữ liệu", "Chính sách, quy trình bảo vệ dữ liệu", "Tất cả các tài liệu trên"]'::jsonb,3,'Báo cáo, hợp đồng, chính sách – đủ bộ.','Điều 20 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Nghị định 356/2025/NĐ-CP ngày 31/12/2025 quy định chi tiết Luật Bảo vệ dữ liệu cá nhân','HHANM-296'),
(500,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Ai có thẩm quyền yêu cầu ngừng chuyển dữ liệu ra nước ngoài khi có dấu hiệu xâm phạm an ninh quốc gia?','["Bộ Tài chính", "Cơ quan chuyên trách bảo vệ dữ liệu cá nhân", "Bộ Công Thương", "Ủy ban dân tộc"]'::jsonb,1,'Cơ quan chuyên trách bảo vệ dữ liệu cá nhân.','Điều 20 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-297'),
(501,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Hồ sơ năng lực của tổ chức dịch vụ bảo vệ dữ liệu phải thể hiện gì?','["Ngành nghề kinh doanh và kinh nghiệm", "Chính sách cung cấp dịch vụ", "Trình độ, năng lực nhân sự", "Tất cả các nội dung trên"]'::jsonb,3,'Ngành nghề, chính sách, năng lực nhân sự – đủ cả.','Khoản 2 Điều 16 Nghị định 356/2025/NĐ-CP','HHANM-298'),
(502,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Tổ chức dịch vụ bảo vệ dữ liệu phải có tối thiểu bao nhiêu nhân sự đủ điều kiện?','["05 nhân sự", "03 nhân sự", "01 nhân sự", "02 nhân sự"]'::jsonb,1,'Tối thiểu 3 nhân sự.','Điểm b khoản 1 Điều 16 Nghị định 356/2025/NĐ-CP','HHANM-299'),
(503,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Cá nhân làm dịch vụ bảo vệ dữ liệu (thuê ngoài) cần tối thiểu bao nhiêu năm kinh nghiệm?','["02 năm", "05 năm", "04 năm", "03 năm"]'::jsonb,3,'3 năm kinh nghiệm.','Điểm b khoản 2 Điều 15 Nghị định 356/2025/NĐ-CP','HHANM-300'),
(504,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Công ty Việt Nam lưu dữ liệu khách trên máy chủ ở nước ngoài. Đây có phải chuyển dữ liệu xuyên biên giới?','["Lưu trữ dữ liệu tại Việt Nam trên máy chủ đặt ngoài lãnh thổ VN", "Chuyển dữ liệu từ Việt Nam cho tổ chức ở nước ngoài", "Sử dụng nền tảng ngoài lãnh thổ VN để xử lý dữ liệu tại VN", "Tất cả các phương án trên"]'::jsonb,3,'Máy chủ ngoại, đối tác ngoại, nền tảng ngoại – đều là xuyên biên giới.','Điều 20 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-301'),
(505,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Cơ quan chức năng yêu cầu hoàn thiện hồ sơ đánh giá tác động. Có bao lâu?','["60 ngày", "45 ngày", "30 ngày", "15 ngày"]'::jsonb,2,'30 ngày để hoàn thiện.','Khoản 6 Điều 18, khoản 6 Điều 19 Nghị định 356/2025/NĐ-CP','HHANM-302'),
(506,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Hồ sơ đánh giá tác động xử lý dữ liệu cá nhân (nội bộ) nộp theo mẫu nào?','["Mẫu số 10", "Mẫu số 08", "Mẫu số 09", "Mẫu số 01a"]'::jsonb,0,'Mẫu số 10.','Điểm a khoản 2 Điều 19 và Mẫu số 10 Phụ lục Nghị định 356/2025/NĐ-CP','HHANM-303'),
(507,4,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Nhân sự bảo vệ dữ liệu được chỉ định phải có trình độ tối thiểu là gì?','["Đại học trở lên", "Sau đại học", "Trung cấp", "Cao đẳng trở lên"]'::jsonb,3,'Cao đẳng trở lên.','Điểm a khoản 2 Điều 13 Nghị định 356/2025/NĐ-CP','HHANM-304'),
(508,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Chỉ định nhân sự bảo vệ dữ liệu trong tổ chức phải bằng hình thức nào?','["Văn bản chính thức của cơ quan, tổ chức", "Thông báo trên bảng tin", "Thỏa thuận miệng", "Không cần văn bản"]'::jsonb,0,'Bằng văn bản chính thức.','Khoản 1 Điều 13 Nghị định 356/2025/NĐ-CP','HHANM-305'),
(509,3,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Hồ sơ khám bệnh và vân tay của bà nội thuộc loại dữ liệu nào?','["Dữ liệu cá nhân nhạy cảm", "Dữ liệu cơ bản", "Dữ liệu kinh doanh", "Dữ liệu không quan trọng"]'::jsonb,0,'Sức khỏe, sinh trắc – dữ liệu nhạy cảm.','Khoản 3 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; điểm d, điểm đ khoản 1 Điều 4 Nghị định 356/2025/NĐ-CP','HHANM-306'),
(510,3,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','"Quan điểm chính trị, tôn giáo" là dữ liệu nhạy cảm – đúng hay sai?','["Tùy vào người cung cấp", "Sai", "Đúng", "Chỉ là dữ liệu cơ bản"]'::jsonb,2,'Đúng – thuộc dữ liệu nhạy cảm.','Khoản 3 Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; điểm b khoản 1 Điều 4 Nghị định 356/2025/NĐ-CP','HHANM-307'),
(511,4,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Bộ phận bảo vệ dữ liệu cá nhân trong công ty có nhiệm vụ gì?','["Xây dựng chính sách, quy trình tuân thủ", "Triển khai thực hiện các quyền của chủ thể dữ liệu", "Lập hồ sơ đánh giá tác động", "Tất cả các nhiệm vụ trên"]'::jsonb,3,'Chính sách, quyền chủ thể, hồ sơ đánh giá – đủ cả.','Khoản 1 Điều 14 Nghị định 356/2025/NĐ-CP','HHANM-308'),
(512,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Kinh nghiệm ở lĩnh vực nào được tính cho nhân sự bảo vệ dữ liệu?','["Pháp chế, CNTT", "An ninh mạng, quản trị rủi ro", "Quản lý nhân sự, tổ chức cán bộ", "Tất cả các phương án trên"]'::jsonb,3,'Pháp chế, CNTT, ANM, rủi ro, nhân sự – đều tính.','Điểm b khoản 2 Điều 13 Nghị định 356/2025/NĐ-CP','HHANM-309'),
(513,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Nhân sự bảo vệ dữ liệu cần ít nhất bao nhiêu năm kinh nghiệm?','["02 năm", "01 năm", "03 năm", "05 năm"]'::jsonb,0,'2 năm.','Điểm b khoản 2 Điều 13 Nghị định 356/2025/NĐ-CP','HHANM-310'),
(514,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Trường hợp nào không phải đánh giá tác động chuyển dữ liệu xuyên biên giới?','["Hoạt động báo chí, truyền thông theo luật", "Tình huống khẩn cấp bảo vệ tính mạng", "Chuyển dữ liệu để xin thị thực, học bổng", "Tất cả các trường hợp trên"]'::jsonb,3,'Báo chí, cứu người khẩn cấp, xin visa/học bổng – đều miễn.','Điều 20 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Nghị định 356/2025/NĐ-CP ngày 31/12/2025 quy định chi tiết Luật Bảo vệ dữ liệu cá nhân','HHANM-311'),
(515,4,2,ARRAY['pháp luật']::text[],'img/luat-1.svg','Nghị định 13/2023 về bảo vệ dữ liệu cá nhân hết hiệu lực từ khi nào?','["Khi có Luật mới", "Ngày 01/01/2026", "Từ ngày Nghị định được ban hành (31/12/2025)", "Vẫn còn hiệu lực song song"]'::jsonb,1,'Từ 01/01/2026 – khi Luật BVDLCN có hiệu lực.','Điều 39 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-312'),
(516,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Doanh nghiệp siêu nhỏ xử lý dữ liệu của bao nhiêu người trở lên thì phải lập hồ sơ đánh giá tác động?','["100.000 trở lên (tích lũy tổng lượng dữ liệu đã xử lý)", "10000", "50000", "1000000"]'::jsonb,0,'Từ 100.000 chủ thể trở lên.','Khoản 3 Điều 38 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; khoản 2 Điều 41 Nghị định 356/2025/NĐ-CP','HHANM-313'),
(517,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Kinh phí bảo vệ dữ liệu cá nhân của cơ quan nhà nước lấy từ đâu?','["Do các công ty tài trợ", "Do nhân viên đóng góp", "Không có kinh phí", "Ngân sách nhà nước"]'::jsonb,3,'Ngân sách nhà nước.','Khoản 2 Điều 40 Nghị định 356/2025/NĐ-CP','HHANM-314'),
(518,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Giấy chứng nhận bị mất, hỏng – cấp lại trong bao lâu?','["03 ngày", "05 ngày", "10 ngày", "07 ngày"]'::jsonb,1,'5 ngày làm việc.','Điểm b khoản 1 Điều 26 Nghị định 356/2025/NĐ-CP','HHANM-315'),
(519,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Bị thu hồi Giấy chứng nhận, tổ chức phải nộp lại trong bao lâu?','["10 ngày làm việc", "07 ngày làm việc", "05 ngày làm việc", "03 ngày làm việc"]'::jsonb,2,'5 ngày làm việc.','Khoản 3 Điều 27 Nghị định 356/2025/NĐ-CP','HHANM-316'),
(520,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Tổ chức không kinh doanh dịch vụ bao lâu thì bị thu hồi Giấy chứng nhận?','["24 tháng", "06 tháng", "12 tháng", "18 tháng"]'::jsonb,2,'12 tháng không hoạt động – bị thu hồi.','Điểm b khoản 1 Điều 27 Nghị định 356/2025/NĐ-CP','HHANM-317'),
(521,4,1,ARRAY['báo cáo']::text[],'img/baocao-2.svg','Cổng thông tin quốc gia về bảo vệ dữ liệu cá nhân có chức năng gì?','["Tuyên truyền chính sách pháp luật", "Hỗ trợ, hướng dẫn kỹ năng bảo vệ dữ liệu", "Tiếp nhận phản ánh, kiến nghị vi phạm", "Tất cả các chức năng trên"]'::jsonb,3,'Tuyên truyền, hướng dẫn, nhận phản ánh – đủ cả.','Khoản 2 Điều 39 Nghị định 356/2025/NĐ-CP','HHANM-318'),
