(527,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Thẩm định và quyết định cấp Giấy chứng nhận kinh doanh dịch vụ xử lý dữ liệu trong bao lâu?','["45 ngày", "30 ngày", "20 ngày", "15 ngày"]'::jsonb,1,'30 ngày từ khi đủ hồ sơ.','Khoản 4 Điều 25 Nghị định 356/2025/NĐ-CP','HHANM-324'),
