(535,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Giấy chứng nhận đủ điều kiện kinh doanh dịch vụ xử lý dữ liệu được cấp dưới dạng nào?','["Văn bản thông báo", "Bản giấy và bản điện tử", "Chỉ bản điện tử", "Chỉ bản giấy"]'::jsonb,1,'Cả bản giấy và bản điện tử.','Khoản 4 Điều 25 Nghị định 356/2025/NĐ-CP','HHANM-332'),
(536,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Thời gian phản hồi tối đa cho chủ thể dữ liệu sau khi nhận yêu cầu thực hiện quyền?','["02 ngày làm việc", "10 ngày làm việc", "05 ngày làm việc", "Ngay lập tức"]'::jsonb,0,'2 ngày làm việc.','Khoản 5 Điều 4 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Nghị định 356/2025/NĐ-CP ngày 31/12/2025 quy định chi tiết Luật Bảo vệ dữ liệu cá nhân','HHANM-333'),
(537,3,2,ARRAY['camera']::text[],'img/webcam.svg','Khi nào ghi hình nơi công cộng không cần đồng ý?','["Bảo vệ an ninh quốc gia, trật tự xã hội", "Hội nghị, hội thảo, thi đấu thể thao công cộng", "Thực hiện nhiệm vụ quốc phòng", "Tất cả các trường hợp trên"]'::jsonb,3,'An ninh, sự kiện công cộng, nhiệm vụ quốc phòng – đều được.','Điều 32 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-334'),
(538,3,2,ARRAY['AI-deepfake']::text[],'img/deepfake.svg','Hệ thống AI dùng dữ liệu cá nhân bị cấm phát triển nếu gây hại đến đâu?','["Quốc phòng, an ninh quốc gia", "Trật tự, an toàn xã hội", "Danh dự, nhân phẩm, tài sản của người khác", "Tất cả các phương án trên"]'::jsonb,3,'Hại quốc phòng, trật tự xã hội, danh dự tài sản người khác – đều cấm.','Điều 30 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-335'),
(539,4,3,ARRAY['AI-deepfake']::text[],'img/deepfake.svg','Xử lý dữ liệu bằng AI phải phân loại theo tiêu chí nào?','["Theo dung lượng dữ liệu", "Theo mức độ rủi ro", "Theo giá thành hệ thống", "Theo số lượng người dùng"]'::jsonb,1,'Theo mức độ rủi ro.','Điều 30 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-336'),
(540,2,1,ARRAY['quyền riêng tư']::text[],'img/anhrieng.svg','Ứng dụng mạng xã hội không được ghi âm cuộc gọi của Mèo Mít nếu không có sự đồng ý của ai?','["Nhà cung cấp thiết bị", "Chủ thể dữ liệu cá nhân", "Cơ quan công an", "Không cần đồng ý của ai"]'::jsonb,1,'Của chính chủ thể dữ liệu – Mèo Mít.','Khoản 5 Điều 29 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-337'),
(541,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Dịch vụ quảng cáo có được thuê bên khác làm thay toàn bộ không?','["Chỉ khi thuê công ty trong nước", "Chỉ khi thuê công ty có vốn đầu tư nước ngoài", "Không được thuê lại hoặc thỏa thuận thực hiện toàn bộ", "Có"]'::jsonb,2,'Không được khoán trắng.','Điều 28 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-338'),
(542,2,1,ARRAY['tài khoản']::text[],'img/taikhoan-1.svg','Ngân hàng phải báo cho khách khi xảy ra chuyện gì với dữ liệu?','["Khi thay đổi lãi suất", "Khi mạng ngân hàng bị chậm", "Khi thay đổi mẫu thẻ", "Lộ, mất thông tin tài khoản, tín dụng"]'::jsonb,3,'Lộ, mất thông tin tài khoản, tín dụng.','Điều 27 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-339'),
(543,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Nhận yêu cầu xóa dữ liệu, bên kiểm soát làm trong bao nhiêu ngày?','["20 ngày", "07 ngày", "30 ngày", "15 ngày"]'::jsonb,0,'20 ngày.','Khoản 4 Điều 5 Nghị định 356/2025/NĐ-CP; Điều 14 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-340'),
(544,4,1,ARRAY['pháp luật']::text[],'img/luat-1.svg','Luật Bảo vệ dữ liệu cá nhân 2025 do Quốc hội khóa mấy thông qua? (Gợi ý: nhìn số hiệu 91/2025/QH15)','["Khóa XIV", "Khóa XIII", "Khóa XV", "Khóa XVI"]'::jsonb,2,'QH15 – Quốc hội khóa XV.','Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-341'),
(545,4,3,ARRAY['pháp luật']::text[],'img/luat.svg','Công ty X vi phạm bảo vệ dữ liệu (không phải mua bán hay chuyển ra nước ngoài). Mức phạt tối đa là bao nhiêu?','["3 tỷ đồng", "2 tỷ đồng", "5 tỷ đồng", "1 tỷ đồng"]'::jsonb,0,'Vi phạm khác – tối đa 3 tỷ đồng.','Điều 8 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-342'),
(546,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Yêu cầu ngừng xử lý dữ liệu của chủ thể dữ liệu quá phức tạp. Bên kiểm soát được gia hạn tối đa bao lâu?','["30 ngày", "10 ngày", "05 ngày", "15 ngày (không quá 01 lần)"]'::jsonb,3,'Gia hạn 15 ngày, chỉ 1 lần.','Khoản 2 Điều 5 Nghị định 356/2025/NĐ-CP; Điều 10 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-343'),
(547,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Công ty bảo hiểm xin bệnh viện hồ sơ sức khỏe của bác Tư. Bệnh viện chỉ được cung cấp khi nào?','["Có sự yêu cầu của công ty bảo hiểm", "Luôn luôn được cung cấp", "Có yêu cầu bằng văn bản của chủ thể dữ liệu", "Có sự đồng ý của giám đốc bệnh viện"]'::jsonb,2,'Chỉ khi chính chủ yêu cầu bằng văn bản.','Điều 26 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-344'),
(548,4,1,ARRAY['pháp luật']::text[],'img/luat-1.svg','Nghị định 356/2025/NĐ-CP hướng dẫn Luật BVDLCN có hiệu lực từ ngày nào?','["01/7/2026", "01/01/2026", "02/9/2026", "01/7/2025"]'::jsonb,1,'Cùng ngày với Luật – 01/01/2026.','Khoản 1 Điều 42 Nghị định 356/2025/NĐ-CP ngày 31/12/2025 quy định chi tiết Luật Bảo vệ dữ liệu cá nhân','HHANM-345'),
(549,3,2,ARRAY['camera']::text[],'img/webcam-1.svg','Camera ở công viên ghi hình mọi người. Dữ liệu được lưu bao lâu?','["10 năm", "Tùy vào dung lượng ổ cứng", "Vĩnh viễn", "Khoảng thời gian cần thiết để phục vụ mục đích thu thập"]'::jsonb,3,'Lưu vừa đủ thời gian cần cho mục đích.','Điều 32 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-346'),
(550,4,2,ARRAY['báo cáo']::text[],'img/baocao.svg','Thông báo vi phạm bảo vệ dữ liệu (Mẫu số 08) gồm những thông tin gì?','["Thời gian, địa điểm, hành vi vi phạm", "Các loại dữ liệu và số lượng bị ảnh hưởng", "Mô tả hậu quả và biện pháp khắc phục", "Tất cả các thông tin trên"]'::jsonb,3,'Thời gian, hành vi, dữ liệu ảnh hưởng, hậu quả – đủ cả.','Điều 23 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Nghị định 356/2025/NĐ-CP ngày 31/12/2025 quy định chi tiết Luật Bảo vệ dữ liệu cá nhân','HHANM-347'),
(551,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Dữ liệu vân tay khách hàng bị lộ. Phải báo cho chủ thể trong bao lâu?','["48 giờ", "72 giờ", "24 giờ", "05 ngày"]'::jsonb,1,'Sự cố sinh trắc – báo trong 72 giờ.','Điểm a khoản 1 Điều 29 Nghị định 356/2025/NĐ-CP; Điều 23, Điều 31 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-348'),
(552,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Hồ sơ vi phạm dữ liệu vị trí, sinh trắc phải lưu tối thiểu bao lâu?','["01 năm", "05 năm", "03 năm", "Vĩnh viễn"]'::jsonb,1,'Lưu 5 năm.','Điểm c khoản 1 Điều 29 Nghị định 356/2025/NĐ-CP','HHANM-349'),
(553,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Kiểm tra thường xuyên – cơ quan chuyên trách báo trước bao nhiêu ngày?','["07 ngày", "30 ngày", "15 ngày", "10 ngày"]'::jsonb,2,'Báo trước 15 ngày.','Khoản 4 Điều 31 Nghị định 356/2025/NĐ-CP','HHANM-350'),
(554,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-1.svg','Khi nào cơ quan chuyên trách được kiểm tra ngay không cần báo trước?','["Khi doanh nghiệp yêu cầu", "Kiểm tra định kỳ", "Kiểm tra đột xuất để ngăn chặn vi phạm", "Kiểm tra theo kế hoạch năm"]'::jsonb,2,'Đột xuất để ngăn chặn vi phạm.','Khoản 4 Điều 31 Nghị định 356/2025/NĐ-CP','HHANM-351'),
(555,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Nhân sự bảo vệ dữ liệu nội bộ cần ít nhất bao nhiêu năm kinh nghiệm?','["02 năm", "01 năm", "05 năm", "03 năm"]'::jsonb,0,'2 năm.','Điểm b khoản 2 Điều 13 Nghị định 356/2025/NĐ-CP','HHANM-352'),
(556,4,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Nhân sự bảo vệ dữ liệu nội bộ cần trình độ tối thiểu gì?','["Trung cấp", "Sau đại học", "Đại học chuyên ngành CNTT", "Cao đẳng trở lên"]'::jsonb,3,'Cao đẳng trở lên.','Điểm a khoản 2 Điều 13 Nghị định 356/2025/NĐ-CP','HHANM-353'),
(557,3,2,ARRAY['game']::text[],'img/game-2.svg','Trong metaverse, avatar của Bin lưu đầy lịch sử hành vi. Bin có quyền gì với hồ sơ nhận dạng của mình?','["Chỉ được xem hồ sơ", "Phải trả phí để xóa hồ sơ", "Không có quyền gì", "Quyền chỉnh sửa, ẩn danh, xóa hồ sơ (kể cả khi có lịch sử hành vi)"]'::jsonb,3,'Sửa, ẩn danh, xóa – kể cả có lịch sử hành vi.','Điều 30 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-354'),
(558,4,2,ARRAY['game']::text[],'img/game-1.svg','Metaverse (vũ trụ ảo) là gì?','["Một hệ thống lưu trữ đám mây", "Một mạng xã hội mới", "Một loại trò chơi điện tử", "Vũ trụ kỹ thuật số kết hợp truyền thông xã hội, AR, VR, Internet và tiền điện tử"]'::jsonb,3,'Vũ trụ số: mạng xã hội + AR/VR + Internet + tiền điện tử.','Điều 30 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-355'),
(559,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Doanh nghiệp giải thể, phá sản – cập nhật hồ sơ trong bao lâu?','["03 ngày", "05 ngày", "30 ngày", "10 ngày"]'::jsonb,3,'10 ngày.','Điều 22 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15; Nghị định 356/2025/NĐ-CP ngày 31/12/2025 quy định chi tiết Luật Bảo vệ dữ liệu cá nhân','HHANM-356'),
(560,3,2,ARRAY['camera']::text[],'img/webcam-1.svg','Dữ liệu từ camera nơi công cộng được lưu trữ bao lâu?','["Khoảng thời gian cần thiết để phục vụ mục đích thu thập", "01 tháng", "01 năm", "Vĩnh viễn"]'::jsonb,0,'Đủ thời gian cần thiết cho mục đích thu thập.','Điều 32 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-357'),
(561,3,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Dữ liệu đã khử nhận dạng thì không được tái nhận dạng – đúng hay sai?','["Sai", "Đúng (trừ trường hợp pháp luật có quy định khác)", "Tùy vào người xử lý", "Có thể tái nhận dạng tự do"]'::jsonb,1,'Đúng – đã khử thì không tái nhận dạng (trừ luật định khác).','Điều 14 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-358'),
(562,2,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Tèo sửa lại ngày sinh bị ghi nhầm trong hồ sơ. Việc chỉnh sửa phải bảo đảm điều gì?','["Tính chính xác", "Tính công khai", "Tính phổ biến", "Tính bảo mật"]'::jsonb,0,'Sửa dữ liệu – phải chính xác.','Điều 13 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-359'),
(563,4,2,ARRAY['pháp luật']::text[],'img/luat.svg','Danh mục dữ liệu cá nhân nhạy cảm do ai ban hành?','["Bộ Công an", "Quốc hội", "Chính phủ", "Bộ Thông tin và Truyền thông"]'::jsonb,2,'Chính phủ ban hành danh mục.','Điều 2 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-360'),
(564,3,2,ARRAY['mật khẩu']::text[],'img/matkhau-1.svg','Dữ liệu cá nhân đã mã hóa thành chuỗi loằng ngoằng – còn là dữ liệu cá nhân không?','["Trở thành dữ liệu công cộng", "Chỉ khi được giải mã xong", "Vẫn là dữ liệu cá nhân", "Không"]'::jsonb,2,'Mã hóa rồi vẫn là dữ liệu cá nhân.','Điều 12 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-361'),
(565,4,1,ARRAY['pháp luật']::text[],'img/luat.svg','Cơ quan Đảng, Nhà nước phân tích dữ liệu cá nhân để làm gì?','["Giải trí", "Kinh doanh", "Phục vụ công tác lãnh đạo, chỉ đạo, quản lý nhà nước, phát triển KT-XH", "Quảng cáo"]'::jsonb,2,'Phục vụ lãnh đạo, quản lý, phát triển kinh tế – xã hội.','Điều 11 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-362'),
(566,4,3,ARRAY['pháp luật']::text[],'img/luat.svg','Ai quy định cách tính khoản thu từ hành vi vi phạm pháp luật bảo vệ dữ liệu?','["Quốc hội", "Bộ Tài chính", "Chính phủ", "Bộ Công an"]'::jsonb,2,'Chính phủ quy định.','Điều 8 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-363'),
(567,3,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Mai muốn rút lại sự đồng ý cho app dùng dữ liệu. Phải làm bằng hình thức nào?','["Văn bản (bao gồm cả dạng điện tử hoặc định dạng kiểm chứng được)", "Nhờ người khác nói hộ", "Hành động im lặng", "Lời nói"]'::jsonb,0,'Rút đồng ý bằng văn bản (kể cả điện tử).','Điều 10 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-364'),
(568,1,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Ứng dụng hỏi: "Cho mình dùng ảnh của bạn nhé?" Ốc Sên không trả lời gì. Im lặng có phải là đồng ý không?','["Tùy trường hợp", "Chỉ đối với dữ liệu cơ bản", "Có", "Không được coi là sự đồng ý"]'::jsonb,3,'Im lặng không phải là đồng ý, nhớ kỹ!','Điểm d khoản 4 Điều 9 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-365'),
(569,2,1,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu-2.svg','Sự đồng ý của bạn cho app dùng dữ liệu có hiệu lực đến khi nào?','["Sau 5 năm", "Khi chủ thể dữ liệu thay đổi sự đồng ý hoặc theo pháp luật", "Sau 1 năm", "Vĩnh viễn"]'::jsonb,1,'Đến khi bạn đổi ý hoặc theo pháp luật.','Điều 9 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-366'),
(570,4,2,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Xử lý dữ liệu khẩn cấp để cứu người – ai phải chứng minh?','["Không cần chứng minh", "Cơ quan Công an", "Chủ thể dữ liệu", "Bên kiểm soát, bên xử lý hoặc bên thứ ba thực hiện"]'::jsonb,3,'Bên kiểm soát, bên xử lý hoặc bên thứ ba thực hiện.','Điều 19 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-367'),
(571,4,3,ARRAY['báo cáo']::text[],'img/baocao.svg','Mẫu số 04 tại Nghị định 356/2025 là văn bản gì?','["Báo cáo vi phạm", "Thông báo cập nhật hồ sơ", "Đơn đề nghị cấp Giấy chứng nhận đủ điều kiện kinh doanh dịch vụ", "Quyết định cấp phép"]'::jsonb,2,'Mẫu 04 – Đơn đề nghị cấp Giấy chứng nhận.','Điểm a khoản 1 Điều 25 và Mẫu số 04 Phụ lục Nghị định 356/2025/NĐ-CP','HHANM-368'),
(572,4,2,ARRAY['tài khoản']::text[],'img/taikhoan-1.svg','Tổ chức kinh doanh dịch vụ xử lý dữ liệu xác thực danh tính theo luật nào?','["Luật Đất đai", "Luật Giáo dục", "Pháp luật về định danh và xác thực điện tử", "Luật Hôn nhân"]'::jsonb,2,'Theo pháp luật về định danh và xác thực điện tử.','Khoản 8 Điều 23 Nghị định 356/2025/NĐ-CP','HHANM-369'),
(573,4,3,ARRAY['dữ liệu cá nhân']::text[],'img/dulieu.svg','Kiểm tra định kỳ chuyển dữ liệu xuyên biên giới tối đa mấy lần?','["Không quá 01 lần trong năm (trừ khi có vi phạm)", "Hàng tuần", "02 năm/lần", "1 tháng/lần"]'::jsonb,0,'Không quá 1 lần/năm (trừ khi vi phạm).','Điều 20 Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-370'),
(574,4,2,ARRAY['pháp luật']::text[],'img/luat.svg','Luật Bảo vệ dữ liệu cá nhân được thông qua tại kỳ họp thứ mấy của Quốc hội khóa XV?','["Kỳ họp thứ 8", "Kỳ họp thứ 11", "Kỳ họp thứ 10", "Kỳ họp thứ 9"]'::jsonb,3,'Kỳ họp thứ 9.','Luật Bảo vệ dữ liệu cá nhân số 91/2025/QH15','HHANM-371'),
